app = Flask(__name__)

# Fait confiance aux en-têtes envoyés par le reverse proxy Apache (192.168.1.75)
# afin que request.remote_addr, url_for(), redirect() et les cookies reflètent
# le client réel et non l'adresse/protocole vus par Apache.
# x_prefix=1 : lit X-Forwarded-Prefix ("/aprs") pour générer les URLs correctes
# une fois l'application servie sous https://f1riq.freeboxos.fr/aprs/
app.wsgi_app = ProxyFix(app.wsgi_app, x_for=1, x_proto=1, x_host=1, x_prefix=1)

# PATCH_SESSION_COOKIE_PREFIX_282 : Flask calcule le Path du cookie de
# session à partir d'une config STATIQUE (SESSION_COOKIE_PATH ou
# APPLICATION_ROOT), jamais depuis request.script_root -- même avec
# ProxyFix(x_prefix=1) qui pose bien SCRIPT_NAME="/aprs", le cookie partait
# toujours avec Path=/. On comptait sur Apache (ProxyPassReverseCookiePath)
# pour le réécrire, mais avec plusieurs apps (ft8/aprs/flrig) sur le même
# VirtualHost cette réécriture s'est révélée peu fiable (une règle en
# écrasait une autre selon l'ordre/l'imbrication des <Location>).
# On calcule donc le Path nous-mêmes, dynamiquement, par requête : "/aprs"
# quand servi derrière le proxy (script_root posé par ProxyFix), "/" en
# accès direct (tests locaux sur le port 5001). Plus besoin qu'Apache
# touche au Set-Cookie -- retirer ProxyPassReverseCookiePath du VirtualHost.
from flask.sessions import SecureCookieSessionInterface as _SCSI

# CORRIGÉ (boucle de login) : le Path du cookie dépendait de request.script_root,
# lui-même dérivé du header X-Forwarded-Prefix posé par Apache. Ce header n'arrive
# pas de façon fiable sur toutes les requêtes (constaté : Path=/ au lieu de /aprs
# sur un POST /login passé pourtant par le proxy), ce qui pouvait faire coexister
# deux cookies "session" à des Path différents et casser la session juste après
# une connexion réussie. On fixe donc le Path de secours à "/aprs" (préfixe réel
# de déploiement) au lieu de "/" -- le calcul dynamique via script_root reste
# utilisé quand le header est bien présent, donc rien ne change en accès direct
# local (http://192.168.1.75:5001/, script_root vide -> Path "/aprs" tout de
# même désormais, cohérent avec le seul mode d'accès réellement utilisé).
_DEPLOY_URL_PREFIX = "/aprs"

# PATCH_SESSION_COOKIE_PATH_FORCE_283 : request.script_root (dérivé du header
# X-Forwarded-Prefix posé par Apache) s'est révélé porter le préfixe d'une
# AUTRE app du même VirtualHost (observé : Path=/depot au lieu de /aprs).
# Plusieurs apps partageant le même vhost, ce header n'est pas une source
# fiable pour le Path du cookie -- on fixe donc /aprs en dur, sans jamais
# retomber sur script_root, quel que soit le contenu du header.
class _PrefixAwareSessionInterface(_SCSI):
    def get_cookie_path(self, app):
        return _DEPLOY_URL_PREFIX

app.session_interface = _PrefixAwareSessionInterface()

# ══════════════════════════════════════════════════════════════════════════════
# ── CAT_FREQ_PATCH_APPLIED ──
# Lecture autonome de la fréquence RX via CAT (protocole Yaesu, FT-897 & co.)
# Ouverture ponctuelle du port série à chaque lecture (pas de connexion
# permanente) afin de ne pas entrer en conflit avec Dire Wolf / PTT RTS-DTR
# qui peuvent utiliser un port série différent au même moment.
# ══════════════════════════════════════════════════════════════════════════════
_cat_lock = threading.Lock()
_cat_state = {
    "freq_hz": None,      # dernière fréquence lue (Hz), None si jamais lue / erreur
    "ok":      False,     # True si la dernière lecture a réussi
    "ts":      0.0,       # timestamp de la dernière lecture réussie
    "error":   None,      # dernier message d'erreur (si ok=False)
}

_cat_serial = {"ser": None, "port": None, "baudrate": None}
_cat_serial_lock = threading.Lock()

def _cat_get_connection():
    """
    Retourne une connexion série CAT persistante (ouverte une seule fois),
    ou la (re)crée si la config a changé / si la précédente est invalide.

    ── Pourquoi persistante ? ───────────────────────────────────────────────
    Sur la quasi-totalité des adaptateurs USB-série (CH340, PL2303, CP210x),
    ce n'est pas pyserial qui pose problème mais la puce elle-même : à CHAQUE
    fermeture puis réouverture du device, le firmware de la puce réinitialise
    ses lignes de contrôle (RTS/DTR), générant un sursaut matériel totalement
    indépendant de ce que fait le code Python. Comme cat_port peut être le
    même fil que la PTT Dire Wolf (RTS), rouvrir le port toutes les
    cat_poll_interval secondes revenait à déclencher une PTT fantôme à
    chaque cycle — même avec rts/dtr forcés à False avant open().
    La solution : n'ouvrir le port qu'UNE fois pour la durée de vie du
    process, et ne plus jamais le refermer entre deux lectures.
    """
    port     = config_manager.data.get("cat_port", "/dev/ttyUSB0").strip()
    baudrate = int(config_manager.data.get("cat_baudrate", 9600))
    if not port:
        raise RuntimeError("Port CAT non configuré")

    with _cat_serial_lock:
        ser = _cat_serial["ser"]
        # Config changée depuis la dernière ouverture -> on referme et recrée
        if ser is not None and (_cat_serial["port"] != port or _cat_serial["baudrate"] != baudrate):
            try:
                ser.close()
            except Exception:
                pass
            ser = None

        if ser is not None and not ser.is_open:
            ser = None

        if ser is None:
            ser = serial.Serial()
            ser.port      = port
            ser.baudrate  = baudrate
            ser.timeout   = 0.5
            ser.bytesize  = serial.EIGHTBITS
            ser.parity    = serial.PARITY_NONE
            ser.stopbits  = serial.STOPBITS_ONE
            ser.rtscts    = False
            ser.dsrdtr    = False
            ser.dtr       = False   # a positionner AVANT open()
            ser.rts       = False   # a positionner AVANT open()
            ser.open()
            logger.info("[CAT] Port série ouvert (persistant) : %s @ %d bauds", port, baudrate)
            _cat_serial["ser"]      = ser
            _cat_serial["port"]     = port
            _cat_serial["baudrate"] = baudrate

        return ser

def _cat_close_connection(reason=""):
    """Ferme et invalide la connexion CAT persistante (utilisé en cas d'erreur E/S)."""
    with _cat_serial_lock:
        ser = _cat_serial["ser"]
        if ser is not None:
            try:
                ser.close()
            except Exception:
                pass
        _cat_serial["ser"] = None
    if reason:
        logger.warning("[CAT] Connexion série fermée (%s) — réouverture au prochain poll", reason)

def _cat_read_frequency():
    """
    Envoie la commande CAT Yaesu 0x03 (lecture fréquence + mode) et retourne
    la fréquence en Hz, ou lève une exception en cas d'échec.

    Trame envoyée  : 00 00 00 00 03            (5 octets)
    Trame reçue    : F1 F2 F3 F4 MODE           (5 octets)
                      F1..F4 = fréquence en BCD, résolution 10 Hz

    Utilise la connexion série persistante (cf. _cat_get_connection) : le
    port n'est plus jamais fermé/rouvert entre deux lectures, ce qui élimine
    le sursaut RTS/DTR matériel responsable des PTT intempestifs.
    """
    ser = _cat_get_connection()
    try:
        with _cat_serial_lock:
            ser.reset_input_buffer()
            ser.write(bytes([0x00, 0x00, 0x00, 0x00, 0x03]))
            resp = ser.read(5)
    except Exception as e:
        # Port débranché / erreur E/S : on invalide la connexion pour forcer
        # une réouverture propre au prochain cycle, plutot que de rester bloqué.
        _cat_close_connection(reason=str(e))
        raise

    if len(resp) != 5:
        raise RuntimeError("Réponse CAT incomplète (%d octet(s) reçu(s))" % len(resp))

    # Chaque octet de fréquence contient 2 chiffres BCD (0-9 par nibble)
    digits = "".join("%02X" % b for b in resp[0:4])
    try:
        freq_val = int(digits)
    except ValueError:
        raise RuntimeError("Trame CAT invalide : %s" % resp.hex())

    return freq_val * 10   # résolution 10 Hz → Hz


def _cat_poll_worker():
    """Thread daemon : interroge périodiquement la radio en CAT pour la fréquence RX."""
    _cat_p  = config_manager.data.get("cat_port", "").strip()
    _ptt_p  = config_manager.data.get("serial_port", "").strip()
    if _cat_p and _cat_p == _ptt_p:
        logger.warning(
            "[CAT] cat_port et serial_port (PTT Dire Wolf) pointent sur le meme "
            "peripherique (%s). Le correctif rts/dtr=False-avant-open evite le "
            "sursaut PTT au moment de l'ouverture, mais deux process (ce script "
            "et direwolf) qui ouvrent/ferment la meme ligne serie restent fragiles. "
            "Prefer un port dedie au CAT si possible.", _cat_p)
    while True:
        interval = max(1, int(config_manager.data.get("cat_poll_interval", 3)))
        if not config_manager.data.get("cat_enabled", True):
            time.sleep(interval)
            continue
        try:
            freq_hz = _cat_read_frequency()
            with _cat_lock:
                _cat_state["freq_hz"] = freq_hz
                _cat_state["ok"]      = True
                _cat_state["ts"]      = time.time()
                _cat_state["error"]   = None
        except Exception as _e:
            with _cat_lock:
                _cat_state["ok"]    = False
                _cat_state["error"] = str(_e)
            logger.debug("[CAT] Lecture fréquence échouée : %s", _e)
        time.sleep(interval)


# ── SYS_STATS_CPU_RAM_VOLT_PATCH_APPLIED : CPU / RAM / tension d'alimentation ──
import subprocess as _sys_stats_subprocess

_sys_stats_prev_cpu = {"total": None, "idle": None}
_sys_stats_lock = threading.Lock()


def _sys_stats_read_cpu_percent():
    """Calcule le %CPU depuis /proc/stat (delta entre deux appels)."""
    try:
        with open("/proc/stat", "r") as f:
            parts = f.readline().split()
        # cpu  user nice system idle iowait irq softirq steal guest guest_nice
        values = [int(v) for v in parts[1:]]
        idle = values[3] + values[4]
        total = sum(values)
        with _sys_stats_lock:
            prev_total = _sys_stats_prev_cpu["total"]
            prev_idle = _sys_stats_prev_cpu["idle"]
            _sys_stats_prev_cpu["total"] = total
            _sys_stats_prev_cpu["idle"] = idle
        if prev_total is None:
            return None
        d_total = total - prev_total
        d_idle = idle - prev_idle
        if d_total <= 0:
            return None
        return round(100.0 * (d_total - d_idle) / d_total, 1)
    except Exception:
        return None


def _sys_stats_read_ram_percent():
    """Calcule le %RAM utilisée depuis /proc/meminfo."""
    try:
        meminfo = {}
        with open("/proc/meminfo", "r") as f:
            for line in f:
                key, _, rest = line.partition(":")
                meminfo[key.strip()] = int(rest.strip().split()[0])  # kB
        total_kb = meminfo.get("MemTotal")
        avail_kb = meminfo.get("MemAvailable")
        if not total_kb or avail_kb is None:
            return None, None, None
        used_kb = total_kb - avail_kb
        percent = round(100.0 * used_kb / total_kb, 1)
        return percent, round(used_kb / 1024, 0), round(total_kb / 1024, 0)
    except Exception:
        return None, None, None


def _sys_stats_read_voltage():
    """Lit la tension noyau (vcgencmd) et le statut undervoltage sur Raspberry Pi."""
    volts = None
    undervoltage = None
    try:
        out = _sys_stats_subprocess.check_output(
            ["vcgencmd", "measure_volts", "core"],
            stderr=_sys_stats_subprocess.DEVNULL, timeout=2
        ).decode().strip()
        # format : "volt=1.2000V"
        m = re.search(r"volt=([\d.]+)V", out)
        if m:
            volts = float(m.group(1))
    except Exception:
        pass
    try:
        out = _sys_stats_subprocess.check_output(
            ["vcgencmd", "get_throttled"],
            stderr=_sys_stats_subprocess.DEVNULL, timeout=2
        ).decode().strip()
        # format : "throttled=0x50000"
        m = re.search(r"0x([0-9a-fA-F]+)", out)
        if m:
            flags = int(m.group(1), 16)
            undervoltage = bool(flags & 0x1)  # bit 0 = undervoltage détectée actuellement
    except Exception:
        pass
    return volts, undervoltage


def _sys_stats_read_temp():
    """Température SoC (°C) : thermal_zone0, sinon vcgencmd measure_temp."""
    try:
        with open("/sys/class/thermal/thermal_zone0/temp") as f:
            return round(int(f.read().strip()) / 1000.0, 1)
    except Exception:
        pass
    try:
        out = _sys_stats_subprocess.check_output(
            ["vcgencmd", "measure_temp"], stderr=_sys_stats_subprocess.DEVNULL, timeout=2).decode()
        m = re.search(r"temp=([\d.]+)", out)
        return float(m.group(1)) if m else None
    except Exception:
        return None


def _sys_stats_read_disk():
    """Occupation de la partition qui porte l'application (carte SD) : % utilisé, Go libres."""
    try:
        du = shutil.disk_usage(BASE_DIR)
        return round(100.0 * du.used / du.total, 1), round(du.free / 1e9, 1)
    except Exception:
        return None, None


@app.route('/sys_stats')
def sys_stats():
    """Retourne CPU %, RAM % et tension d'alimentation (JSON)."""
    cpu_percent = _sys_stats_read_cpu_percent()
    ram_percent, ram_used_mb, ram_total_mb = _sys_stats_read_ram_percent()
    volts, undervoltage = _sys_stats_read_voltage()
    temp_c = _sys_stats_read_temp()
    disk_percent, disk_free_gb = _sys_stats_read_disk()
    return jsonify({
        "temp_c":        temp_c,
        "disk_percent":  disk_percent,
        "disk_free_gb":  disk_free_gb,
        "cpu_percent":   cpu_percent,
        "ram_percent":   ram_percent,
        "ram_used_mb":   ram_used_mb,
        "ram_total_mb":  ram_total_mb,
        "volts":         volts,
        "undervoltage":  undervoltage,
    })


@app.route('/cat_freq')
def cat_freq():
    """Retourne la dernière fréquence RX lue en CAT (JSON)."""
    with _cat_lock:
        freq_hz = _cat_state["freq_hz"]
        return jsonify({
            "ok":       _cat_state["ok"],
            "freq_hz":  freq_hz,
            "freq_mhz": round(freq_hz / 1e6, 3) if freq_hz else None,
            "age_s":    round(time.time() - _cat_state["ts"], 1) if _cat_state["ts"] else None,
            "error":    _cat_state["error"],
        })

