# ── LOGIN_PATCH_APPLIED (simplifié) ──
# Protection par simple passphrase (plus de comptes / identifiants)
# ══════════════════════════════════════════════════════════════════════════════
import secrets as _secrets
from werkzeug.security import generate_password_hash as _gen_hash, \
                              check_password_hash   as _chk_hash
from functools import wraps as _wraps

_PASSPHRASE_FILE    = os.path.join(BASE_DIR, "passphrase.json")
_DEFAULT_PASSPHRASE = "aprs1200"

# Clé secrète Flask (persistante entre redémarrages)
_SECRET_KEY_FILE = os.path.join(BASE_DIR, ".flask_secret")
if os.path.exists(_SECRET_KEY_FILE):
    with open(_SECRET_KEY_FILE) as _f:
        app.secret_key = _f.read().strip()
else:
    app.secret_key = _secrets.token_hex(32)
    with open(_SECRET_KEY_FILE, "w") as _f:
        _f.write(app.secret_key)

# ── Gestion passphrase.json ───────────────────────────────────────────────────

def _load_passphrase_hash():
    if os.path.exists(_PASSPHRASE_FILE):
        try:
            with open(_PASSPHRASE_FILE, "r", encoding="utf-8") as _f:
                return json.load(_f).get("hash")
        except Exception:
            pass
    # Créer la passphrase par défaut
    ph = _gen_hash(_DEFAULT_PASSPHRASE)
    _save_passphrase_hash(ph)
    logger.info("[AUTH] Fichier passphrase.json créé avec la passphrase par défaut (aprs1200)")
    return ph

def _save_passphrase_hash(ph):
    tmp = _PASSPHRASE_FILE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as _f:
        json.dump({"hash": ph}, _f, ensure_ascii=False, indent=2)
    os.replace(tmp, _PASSPHRASE_FILE)

_passphrase_hash = _load_passphrase_hash()

# ── Décorateur de protection des routes ──────────────────────────────────────

def _login_required(f):
    @_wraps(f)
    def _decorated(*args, **kwargs):
        if not session.get("logged_in"):
            # SSE (EventSource) : retourner 401, pas une redirection HTML
            if request.headers.get("Accept", "").startswith("text/event-stream"):
                return Response("data: {\"type\":\"auth_required\"}\n\n",
                                status=401, mimetype="text/event-stream")
            # Requêtes JSON/API
            if request.is_json or request.headers.get("X-Requested-With") == "XMLHttpRequest":
                return jsonify({"error": "Non authentifié", "redirect": url_for("login")}), 401
            return redirect(url_for("login", next=request.path))
        return f(*args, **kwargs)
    return _decorated

