# PATCH_LOGIN_RATELIMIT_278 ──────────────────────────────────────────────────
# L'appli écoute sur 0.0.0.0:5001, donc accessible à tout le réseau local
# (et au-delà en cas de NAT/port-forward). Sans limite, /login est ouvert au
# bruteforce. Verrouillage par IP avec backoff exponentiel : 5 échecs en 5 min
# -> verrouillage 30s, doublé à chaque nouveau déclenchement (plafond 30 min).
_login_lock       = threading.Lock()
_login_attempts    = {}   # ip -> {"fails", "window_start", "locked_until", "lockout_count"}
_LOGIN_MAX_FAILS   = 5
_LOGIN_WINDOW_SEC  = 300
_LOGIN_BASE_LOCKOUT = 30
_LOGIN_MAX_LOCKOUT  = 1800

def _login_check_rate_limit(ip):
    """Retourne (autorisé: bool, secondes_avant_reessai: int|None)."""
    now = time.time()
    with _login_lock:
        rec = _login_attempts.get(ip)
        if rec and rec["locked_until"] > now:
            return False, int(rec["locked_until"] - now) + 1
        return True, None

def _login_register_failure(ip):
    now = time.time()
    with _login_lock:
        rec = _login_attempts.setdefault(ip, {
            "fails": 0, "window_start": now, "locked_until": 0, "lockout_count": 0
        })
        if now - rec["window_start"] > _LOGIN_WINDOW_SEC:
            rec["fails"] = 0
            rec["window_start"] = now
        rec["fails"] += 1
        if rec["fails"] >= _LOGIN_MAX_FAILS:
            rec["lockout_count"] += 1
            lockout = min(_LOGIN_BASE_LOCKOUT * (2 ** (rec["lockout_count"] - 1)), _LOGIN_MAX_LOCKOUT)
            rec["locked_until"] = now + lockout
            rec["fails"] = 0
            rec["window_start"] = now
            logger.warning("[AUTH] IP %s verrouillée %ds après trop d'échecs (verrouillage n°%d)",
                            ip, lockout, rec["lockout_count"])
        # Purge opportuniste des entrées anciennes et inactives (évite une
        # croissance non bornée du dict en cas de scan depuis de nombreuses IP)
        if len(_login_attempts) > 500:
            stale = [k for k, v in _login_attempts.items()
                     if v["locked_until"] < now and now - v["window_start"] > 3600]
            for k in stale:
                _login_attempts.pop(k, None)

def _login_register_success(ip):
    with _login_lock:
        _login_attempts.pop(ip, None)

def _prefixed_next(next_url):
    """Reconstruit une URL de redirection interne en tenant compte du préfixe
    (/aprs) éventuellement ajouté par ProxyFix (X-Forwarded-Prefix). `next_url`
    est stocké relatif à la racine de l'appli (sans préfixe), il faut donc le
    recombiner avec request.script_root avant tout redirect()."""
    if not next_url or next_url == "/":
        return url_for("index")
    if not next_url.startswith("/"):
        return url_for("index")
    prefix = request.script_root or ""
    if prefix and next_url.startswith(prefix + "/"):
        return next_url
    return prefix + next_url


@app.route('/login', methods=['GET', 'POST'])
def login():
    next_url = request.args.get("next", "/")
    err = ""
    client_ip = request.remote_addr or "?"

    allowed, retry_after = _login_check_rate_limit(client_ip)
    if not allowed:
        err = "Trop de tentatives échouées. Réessayez dans %ds." % retry_after
        html = _LOGIN_HTML.replace("{ERR_CLASS}", "show") \
                          .replace("{ERR_MSG}",   err) \
                          .replace("{NEXT}",      next_url) \
                          .replace("{LOGIN_ACTION}", url_for("login")) \
                          .replace("{VERSION}",   APP_VERSION)
        return Response(html, mimetype="text/html", status=429)

    if request.method == "POST":
        next_url   = request.form.get("next", "/")
        passphrase = request.form.get("passphrase", "")
        if _passphrase_hash and _chk_hash(_passphrase_hash, passphrase):
            _login_register_success(client_ip)
            session.permanent = True
            session["logged_in"] = True
            logger.info("[AUTH] Connexion réussie")
            return redirect(_prefixed_next(next_url))
        _login_register_failure(client_ip)
        err = "Passphrase incorrecte."
        logger.warning("[AUTH] Échec connexion (IP %s)", client_ip)
    html = _LOGIN_HTML.replace("{ERR_CLASS}", "show" if err else "") \
                      .replace("{ERR_MSG}",   err) \
                      .replace("{NEXT}",      next_url) \
                      .replace("{LOGIN_ACTION}", url_for("login")) \
                      .replace("{VERSION}",   APP_VERSION)
    return Response(html, mimetype="text/html", status=200 if not err else 401)

# ── TRX_FREQ_BUTTONS_v1_APPLIED : réglage de la fréquence TRX en CAT ─────────
_CAT_PRESETS_MHZ = (144.800, 145.825)   # APRS France, ISS


def _cat_write_frequency(freq_hz):
    """Commande CAT Yaesu 0x01 : F1 F2 F3 F4 01 (BCD, résolution 10 Hz)."""
    digits = "%08d" % int(round(freq_hz / 10.0))
    frame = bytes(int(digits[i:i + 2], 16) for i in (0, 2, 4, 6)) + b"\x01"
    ser = _cat_get_connection()
    try:
        with _cat_serial_lock:
            ser.reset_input_buffer()
            ser.write(frame)
            ser.flush()
            time.sleep(0.1)
            ser.reset_input_buffer()   # le FT-897 peut acquitter (1 octet)
    except Exception as e:
        _cat_close_connection(reason=str(e))
        raise


@app.route('/cat_set_freq', methods=['POST'])
@_login_required
def cat_set_freq():
    data = request.get_json(silent=True) or {}
    try:
        mhz = round(float(data.get("freq_mhz")), 3)
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "Fréquence invalide"}), 400
    if mhz not in _CAT_PRESETS_MHZ:
        return jsonify({"ok": False, "error": "Fréquence non autorisée"}), 400
    if not config_manager.data.get("cat_enabled", True):
        return jsonify({"ok": False, "error": "CAT désactivé"}), 409
    try:
        _cat_write_frequency(mhz * 1e6)
    except Exception as e:
        logger.warning("[CAT] Réglage %.3f MHz échoué : %s", mhz, e)
        return jsonify({"ok": False, "error": str(e)[:120]}), 500
    with _cat_lock:
        _cat_state["freq_hz"] = int(round(mhz * 1e6))
        _cat_state["ok"] = True
        _cat_state["ts"] = time.time()
        _cat_state["error"] = None
    logger.info("[CAT] TRX réglé sur %.3f MHz", mhz)
    return jsonify({"ok": True, "freq_mhz": mhz})


@app.route('/logout')
def logout():
    session.clear()
    logger.info("[AUTH] Déconnexion")
    return redirect(url_for("login"))

@app.route('/auth/attempts')
@_login_required
def auth_attempts():
    """Expose l'etat courant du verrouillage anti-bruteforce par IP."""
    now = time.time()
    result = []
    with _login_lock:
        for ip, rec in _login_attempts.items():
            locked = rec["locked_until"] > now
            result.append({
                "ip": ip,
                "fails": rec["fails"],
                "lockout_count": rec["lockout_count"],
                "locked": locked,
                "retry_after": int(rec["locked_until"] - now) + 1 if locked else 0,
            })
    result.sort(key=lambda r: (-r["locked"], -r["fails"]))
    return jsonify({"attempts": result})

# ── Changement de la passphrase ───────────────────────────────────────────────

@app.route('/auth/change_password', methods=['POST'])
def auth_change_password():
    global _passphrase_hash
    if not session.get("logged_in"):
        return jsonify({"error": "Non authentifié"}), 401
    data = request.json or {}
    current  = data.get("current_password", "")
    new_pass = data.get("new_password", "").strip()
    if not _passphrase_hash or not _chk_hash(_passphrase_hash, current):
        return jsonify({"ok": False, "error": "Passphrase actuelle incorrecte"}), 403
    if len(new_pass) < 6:
        return jsonify({"ok": False, "error": "La passphrase doit faire au moins 6 caractères"}), 400
    _passphrase_hash = _gen_hash(new_pass)
    _save_passphrase_hash(_passphrase_hash)
    logger.info("[AUTH] Passphrase changée")
    return jsonify({"ok": True})

@app.route('/auth/whoami')
def auth_whoami():
    return jsonify({
        "logged_in": bool(session.get("logged_in")),
    })

