        noms = ["Lundi", "Mardi", "Mercredi", "Jeudi", "Vendredi", "Samedi", "Dimanche"]
        lettres = ["L", "M", "M", "J", "V", "S", "D"]
        pills = "".join([
            '<label class="cursor-pointer" title="%s">'
            '<input type="checkbox" class="hidden peer bln-day" data-prefix="%s" data-day="%d"%s>'
            '<span class="peer-checked:bg-amber-600/70 peer-checked:text-white peer-checked:border-amber-500 '
            'bg-slate-800/50 text-slate-500 border border-slate-700 rounded-md '
            'w-5 h-5 flex items-center justify-center text-[9px] font-bold transition-all">%s</span>'
            '</label>' % (noms[i], prefix, i, ' checked' if i in cur_days else '', lettres[i])
            for i in range(7)
        ])
        return '<div class="flex gap-1">' + pills + '</div>'

