@app.route('/manifest.webmanifest')
def pwa_manifest():
    """Manifest PWA : URLs relatives (start_url, scope, icônes) pour rester valable
    derrière le préfixe Apache /aprs comme en accès direct sur le port 5001."""
    from flask import Response as _R
    data = {
        "id": "./",
        "name": "Py-APRS Station de Contrôle",
        "short_name": "Py-APRS",
        "description": "Station APRS : moniteur de trafic, carte, propagation",
        "start_url": "./",
        "scope": "./",
        "display": "standalone",
        "orientation": "any",
        "background_color": "#020617",
        "theme_color": "#020617",
        "lang": "fr",
        "icons": [
            {"src": "icon-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any"},
            {"src": "icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any"},
            {"src": "icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "maskable"},
        ],
        "shortcuts": [
            {"name": "Moniteur viewer", "short_name": "Viewer", "url": "./?viewer=1",
             "icons": [{"src": "icon-192.png", "sizes": "192x192", "type": "image/png"}]},
            {"name": "Viewer sans header", "short_name": "Sans header", "url": "./?viewer=2",
             "icons": [{"src": "icon-192.png", "sizes": "192x192", "type": "image/png"}]},
        ],
    }
    return _R(json.dumps(data, ensure_ascii=False), mimetype='application/manifest+json',
              headers={'Cache-Control': 'no-cache'})


