@app.route('/chat/send', methods=['POST'])
@_login_required
def chat_send():
    data  = request.get_json(silent=True) or {}
    dest  = (data.get('dest') or '').upper().strip()
    text  = (data.get('text') or '').strip()
    if not dest or not text:
        return jsonify({"error": "dest/text requis"}), 400
    if len(dest) > 9:
        # Le champ adressé d'un message APRS fait 9 caractères (aprs101 §14)
        return jsonify({"error": "destinataire trop long (9 car. max)"}), 400
    msgno   = chat_manager._next_msgno()
    # APRS_MSGNO_SPEC_FIX_v1 : pas d'accolade fermante — cf. _ack_retry_worker.
    # PATCH_MSG_LEN_LIMIT_FIX_v1 : la limite APRS de 67 car. (aprs101 §14)
    # porte sur texte + "{msgno}" au total. L'ancien code tronquait le
    # texte a 67 car. AVANT d'ajouter "{msgno}", d'ou des messages jusqu'a
    # 6 car. trop longs (ex: 65 + "{28" = 68 car.) -> rejetes/tronques par
    # certains materiels stricts (portatifs), qui ne renvoyaient alors
    # jamais d'ACK.
    text = text[:67 - len("{" + msgno)]
    payload = ":" + dest.ljust(9) + ":" + text + "{" + msgno
    # via_igate : envoi direct sur APRS-IS (TCPIP*) au lieu du RF via le
    # modem/TNC. Utile si le message est destiné à une station jointe
    # uniquement via Internet, ou si le TNC/modem RF n'est pas disponible.
    via_igate = bool(data.get('via_igate'))
    if via_igate:
        if not igate_client.connected:
            return jsonify({"status": "error",
                             "error": "iGate non connecté à APRS-IS"}), 503
        chat_manager.add_outgoing(dest, text, msgno, via="is")
        ok = igate_client.send_is(payload)
        if not ok:
            return jsonify({"status": "error",
                             "error": "Échec envoi APRS-IS"}), 503
        return jsonify({"status": "queued", "msgno": msgno, "via": "is"})
    chat_manager.add_outgoing(dest, text, msgno, via="rf")
    # custom_path : permet de forcer ARISS pour les messages ISS
    custom_path = (data.get('custom_path') or '').strip() or None
    try:
        tx_queue.put_nowait({
            "dest": "APRS", "payload": payload, "path": custom_path,
            "aprs_type": "Message", "extra": {"comment": text, "msg_dest": dest}
        })
        return jsonify({"status": "queued", "msgno": msgno, "via": "rf"})
    except queue.Full:
        return jsonify({"status": "busy"}), 429

@app.route('/chat/delete/<callsign>', methods=['DELETE'])
@_login_required
def chat_delete(callsign):
    """Supprime toute la conversation avec un indicatif."""
    cs = callsign.upper().strip()
    if not cs:
        return jsonify({"error": "indicatif requis"}), 400
    deleted = chat_manager.delete_conversation(cs)
    if deleted:
        logger.info("[QSO] Conversation supprimée : %s", cs)
        return jsonify({"ok": True, "callsign": cs})
    return jsonify({"ok": False, "error": "conversation introuvable"}), 404

