@app.route('/lightning_strikes')
@_login_required
def lightning_strikes_route():
    cfg = dict(DEFAULT_CONFIG["lightning_strikes"])
    cfg.update(config_manager.data.get("lightning_strikes") or {})
    _lightning_prune(time.time(), float(cfg.get("retention_min", 180)))
    with _lightning_lock:
        strikes = list(_lightning_strikes)
    try:   # LTG_MAP_v1 : la carte demande davantage d'impacts (défaut 200, max 1500)
        _lim = max(1, min(1500, int(request.args.get("limit", "200"))))
    except ValueError:
        _lim = 200
    now = time.time()
    last_10min = sum(1 for s in strikes if now - s["time"] <= 600)
    last_60min = sum(1 for s in strikes if now - s["time"] <= 3600)
    nearest = min((s["dist_km"] for s in strikes), default=None)
    return json.dumps({
        "enabled":        bool(cfg.get("enabled")),
        "connected":       _lightning_status["connected"],
        "server":          _lightning_status["server"],
        "error":           _lightning_status["error"],
        "radius_km":       cfg.get("radius_km"),
        "count_10min":     last_10min,
        "count_60min":     last_60min,
        "nearest_km":      nearest,
        "last_strike_ts":  _lightning_status["last_strike_ts"],
        "strikes":         sorted(strikes, key=lambda s: -s["time"])[:_lim],
    }, ensure_ascii=False), 200, {'Content-Type': 'application/json'}


def _rx_broadcaster():
    def my_calls():
        """Retourne la liste des variantes acceptables : F1RIQ, F1RIQ-9, etc."""
        full = config_manager.data.get("callsign", "").upper().strip()
        base = full.split("-")[0]
        return {full, base}

    while True:
        try:
            frame = APRSModem.rx_queue.get(timeout=1)

            # ── Capture métadonnées télémétrie (messages PARM/UNIT/EQNS/BITS) ─
            if frame.get("aprs_type") == "Message" and frame.get("type") != "rx_level":
                _extra = frame.get("extra", {})
                _src   = frame.get("src", "").upper().strip()
                _body  = _extra.get("msg_text", "")
                if _body.startswith("PARM."):
                    with _telem_meta_lock:
                        _telem_meta.setdefault(_src, {})["parm"] = _parse_telem_parm(_body[5:])
                    logger.debug("[TELEM] PARM recu de %s", _src)
                elif _body.startswith("UNIT."):
                    with _telem_meta_lock:
                        _telem_meta.setdefault(_src, {})["unit"] = _parse_telem_parm(_body[5:])
                    logger.debug("[TELEM] UNIT recu de %s", _src)
                elif _body.startswith("EQNS."):
                    with _telem_meta_lock:
                        _telem_meta.setdefault(_src, {})["eqns"] = _parse_telem_eqns(_body[5:])
                    logger.debug("[TELEM] EQNS recu de %s", _src)
                elif _body.startswith("BITS."):
                    parts_b = _body[5:].split(',', 9)
                    with _telem_meta_lock:
                        meta = _telem_meta.setdefault(_src, {})
                        meta["bits_mask"]  = parts_b[0].strip() if parts_b else ""
                        meta["bits_label"] = parts_b[1].strip() if len(parts_b) > 1 else ""
                        meta["bits_names"] = [p.strip() for p in parts_b[2:10]]
                    logger.debug("[TELEM] BITS recu de %s", _src)

            # ── Enrichissement des trames Télémétrie avec PARM/UNIT/EQNS ────
            if frame.get("aprs_type") == "Telemetrie":
                src  = frame.get("src", "").upper().strip()
                with _telem_meta_lock:
                    meta = _telem_meta.get(src, {})
                extra = frame.get("extra", {})
                parm  = meta.get("parm", [])
                unit  = meta.get("unit", [])
                eqns  = meta.get("eqns", [])
                bits_names = meta.get("bits_names", [])
                raw_vals   = extra.get("telem_analog_raw", extra.get("telem_analog", []))

                # Calcul des valeurs mises à l'échelle via EQNS
                scaled = []
                for i, rv in enumerate(raw_vals):
                    if rv is None:
                        scaled.append(None)
                    elif i < len(eqns):
                        scaled.append(_apply_eqns(rv, eqns[i]))
                    else:
                        scaled.append(float(rv))
                extra["telem_analog"] = scaled

                # Noms et unités (5 analogiques)
                extra["telem_names"] = parm[:5]   if parm else []
                extra["telem_units"] = unit[:5]   if unit else []

                # Bits numériques nommés
                bits_str = extra.get("telem_bits", "")
                named_bits = []
                for i, bit_char in enumerate(bits_str[:8]):
                    name = bits_names[i] if i < len(bits_names) else ("B%d" % (i+1))
                    named_bits.append({"name": name, "val": bit_char == "1"})
                extra["telem_named_bits"] = named_bits

                frame["extra"] = extra

            if frame.get("aprs_type") == "Message" and frame.get("type") != "rx_level":
                extra = frame.get("extra", {})
                dest  = extra.get("msg_dest", "").upper().strip()
                src   = frame.get("src", "").upper().strip()
                text  = extra.get("msg_text", "")
                msgno = extra.get("msg_msgno")
                ackto = extra.get("msg_ackno")

                if extra.get("msg_ack") == "REJ" and ackto:
                    # REJ_FIX_v1 : rejN = refus du message, PAS un accusé de réception
                    found_dest, found_msgno = chat_manager.mark_rej(ackto)
                    logger.warning("[MSG] REJ recu pour msgno=%s de %s (message refuse)", ackto, src)
                    if found_dest:
                        rej_event = {"type": "msg_rej", "msgno": found_msgno, "dest": found_dest, "src": src}
                        for _q in list(listeners):
                            try: _q.put_nowait(rej_event)
                            except queue.Full: pass
                elif extra.get("msg_ack") and ackto:
                    found_dest, found_msgno = chat_manager.mark_ack(ackto)
                    logger.info("[MSG] ACK recu pour msgno=%s de %s", ackto, src)
                    if found_dest:
                        # Diffuser l'event ack au frontend pour mise à jour live de la bulle TX
                        ack_event = {
                            "type":   "msg_ack",
                            "msgno":  found_msgno,
                            "dest":   found_dest,
                            "src":    src,
                        }
                        for _q in list(listeners):
                            try: _q.put_nowait(ack_event)
                            except queue.Full: pass
                elif dest and dest in my_calls():
                    is_new = chat_manager.add_incoming(src, text, msgno)
                    frame["_chat"] = True
                    if is_new:
                        logger.info("[MSG] Message recu de %s : %s (msgno=%s)", src, text[:40], msgno)
                    else:
                        logger.info("[MSG] Retransmission (doublon ignoré) de %s : msgno=%s — ACK renvoyé", src, msgno)
                    # APRS_MSGNO_REPLYACK_FIX_v1 : reply-ack piggybacké dans le
                    # msgno de leur message ("{msgno}reply-ack") -> ils accusent
                    # au passage un de NOS messages sortants. On le traite comme
                    # un ACK normal, en plus de l'ACK qu'on va leur renvoyer.
                    replyack = extra.get("msg_replyack")
                    if replyack:
                        ra_dest, ra_msgno = chat_manager.mark_ack(replyack)
                        logger.info("[MSG] Reply-ack piggybacké recu pour msgno=%s de %s", replyack, src)
                        if ra_dest:
                            ack_event = {
                                "type": "msg_ack", "msgno": ra_msgno,
                                "dest": ra_dest, "src": src,
                            }
                            for _q in list(listeners):
                                try: _q.put_nowait(ack_event)
                                except queue.Full: pass
                    if msgno:
                        ack_payload = ":" + src.ljust(9) + ":ack" + msgno
                        try:
                            tx_queue.put_nowait({
                                "dest": "APRS", "payload": ack_payload, "path": None,
                                "aprs_type": "ACK", "extra": {"comment": "ack" + msgno}
                            })
                            logger.debug("[MSG] ACK envoye : ack%s -> %s", msgno, src)
                        except Exception as e:
                            logger.error("[MSG] Erreur envoi ACK : %s", e)

            # ── iGate : forward RF → APRS-IS ─────────────────────────────
            if (config_manager.data.get("igate_enabled") and
                    igate_client.connected and
                    frame.get("type") != "tx_event" and
                    frame.get("type") != "rx_level" and
                    frame.get("_source") != "IS" and          # pas de boucle
                    frame.get("aprs_type") not in ("Telemetrie",) and
                    frame.get("src")):
                igate_client.gate_rf_to_is(frame)

            # ── Digipeater : retransmission RF ────────────────────────────
            if (frame.get("type") not in ("tx_event", "rx_level") and
                    frame.get("_source") != "IS" and
                    frame.get("src")):
                digipeater.process(frame)

            # Assigner _fid AVANT de broadcaster (SSE + historique ont le même id)
            if frame.get("type") != "rx_level" and "_fid" not in frame:
                frame["_fid"] = next(_fid_counter)

            # Historique (hors rx_level)
            if frame.get("type") != "rx_level":
                if "_ts" not in frame:
                    frame["_ts"] = time.time()
                with rx_history_lock:
                    rx_history.append(frame)
                _fs = globals().get('_fs_record')   # STATION_WATCH_v1 : compteurs de trafic
                if _fs and frame.get("type") != "tx_event":
                    _fs(frame)
                _cu = globals().get('_cu_record')   # CHANNEL_USAGE_PATCH_v1 : airtime du canal
                if _cu:
                    _cu(frame)
                # Marquer l'activité pour la jauge
                if frame.get("type") != "tx_event":
                    _rx_activity_ts[0] = time.time()
            # ── Mise à jour positions stations ──────────────────────────
            _e = frame.get("extra", {})
            if _e.get("lat") is not None and frame.get("type") not in ("tx_event", "rx_level"):
                _cs  = frame.get("src", "").upper().strip().split(",")[0]
                _lat = _e["lat"];  _lon = _e["lon"];  _now = time.time()
                # Détecter si c'est une station mobile/ballon (table+code symbol)
                _sym = (_e.get("symbol_table", "") + _e.get("symbol_code", "")).lower()
                _mobile = _sym in _TRAIL_SYMBOLS or bool(_re.search(r'[/\\][jkuvoOXY\[]', _sym))
                with stations_positions_lock:
                    _prev = stations_positions.get(_cs, {})
                    _trail = list(_prev.get("trail", []))
                    if _mobile:
                        # N'ajouter un point que si la position a réellement changé
                        _spd = _e.get("speed_kmh", -1)
                        _crs = _e.get("course", -1)
                        if _spd is None: _spd = -1
                        if _crs is None: _crs = -1
                        if _trail:
                            _last = _trail[-1]
                            if abs(_last[0] - _lat) > 1e-5 or abs(_last[1] - _lon) > 1e-5:
                                _trail.append((_lat, _lon, _now, _spd, _crs))
                        else:
                            _trail.append((_lat, _lon, _now, _spd, _crs))
                        if len(_trail) > TRAIL_MAX:
                            _trail = _trail[-TRAIL_MAX:]
                    stations_positions[_cs] = {
                        "lat": _lat, "lon": _lon, "ts": _now,
                        "trail": _trail,
                        "mobile": _mobile,
                    }
                # WELCOME_TOURAINE_v1 : salutation des stations mobiles dans la zone
                if frame.get("aprs_type") in _WELCOME_TYPES:
                    _welcome_maybe(_cs, _lat, _lon, _e.get("speed_kmh"), _prev, frame)

            # ── Carnet de trafic : enregistrement automatique ─────────────
# Diffuser à tous les clients SSE — retrait automatique des listeners morts
# PATCH_MONITOR_FREEZE_267
            _MAX_LISTENER_ERRORS = 5
            _dead = []
            for q in list(listeners):
                try:
                    q.put_nowait(frame)
                    # Réinitialiser le compteur d'erreurs si l'envoi réussit
                    if hasattr(q, '_err_count'):
                        q._err_count = 0
                except queue.Full:
                    q._err_count = getattr(q, '_err_count', 0) + 1
                    if q._err_count >= _MAX_LISTENER_ERRORS:
                        _dead.append(q)
                        logger.warning("[SSE] Listener mort retiré (queue pleine x%d)", _MAX_LISTENER_ERRORS)
            if _dead:
                with _listeners_lock:
                    for _dq in _dead:
                        try:
                            listeners.remove(_dq)
                        except ValueError:
                            pass

        except queue.Empty:
            pass
        except Exception as _bcast_exc:
            logger.error("[BROADCASTER] Exception inattendue (trame ignorée) : %s", _bcast_exc, exc_info=True)

        # Jauge rx_level périodique (toutes les 500 ms) basée sur activité KISS
        now = time.time()
        if now - _rx_level_last[0] >= 0.5:
            _rx_level_last[0] = now
            elapsed = now - _rx_activity_ts[0]
            level = round(max(0.0, 1.0 - elapsed / 3.0), 3) if elapsed < 3.0 else 0.0
            lf = {"type": "rx_level", "level": level}
            for q in list(listeners):
                try: q.put_nowait(lf)
                except queue.Full: pass

threading.Thread(target=_rx_broadcaster, daemon=True).start()
igate_client.start()   # démarre le manager iGate (se connecte si igate_enabled)


@app.route('/rx_history')
@_login_required
def rx_history_route():
    """Retourne les dernières trames reçues (max RX_HISTORY_MAX).
    Le frontend l'appelle au chargement pour restaurer l'affichage après un F5."""
    with rx_history_lock:
        snapshot = list(rx_history)
    return jsonify(snapshot)

# ── Worker TX ─────────────────────────────────────────────────────────────────

tx_queue = queue.Queue(maxsize=10)

import itertools as _itertools
_fid_counter = _itertools.count(1)

def _broadcast_tx(job):
    cfg = config_manager.data
    APRSModem.rx_queue.put({
        "type":      "tx_event",
        "src":       cfg.get("callsign", "?"),
        "dest":      job.get("dest", "APRS"),
        "path":      job.get("path") or cfg.get("path", ""),
        "aprs_type": job.get("aprs_type", "TX"),
        "payload":   job.get("payload", ""),
        "extra":     job.get("extra", {}),
        "_fid":      next(_fid_counter),
    })

def _tx_worker():
    global modem
    while True:
        job = tx_queue.get()
        try:
            _broadcast_tx(job)
            if modem is None:
                raise RuntimeError("Modem non initialise")
            # Pour les retransmissions digi, préserver le src original
            _job_src = job.get("src") if job.get("aprs_type") == "Digi" else None
            modem.send_packet(job["dest"], job["payload"], job.get("path"), custom_src=_job_src)
        except Exception as e:
            APRSModem.tx_last_error = str(e)
            logger.error("[TX WORKER] ERREUR : %s", e)
            import traceback; traceback.print_exc()
        finally:
            tx_queue.task_done()

threading.Thread(target=_tx_worker, daemon=True, name="tx-worker").start()

# ── Démarrage du thread de retry ACK (après tx_queue et listeners) ────────────
threading.Thread(target=_ack_retry_worker, daemon=True, name="ack-retry").start()

# ── Beacon automatique ────────────────────────────────────────────────────────

_beacon_state = {
    "next_at":  None,
    "interval": config_manager.data.get("beacon_interval", 0),
    "type":     config_manager.data.get("beacon_type", "station"),
}

# ── Scheduler multi-balises ───────────────────────────────────────────────────
# Un thread par type de balise, chacun avec son propre timer indépendant.
# _beacon_workers[btype] = {"thread": Thread, "next_at": float|None, "interval": int}

_beacon_workers = {}
_beacon_workers_lock = threading.Lock()

# ── BCN_ISS_PAUSE_v1_APPLIED : pas de balise automatique quand le TRX est sur l'ISS ──
_BCN_ISS_MHZ = 145.825
_bcn_iss_paused_logged = {"v": False}


def _bcn_trx_on_iss():
    """True si la frequence lue en CAT (recente) est celle de l'ISS."""
    try:
        if not config_manager.data.get("beacons_pause_on_iss", True):
            return False
        with _cat_lock:
            ok, hz, ts = _cat_state["ok"], _cat_state["freq_hz"], _cat_state["ts"]
        if not ok or not hz or time.time() - ts > 60:
            return False
        return abs(hz / 1e6 - _BCN_ISS_MHZ) <= 0.002
    except Exception:
        return False


def _make_beacon_worker(btype):
    """Crée et démarre un thread de balise pour le type donné."""
    def _worker():
        # Résolution des fonctions à l'exécution (après définition complète du module)
        _dispatch = {
            "station":     _do_send_beacon,
            "iss":         _do_send_iss_beacon,
            "meteo":       _do_send_weather,
            "propagation": _do_send_propagation,
            "lune":        _do_send_moon,
            "soleil":      _do_send_sun,
            "text1":       _do_send_text1,
            "text2":       _do_send_text2,
            "bulletin":    _do_send_info_bulletin,
            "bulletin2":   _do_send_info_bulletin2,
            "bulletin3":   _do_send_info_bulletin3,
        }
        logger.info("[BCN] Thread démarré pour type=%s", btype)
        while True:
            schedules = config_manager.data.get('beacon_schedules', {})
            interval  = schedules.get(btype, 0)
            if interval and interval > 0 and btype != "iss" and _bcn_trx_on_iss():
                if not _bcn_iss_paused_logged["v"]:
                    _bcn_iss_paused_logged["v"] = True
                    logger.info("[BCN] TRX sur 145.825 MHz (ISS) : balises automatiques suspendues")
                time.sleep(20)
                continue
            if _bcn_iss_paused_logged["v"] and not _bcn_trx_on_iss():
                _bcn_iss_paused_logged["v"] = False
                logger.info("[BCN] TRX hors fréquence ISS : balises automatiques reprises")
            if interval and interval > 0:
                # Émettre
                logger.info("[BCN] Émission type=%s interval=%d min", btype, interval)
                fn = _dispatch.get(btype)
                if fn:
                    try:
                        fn()
                    except Exception as e:
                        logger.error("[BCN] Erreur type=%s : %s", btype, e)
                next_at = time.time() + interval * 60
                with _beacon_workers_lock:
                    if btype in _beacon_workers:
                        _beacon_workers[btype]["next_at"]  = next_at
                        _beacon_workers[btype]["interval"] = interval
                # Attendre par tranches de 5 s — réagit aux changements de config
                while time.time() < next_at:
                    time.sleep(5)
                    new_interval = config_manager.data.get('beacon_schedules', {}).get(btype, 0)
                    if new_interval != interval:
                        logger.info("[BCN] Config changée type=%s (%d→%d) — redémarrage", btype, interval, new_interval)
                        break
                with _beacon_workers_lock:
                    if btype in _beacon_workers:
                        _beacon_workers[btype]["next_at"] = None
            else:
                # Type désactivé — polling toutes les 10 s jusqu'à réactivation
                with _beacon_workers_lock:
                    if btype in _beacon_workers:
                        _beacon_workers[btype]["next_at"]  = None
                        _beacon_workers[btype]["interval"] = 0
                time.sleep(10)

    t = threading.Thread(target=_worker, daemon=True, name="beacon-%s" % btype)
    t.start()
    return t

def _beacon_scheduler():
    """Superviseur : lance/relance les threads de balise selon la config."""
    _ALL_TYPES = ["station", "iss", "meteo", "propagation", "lune", "soleil", "text1", "text2", "bulletin", "bulletin2", "bulletin3"]
    while True:
        with _beacon_workers_lock:
            for btype in _ALL_TYPES:
                worker = _beacon_workers.get(btype)
                if worker is None or not worker["thread"].is_alive():
                    t = _make_beacon_worker(btype)
                    _beacon_workers[btype] = {"thread": t, "next_at": None, "interval": 0}
        time.sleep(15)

def _do_send_beacon():
    cfg     = config_manager.data
    sym_t   = cfg.get('symbol_table', '/')
    sym_c   = cfg.get('symbol_code',  '[')
    comment = cfg.get('station_comment', '')
    grid    = cfg.get('maidenhead', '')

    # Convertir locator Maidenhead en lat/lon pour beacon position (format APRS !)
    def grid_to_latlon(grid):
        g = grid.upper()
        if len(g) < 4:
            return None, None
        try:
            lon = (ord(g[0]) - ord('A')) * 20 - 180
            lat = (ord(g[1]) - ord('A')) * 10 - 90
            lon += (int(g[2])) * 2
            lat += (int(g[3])) * 1
            if len(g) >= 6:
                lon += (ord(g[4]) - ord('A')) * (2/24.0)
                lat += (ord(g[5]) - ord('A')) * (1/24.0)
            lon += 1/24.0
            lat += 0.5/24.0
            return lat, lon
        except Exception:
            return None, None

    def deg_to_aprs(deg, is_lat):
        """Convertit degrés décimaux en format APRS DDDMM.MMH"""
        if is_lat:
            hemi = 'N' if deg >= 0 else 'S'
        else:
            hemi = 'E' if deg >= 0 else 'W'
        deg = abs(deg)
        d = int(deg)
        m = (deg - d) * 60
        if is_lat:
            return "%02d%05.2f%s" % (d, m, hemi)
        else:
            return "%03d%05.2f%s" % (d, m, hemi)

    lat, lon = grid_to_latlon(grid)

    if lat is not None:
        # Beacon avec position (type !)
        aprs_lat = deg_to_aprs(lat, True)
        aprs_lon = deg_to_aprs(lon, False)
        parts = []
        if grid:    parts.append("Grid:" + grid)
        if comment: parts.append(comment)
        info = " ".join(parts)
        payload = "!%s%s%s%s%s" % (aprs_lat, sym_t, aprs_lon, sym_c, info)
    else:
        # Beacon statut sans position si locator absent/invalide
        parts = []
        if grid:    parts.append("Grid:" + grid)
        if comment: parts.append(comment)
        info = " ".join(parts) if parts else "APRS"
        payload = ">" + info

    try:
        tx_queue.put_nowait({"dest": "APRS", "payload": payload, "path": None,
                             "aprs_type": "Beacon", "extra": {"comment": comment}})
        logger.debug("[TX] Beacon queued : %s", payload[:60])
    except Exception as e:
        logger.error("[TX] Beacon queue erreur : %s", e)


# ── Position lunaire (azimut/élévation/phase) ─────────────────────────────────
# Algorithme classique à précision "amateur" (formules de P. Schlyter,
# https://stjarnhimlen.se/comp/ppcomp.html), sans dépendance externe
# (pas de ephem/skyfield). Précision de l'ordre de l'arcminute sur plusieurs
# décennies -- largement suffisant pour un beacon informatif ; PAS destiné au
# pointage d'antenne EME de précision.
def _sun_position(lat, lon, dt_utc=None):
    """
    Position solaire (azimut/élévation) pour un observateur (lat, lon en
    degrés), plus l'état jour/crépuscule/nuit et un indicateur "grayline"
    (zone crépusculaire, propice à la propagation HF en ligne grise).
    Même famille de formules que _moon_position (P. Schlyter), sans
    dépendance externe.
    """
    import math as _m
    from datetime import datetime as _dt, timezone as _tz

    if dt_utc is None:
        dt_utc = _dt.now(_tz.utc)

    def _sind(x): return _m.sin(_m.radians(x))
    def _cosd(x): return _m.cos(_m.radians(x))
    def _atan2d(y, x): return _m.degrees(_m.atan2(y, x))
    def _norm360(x): return x % 360.0

    y, mo, da = dt_utc.year, dt_utc.month, dt_utc.day
    ut_hours  = dt_utc.hour + dt_utc.minute / 60.0 + dt_utc.second / 3600.0
    d = (367 * y - 7 * (y + (mo + 9) // 12) // 4 + 275 * mo // 9
         + da - 730530 + ut_hours / 24.0)

    w_sun = _norm360(282.9404 + 4.70935e-5 * d)
    M_sun = _norm360(356.0470 + 0.9856002585 * d)
    e_sun = 0.016709 - 1.151e-9 * d
    E_sun = M_sun + _m.degrees(e_sun) * _sind(M_sun) * (1 + e_sun * _cosd(M_sun))
    xv_s  = _cosd(E_sun) - e_sun
    yv_s  = _m.sqrt(1 - e_sun * e_sun) * _sind(E_sun)
    v_sun = _atan2d(yv_s, xv_s)
    lon_sun = _norm360(v_sun + w_sun)   # écliptique, latitude solaire ≈ 0

    obliq = 23.4393 - 3.563e-7 * d
    xeq = _cosd(lon_sun)
    yeq = _sind(lon_sun) * _cosd(obliq)
    zeq = _sind(lon_sun) * _sind(obliq)
    ra  = _norm360(_atan2d(yeq, xeq))
    dec = _atan2d(zeq, _m.sqrt(xeq * xeq + yeq * yeq))

    gmst0 = _norm360(lon_sun + 180.0)
    lst   = _norm360(gmst0 + ut_hours * 15.041069 + lon)
    ha    = _norm360(lst - ra)

    x = _cosd(ha) * _cosd(dec)
    yv = _sind(ha) * _cosd(dec)
    z = _sind(dec)
    xhor = x * _sind(lat) - z * _cosd(lat)
    yhor = yv
    zhor = x * _cosd(lat) + z * _sind(lat)

    azimuth   = _norm360(_atan2d(yhor, xhor) + 180.0)
    elevation = _atan2d(zhor, _m.sqrt(xhor * xhor + yhor * yhor))

    # ── État jour/crépuscule/nuit (seuils standards d'élévation solaire) ─────
    if elevation > 0:
        phase, emoji = "Jour", "☀️"
    elif elevation > -6:
        phase, emoji = "Crepuscule civil", "🌇"
    elif elevation > -12:
        phase, emoji = "Crepuscule nautique", "🌆"
    elif elevation > -18:
        phase, emoji = "Crepuscule astronomique", "🌃"
    else:
        phase, emoji = "Nuit", "🌑"

    # Zone grayline : bande crépusculaire propice au DX HF (terminateur proche)
    is_grayline = -6 <= elevation <= 6

    return {
        "azimuth_deg":   round(azimuth, 1),
        "elevation_deg": round(elevation, 1),
        "phase_name":    phase,
        "phase_emoji":   emoji,
        "is_grayline":   is_grayline,
        "visible":       elevation > 0,
    }


def _moon_position(lat, lon, dt_utc=None):
    """
    Calcule la position lunaire pour un observateur (lat, lon en degrés).
    Retourne un dict : azimuth_deg, elevation_deg, distance_km, phase_pct,
    phase_name, phase_emoji, illumination_pct (alias de phase_pct).
    """
    import math as _m
    from datetime import datetime as _dt, timezone as _tz

    if dt_utc is None:
        dt_utc = _dt.now(_tz.utc)

    def _sind(x): return _m.sin(_m.radians(x))
    def _cosd(x): return _m.cos(_m.radians(x))
    def _atan2d(y, x): return _m.degrees(_m.atan2(y, x))
    def _norm360(x): return x % 360.0

    # Jours écoulés depuis le 2000-01-00.0 UT (epoch Schlyter)
    y, mo, da = dt_utc.year, dt_utc.month, dt_utc.day
    ut_hours  = dt_utc.hour + dt_utc.minute / 60.0 + dt_utc.second / 3600.0
    d = (367 * y - 7 * (y + (mo + 9) // 12) // 4 + 275 * mo // 9
         + da - 730530 + ut_hours / 24.0)

    # ── Soleil (nécessaire pour l'élongation / phase) ────────────────────────
    w_sun = _norm360(282.9404 + 4.70935e-5 * d)
    M_sun = _norm360(356.0470 + 0.9856002585 * d)
    e_sun = 0.016709 - 1.151e-9 * d
    E_sun = M_sun + _m.degrees(e_sun) * _sind(M_sun) * (1 + e_sun * _cosd(M_sun))
    xv_s  = _cosd(E_sun) - e_sun
    yv_s  = _m.sqrt(1 - e_sun * e_sun) * _sind(E_sun)
    v_sun = _atan2d(yv_s, xv_s)
    lon_sun = _norm360(v_sun + w_sun)

    # ── Lune : éléments orbitaux ──────────────────────────────────────────────
    N_moon = _norm360(125.1228 - 0.0529538083 * d)
    i_moon = 5.1454
    w_moon = _norm360(318.0634 + 0.1643573223 * d)
    a_moon = 60.2666   # rayons terrestres
    e_moon = 0.054900
    M_moon = _norm360(115.3654 + 13.0649929509 * d)

    E_moon = M_moon + _m.degrees(e_moon) * _sind(M_moon) * (1 + e_moon * _cosd(M_moon))
    for _ in range(3):  # affinage itératif de l'anomalie excentrique
        E_moon = E_moon - (E_moon - _m.degrees(e_moon) * _sind(E_moon) - M_moon) / \
                 (1 - e_moon * _cosd(E_moon))

    xv = a_moon * (_cosd(E_moon) - e_moon)
    yv = a_moon * (_m.sqrt(1 - e_moon * e_moon) * _sind(E_moon))
    v_moon = _atan2d(yv, xv)
    r_moon = _m.sqrt(xv * xv + yv * yv)   # distance en rayons terrestres

    vw = v_moon + w_moon
    xh = r_moon * (_cosd(N_moon) * _cosd(vw) - _sind(N_moon) * _sind(vw) * _cosd(i_moon))
    yh = r_moon * (_sind(N_moon) * _cosd(vw) + _cosd(N_moon) * _sind(vw) * _cosd(i_moon))
    zh = r_moon * (_sind(vw) * _sind(i_moon))

    lon_ecl = _norm360(_atan2d(yh, xh))
    lat_ecl = _atan2d(zh, _m.sqrt(xh * xh + yh * yh))
    dist_er = _m.sqrt(xh * xh + yh * yh + zh * zh)  # rayons terrestres

    # ── Perturbations (améliore la précision à ~1 arcmin) ────────────────────
    Lm = _norm360(N_moon + w_moon + M_moon)
    Ls = _norm360(w_sun + M_sun)
    Dm = _norm360(Lm - Ls)
    F  = _norm360(Lm - N_moon)

    lon_ecl += (-1.274 * _sind(M_moon - 2 * Dm)
                + 0.658 * _sind(2 * Dm)
                - 0.186 * _sind(M_sun)
                - 0.059 * _sind(2 * M_moon - 2 * Dm)
                - 0.057 * _sind(M_moon - 2 * Dm + M_sun)
                + 0.053 * _sind(M_moon + 2 * Dm)
                + 0.046 * _sind(2 * Dm - M_sun)
                + 0.041 * _sind(M_moon - M_sun)
                - 0.035 * _sind(Dm)
                - 0.031 * _sind(M_moon + M_sun)
                - 0.015 * _sind(2 * F - 2 * Dm)
                + 0.011 * _sind(M_moon - 4 * Dm))
    lat_ecl += (-0.173 * _sind(F - 2 * Dm)
                - 0.055 * _sind(M_moon - F - 2 * Dm)
                - 0.046 * _sind(M_moon + F - 2 * Dm)
                + 0.033 * _sind(F + 2 * Dm)
                + 0.017 * _sind(2 * M_moon + F))
    dist_er += (-0.58 * _cosd(M_moon - 2 * Dm)
                - 0.46 * _cosd(2 * Dm))
    lon_ecl = _norm360(lon_ecl)

    EARTH_RADIUS_KM = 6378.14
    distance_km = dist_er * EARTH_RADIUS_KM

    # ── Écliptique → équatorial (RA/Dec) ─────────────────────────────────────
    obliq = 23.4393 - 3.563e-7 * d
    xeq = _cosd(lon_ecl) * _cosd(lat_ecl)
    yeq = _sind(lon_ecl) * _cosd(lat_ecl) * _cosd(obliq) - _sind(lat_ecl) * _sind(obliq)
    zeq = _sind(lon_ecl) * _cosd(lat_ecl) * _sind(obliq) + _sind(lat_ecl) * _cosd(obliq)
    ra  = _norm360(_atan2d(yeq, xeq))
    dec = _atan2d(zeq, _m.sqrt(xeq * xeq + yeq * yeq))

    # ── Temps sidéral local → azimut/élévation ────────────────────────────────
    gmst0 = _norm360(lon_sun + 180.0)           # degrés
    lst   = _norm360(gmst0 + ut_hours * 15.041069 + lon)  # lon : est positif
    ha    = _norm360(lst - ra)

    x = _cosd(ha) * _cosd(dec)
    y = _sind(ha) * _cosd(dec)
    z = _sind(dec)
    xhor = x * _sind(lat) - z * _cosd(lat)
    yhor = y
    zhor = x * _cosd(lat) + z * _sind(lat)

    azimuth   = _norm360(_atan2d(yhor, xhor) + 180.0)
    elevation = _atan2d(zhor, _m.sqrt(xhor * xhor + yhor * yhor))

    # ── Phase (élongation géocentrique Lune-Soleil) ──────────────────────────
    elong = _norm360(lon_ecl - lon_sun)
    illumination_pct = round((1 - _cosd(elong)) / 2 * 100, 1)

    if elong < 1 or elong > 359:
        phase_name, phase_emoji = "Nouvelle lune", "🌑"
    elif elong < 90:
        phase_name, phase_emoji = "Premier croissant", "🌒"
    elif abs(elong - 90) < 1:
        phase_name, phase_emoji = "Premier quartier", "🌓"
    elif elong < 180:
        phase_name, phase_emoji = "Gibbeuse croissante", "🌔"
    elif abs(elong - 180) < 1:
        phase_name, phase_emoji = "Pleine lune", "🌕"
    elif elong < 270:
        phase_name, phase_emoji = "Gibbeuse decroissante", "🌖"
    elif abs(elong - 270) < 1:
        phase_name, phase_emoji = "Dernier quartier", "🌗"
    else:
        phase_name, phase_emoji = "Dernier croissant", "🌘"

    return {
        "azimuth_deg":      round(azimuth, 1),
        "elevation_deg":    round(elevation, 1),
        "distance_km":      round(distance_km, 0),
        "illumination_pct": illumination_pct,
        "phase_pct":        illumination_pct,
        "elongation_deg":   round(elong, 3),
        "phase_name":       phase_name,
        "phase_emoji":      phase_emoji,
        "visible":          elevation > 0,
    }


def _grid_to_latlon(grid):
    """Conversion Maidenhead → (lat, lon) décimaux."""
    g = grid.upper()
    if len(g) < 4:
        return None, None
    try:
        lon = (ord(g[0]) - ord('A')) * 20 - 180
        lat = (ord(g[1]) - ord('A')) * 10 - 90
        lon += int(g[2]) * 2
        lat += int(g[3]) * 1
        if len(g) >= 6:
            lon += (ord(g[4]) - ord('A')) * (2 / 24.0)
            lat += (ord(g[5]) - ord('A')) * (1 / 24.0)
        lon += 1 / 24.0
        lat += 0.5 / 24.0
        return round(lat, 5), round(lon, 5)
    except Exception:
        return None, None


def _fetch_openmeteo(lat, lon):
    """
    Interroge l'API Open-Meteo (gratuite, sans clé) et retourne un dict météo.
    Champs retournés : temp_c, humidity_pct, wind_speed_ms, wind_dir_deg,
                       gust_ms, rain_mm, pressure_hpa, description.
    """
    import urllib.request, json as _json
    url = (
        "https://api.open-meteo.com/v1/forecast"
        "?latitude=%.5f&longitude=%.5f"
        "&current=temperature_2m,relative_humidity_2m,apparent_temperature,"
        "precipitation,rain,wind_speed_10m,wind_direction_10m,wind_gusts_10m,"
        "surface_pressure,weather_code"
        "&wind_speed_unit=ms"
        "&timezone=auto"
    ) % (lat, lon)

    logger.debug("[WX] Requete Open-Meteo : lat=%.4f lon=%.4f", lat, lon)
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "aprs_direwolf/1.0"})
        with urllib.request.urlopen(req, timeout=8) as resp:
            data = _json.loads(resp.read())
        cur = data.get("current", {})

        # WMO weather code → description courte
        WMO = {
            0:"Ciel clair", 1:"Peu nuageux", 2:"Partiellement nuageux",
            3:"Couvert", 45:"Brouillard", 48:"Brouillard givrant",
            51:"Bruine legere", 53:"Bruine moderee", 55:"Bruine dense",
            61:"Pluie faible", 63:"Pluie moderee", 65:"Pluie forte",
            71:"Neige faible", 73:"Neige moderee", 75:"Neige forte",
            80:"Averses faibles", 81:"Averses moderees", 82:"Averses fortes",
            95:"Orage", 96:"Orage avec gresil", 99:"Orage violent",
        }
        code = cur.get("weather_code", 0)
        return {
            "temp_c":       cur.get("temperature_2m"),
            "humidity_pct": cur.get("relative_humidity_2m"),
            "wind_speed_ms":cur.get("wind_speed_10m"),
            "wind_dir_deg": cur.get("wind_direction_10m"),
            "gust_ms":      cur.get("wind_gusts_10m"),
            "rain_mm":      cur.get("rain") or cur.get("precipitation") or 0,
            "pressure_hpa": cur.get("surface_pressure"),
            "description":  WMO.get(code, "Inconnu"),
            "wmo_code":     code,
        }
    except Exception as e:
        logger.error("[WX] Erreur Open-Meteo : %s", e)
        return None


def _fetch_solar_indices():
    """
    Récupère les indices solaires/géomagnétiques depuis NOAA Space Weather.
    Retourne un dict : sfi, a_index, k_index, hf_cond, vhf_cond, aurora.

    Endpoints vérifiés mai 2026 :
      Kp + A : products/noaa-planetary-k-index.json
               Format : [{time_tag, Kp, a_running, station_count}, ...]
      SFI    : json/f107_cm_flux.json
               Format : [{time_tag, flux, ...}, ...]
    """
    import urllib.request, json as _json

    result = {}

    # ── Kp + A-index ─────────────────────────────────────────────────────────
    url_kp = "https://services.swpc.noaa.gov/products/noaa-planetary-k-index.json"
    try:
        req = urllib.request.Request(url_kp, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=8) as resp:
            raw = _json.loads(resp.read())
        # Tableau d'objets — dernier = période 3h la plus récente
        if isinstance(raw, list) and raw:
            last = raw[-1]
            if isinstance(last, dict):
                if last.get("Kp")        is not None: result["k_index"] = float(last["Kp"])
                if last.get("a_running") is not None: result["a_index"] = float(last["a_running"])
                logger.debug("[PROP] Kp=%.2f A=%.0f (%s)",
                    result.get("k_index", 0), result.get("a_index", 0),
                    last.get("time_tag", "?"))
    except Exception as e:
        logger.error("[PROP] Erreur Kp NOAA : %s", e)

    # ── SFI (F10.7 cm flux) ───────────────────────────────────────────────────
    url_sfi = "https://services.swpc.noaa.gov/json/f107_cm_flux.json"
    try:
        req = urllib.request.Request(url_sfi, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=8) as resp:
            raw = _json.loads(resp.read())
        if isinstance(raw, list) and raw:
            # Parcourir depuis la fin pour la dernière valeur non nulle
            for entry in reversed(raw):
                v = entry.get("flux") if isinstance(entry, dict) else None
                if v is None and isinstance(entry, dict):
                    v = entry.get("f107")
                if v is not None:
                    result["sfi"] = float(v)
                    logger.debug("[PROP] SFI=%.0f (%s)", result["sfi"], entry.get("time_tag", "?"))
                    break
    except Exception as e:
        logger.error("[PROP] Erreur SFI NOAA : %s", e)

    sfi = result.get("sfi")
    k   = result.get("k_index")
    a   = result.get("a_index")

    def hf_conditions(sfi, a, k):
        if sfi is None:
            return "?"
        if k is not None and k >= 5:
            return "MAUVAIS"
        if a is not None and a >= 30:
            return "PERTURBE"
        if sfi >= 150: return "EXCEL"
        if sfi >= 120: return "BON"
        if sfi >= 90:  return "CORRECT"
        if sfi >= 70:  return "FAIBLE"
        return "MAUVAIS"

    def vhf_conditions(k):
        if k is None: return "?"
        if k >= 5:    return "AURORA"
        if k <= 2:    return "CALME"
        if k <= 3:    return "LEGER"
        return "ACTIVE"

    result["hf_cond"]  = hf_conditions(sfi, a, k)
    result["vhf_cond"] = vhf_conditions(k)
    result["aurora"]   = (k is not None and k >= 5)

    logger.info("[PROP] SFI=%s A=%s K=%s HF=%s VHF=%s",
        ("%.0f" % sfi) if sfi else "?",
        ("%.0f" % a)   if a   else "?",
        ("%.1f" % k)   if k   else "?",
        result["hf_cond"], result["vhf_cond"]
    )
    return result


def _do_send_propagation():
    """
    Construit et émet un beacon APRS de type '>' (Status) avec les indices
    de propagation solaire/géomagnétique récupérés depuis NOAA Space Weather.
    Format : >SFI:NNN A:NN K:N HF:XXXX VHF:YYYY {NOAA}
    """
    data = _fetch_solar_indices()

    sfi = data.get("sfi")
    a   = data.get("a_index")
    k   = data.get("k_index")
    hf  = data.get("hf_cond", "?")
    vhf = data.get("vhf_cond", "?")

    sfi_str = ("%.0f" % sfi) if sfi is not None else "?"
    a_str   = ("%.0f" % a)   if a   is not None else "?"
    k_str   = ("%.1f" % k)   if k   is not None else "?"

    payload = ">SFI:%s A:%s K:%s HF:%s VHF:%s {NOAA}" % (
        sfi_str, a_str, k_str, hf, vhf
    )

    try:
        tx_queue.put_nowait({
            "dest":      "APRS",
            "payload":   payload,
            "path":      None,
            "aprs_type": "Propagation",
            "extra": {
                "sfi":      sfi,
                "a_index":  a,
                "k_index":  k,
                "hf_cond":  hf,
                "vhf_cond": vhf,
                "aurora":   data.get("aurora", False),
                "comment":  payload[1:],
            }
        })
        logger.debug("[PROP] Beacon propagation queued : %s", payload)
        return {"status": "queued", "payload": payload, "data": data}
    except queue.Full:
        return {"error": "File TX pleine"}


def _do_send_sun():
    """
    Construit et émet un beacon APRS de type '>' (Status) avec les
    informations solaires pour la position de la station : azimut,
    élévation, état jour/crépuscule/nuit, indicateur grayline (utile pour
    repérer les fenêtres de propagation HF en ligne grise).
    Format : >SOLEIL Az:NNN El:NN (nom) [GRAYLINE] {SUN}
    """
    cfg      = config_manager.data
    geo_mode = cfg.get('geo_mode', 'locator')

    if geo_mode == 'coords':
        try:
            lat = float(cfg.get('lat_manual', '') or '')
            lon = float(cfg.get('lon_manual', '') or '')
        except (ValueError, TypeError):
            lat = lon = None
        if lat is None or lon is None:
            logger.warning("[SUN] Coordonnées manuelles absentes ou invalides — beacon soleil annulé")
            return {"error": "Latitude et longitude requises dans les réglages"}
    else:
        grid = cfg.get('maidenhead', '')
        lat, lon = _grid_to_latlon(grid)
        if lat is None:
            logger.warning("[SUN] Locator Maidenhead absent ou invalide — beacon soleil annulé")
            return {"error": "Locator Maidenhead requis dans les réglages"}

    sun = _sun_position(lat, lon)

    az   = int(round(sun["azimuth_deg"]))
    el   = int(round(sun["elevation_deg"]))
    name = sun["phase_name"]
    gl   = " GRAYLINE" if sun["is_grayline"] else ""

    payload = ">SOLEIL Az:%d El:%d (%s)%s {SUN}" % (az, el, name, gl)

    try:
        tx_queue.put_nowait({
            "dest":      "APRS",
            "payload":   payload,
            "path":      None,
            "aprs_type": "Beacon Soleil",
            "extra": {
                "sun_az":       sun["azimuth_deg"],
                "sun_el":       sun["elevation_deg"],
                "sun_phase":    name,
                "sun_emoji":    sun["phase_emoji"],
                "sun_grayline": sun["is_grayline"],
                "comment":      payload[1:],
            }
        })
        logger.debug("[SUN] Beacon soleil queued : %s", payload)
        return {"status": "queued", "payload": payload, "data": sun}
    except queue.Full:
        return {"error": "File TX pleine"}


def _do_send_moon():
    """
    Construit et émet un beacon APRS de type '>' (Status) avec les
    informations lunaires pour la position de la station : azimut,
    élévation, distance, phase.
    Format : >LUNE Az:NNN El:NN Phase:NN% (nom) Dist:NNNNNNkm {MOON}
    """
    cfg      = config_manager.data
    geo_mode = cfg.get('geo_mode', 'locator')

    if geo_mode == 'coords':
        try:
            lat = float(cfg.get('lat_manual', '') or '')
            lon = float(cfg.get('lon_manual', '') or '')
        except (ValueError, TypeError):
            lat = lon = None
        if lat is None or lon is None:
            logger.warning("[MOON] Coordonnées manuelles absentes ou invalides — beacon lune annulé")
            return {"error": "Latitude et longitude requises dans les réglages"}
    else:
        grid = cfg.get('maidenhead', '')
        lat, lon = _grid_to_latlon(grid)
        if lat is None:
            logger.warning("[MOON] Locator Maidenhead absent ou invalide — beacon lune annulé")
            return {"error": "Locator Maidenhead requis dans les réglages"}

    moon = _moon_position(lat, lon)

    az   = int(round(moon["azimuth_deg"]))
    el   = int(round(moon["elevation_deg"]))
    pha  = moon["phase_pct"]
    name = moon["phase_name"]
    dist = int(moon["distance_km"])

    payload = ">LUNE Az:%d El:%d Phase:%s%% (%s) Dist:%dkm {MOON}" % (
        az, el, ("%.0f" % pha), name, dist
    )

    try:
        tx_queue.put_nowait({
            "dest":      "APRS",
            "payload":   payload,
            "path":      None,
            "aprs_type": "Beacon Lune",
            "extra": {
                "moon_az":     moon["azimuth_deg"],
                "moon_el":     moon["elevation_deg"],
                "moon_phase":  pha,
                "moon_name":   name,
                "moon_emoji":  moon["phase_emoji"],
                "moon_dist":   dist,
                "moon_visible": moon["visible"],
                "comment":     payload[1:],
            }
        })
        logger.debug("[MOON] Beacon lune queued : %s", payload)
        return {"status": "queued", "payload": payload, "data": moon}
    except queue.Full:
        return {"error": "File TX pleine"}


def _do_send_iss_beacon():
    """Envoie un beacon APRS vers CQ via ARISS (contact ISS)."""
    cfg     = config_manager.data
    comment = cfg.get('station_comment', '')
    grid    = cfg.get('maidenhead', '')
    parts   = []
    if grid:    parts.append("Grid:" + grid)
    if comment: parts.append(comment)
    info    = " ".join(parts) if parts else "QRV ISS"
    payload = ":CQ       :" + info
    try:
        tx_queue.put_nowait({
            "dest":      "CQ",
            "payload":   payload,
            "path":      "ARISS",
            "aprs_type": "Beacon ISS",
            "extra":     {"comment": info}
        })
        logger.debug("[TX] Beacon ISS queued : %s", payload[:60])
    except Exception as e:
        logger.error("[TX] Beacon ISS erreur : %s", e)


def _do_send_weather():
    """
    Construit et émet un beacon météo APRS (symbole _ = weather station).
    Format : @DDHHMMzDDMM.MMN/DDDMM.MME_CSE/SPDgGGGtTTTrRRRpPPPPPPPhHHbBBBBBL### commentaire
    Unités APRS : vent en knots, temp en °F, pluie en 1/100 inch, pression en 1/10 mbar.
    """
    cfg      = config_manager.data
    geo_mode = cfg.get('geo_mode', 'locator')

    if geo_mode == 'coords':
        # ── Mode coordonnées géographiques directes ──────────────────────────
        try:
            lat = float(cfg.get('lat_manual', '') or '')
            lon = float(cfg.get('lon_manual', '') or '')
        except (ValueError, TypeError):
            lat = lon = None
        if lat is None or lon is None:
            logger.warning("[WX] Coordonnées manuelles absentes ou invalides — beacon météo annulé")
            return {"error": "Latitude et longitude requises dans les réglages"}
    else:
        # ── Mode Locator Maidenhead (défaut) ──────────────────────────────────
        grid = cfg.get('maidenhead', '')
        lat, lon = _grid_to_latlon(grid)
        if lat is None:
            logger.warning("[WX] Locator Maidenhead absent ou invalide — beacon météo annulé")
            return {"error": "Locator Maidenhead requis dans les réglages"}

    wx = _fetch_openmeteo(lat, lon)
    if wx is None:
        return {"error": "Impossible de récupérer les données Open-Meteo"}

    # ── Conversions vers unités APRS ────────────────────────────────────────
    def ms_to_knots(ms):
        return int(round((ms or 0) * 1.94384))

    def c_to_f(c):
        return int(round((c or 0) * 9 / 5 + 32))

    def mm_to_hundredths_inch(mm):
        return int(round((mm or 0) * 3.93701))

    def hpa_to_tenths_mbar(hpa):
        # pression en 1/10 mbar = 1/10 hPa, sur 5 chiffres
        return int(round((hpa or 0) * 10))

    def deg_to_cardinal(deg):
        """Convertit un angle en degrés vers un point cardinal (16 directions)."""
        cardinals = [
            "N", "NNE", "NE", "ENE",
            "E", "ESE", "SE", "SSE",
            "S", "SSO", "SO", "OSO",
            "O", "ONO", "NO", "NNO",
        ]
        idx = int(((deg or 0) + 11.25) / 22.5) % 16
        return cardinals[idx]

    wind_dir  = int(wx["wind_dir_deg"] or 0)
    wind_spd  = ms_to_knots(wx["wind_speed_ms"])
    gust      = ms_to_knots(wx["gust_ms"])
    temp_f    = c_to_f(wx["temp_c"])
    rain_1h   = mm_to_hundredths_inch(wx["rain_mm"])
    pressure  = hpa_to_tenths_mbar(wx["pressure_hpa"])
    humidity  = int(wx["humidity_pct"] or 0) % 100  # 00 = 100%

    # ── Position APRS ────────────────────────────────────────────────────────
    def deg_to_aprs(deg, is_lat):
        hemi = ('N' if deg >= 0 else 'S') if is_lat else ('E' if deg >= 0 else 'W')
        deg  = abs(deg); d = int(deg); m = (deg - d) * 60
        return ("%02d%05.2f%s" if is_lat else "%03d%05.2f%s") % (d, m, hemi)

    aprs_lat = deg_to_aprs(lat, True)
    aprs_lon = deg_to_aprs(lon, False)

    # ── Horodatage UTC ───────────────────────────────────────────────────────
    import time as _time
    ts = _time.gmtime()
    timestamp = "%02d%02d%02dz" % (ts.tm_mday, ts.tm_hour, ts.tm_min)

    # ── Données étendues (pluie 24 h / depuis minuit, luminosité) — WX_EXTRA_PATCH_v1 ──
    rain_24h_s = rain_mid_s = lum_s = None
    _bc = {}
    try:
        _bc = _wx_extra_data(lat, lon).get("beacon") or {}
    except Exception as _e:
        logger.warning("[WX] Donnees etendues indisponibles pour la balise : %s", _e)
    if _bc:
        rain_24h_s = "%03d" % min(999, mm_to_hundredths_inch(_bc.get("rain_24h_mm")))
        rain_mid_s = "%03d" % min(999, mm_to_hundredths_inch(_bc.get("rain_midnight_mm")))
        if _WX_BEACON_LUM and _bc.get("lum_wm2") is not None:   # WX_TEXT_ONLY_v1
            _lum = int(max(0, min(1999, round(_bc["lum_wm2"]))))
            lum_s = ("L%03d" % _lum) if _lum < 1000 else ("l%03d" % (_lum - 1000))
    if rain_24h_s is None:
        rain_24h_s = "%03d" % min(999, rain_1h)      # repli : ancienne valeur (pluie 1 h)
        rain_mid_s = "..."                           # inconnu
    rain_1h = min(999, rain_1h)

    # ── Payload APRS météo (@…_) ─────────────────────────────────────────────
    # Symbole fixe : table '/' code '_' = weather station
    # Ordre des champs conforme à la spécification : c/s g t r p P h b L
    payload = (
        "@%s%s/%s_"
        "%03d/%03d"          # wind direction / speed (knots)
        "g%03d"              # gust (knots)
        "t%03d"              # temp °F (peut être négatif → signe inclus)
        "r%03d"              # rain last hour (1/100 inch)
        "p%s"                # rain last 24h (1/100 inch)
        "P%s"                # rain since midnight (1/100 inch)
        "h%02d"              # humidity %
        "b%05d"              # pressure (1/10 mbar)
        "%s"                 # luminosity L### / l### (W/m²), vide si inconnue
        " %s"                # commentaire lisible
    ) % (
        timestamp, aprs_lat, aprs_lon,
        wind_dir, wind_spd,
        gust,
        temp_f,
        rain_1h,
        rain_24h_s,
        rain_mid_s,
        humidity,
        pressure,
        lum_s or "",
        wx["description"],
    )

    wind_cardinal = deg_to_cardinal(wind_dir)
    wind_kmh = round((wx["wind_speed_ms"] or 0) * 3.6, 1)
    gust_kmh  = round((wx["gust_ms"] or 0) * 3.6, 1)
    comment_human = (
        "%.1f°C %d%% HR Vent %s %.1f km/h Rafales %.1f km/h Pression %.1f hPa %s"
        % (wx["temp_c"], wx["humidity_pct"],
           wind_cardinal, wind_kmh, gust_kmh,
           wx["pressure_hpa"], wx["description"])
    )

    logger.debug("[WX] Payload : %s", payload[:80])
    try:
        tx_queue.put_nowait({
            "dest":      "APRS",
            "payload":   payload,
            "path":      None,
            "aprs_type": "Météo",
            "extra":     {
                "temp_c":        wx["temp_c"],
                "humidity_pct":  wx["humidity_pct"],
                "wind_dir":      wind_dir,
                "wind_speed_kmh": wind_kmh,
                "gust_kmh":      gust_kmh,
                "pressure_hpa":  wx["pressure_hpa"],
                "rain_1h_mm":    wx["rain_mm"],
                "rain_24h_mm":   _bc.get("rain_24h_mm"),
                "luminosity_wm2": _bc.get("lum_wm2"),
                "description":   wx["description"],
            }
        })
        return {"status": "queued", "wx": wx, "payload": payload}
    except queue.Full:
        return {"error": "File TX pleine"}

# WX_TEXT_ONLY_v1 : False = la balise WX émise ne contient plus le champ luminosité L###/l###,
# seulement le texte libre (libellé du ciel, ex. « Couvert »). Mettre True pour le rétablir.
_WX_BEACON_LUM = False

