def _send_info_bulletin(n, force=False):
    """
    Émet le bulletin d'information n (1, 2 ou 3) au format APRS BLNn.
    BULLETIN_MULTI_DAYS_PATCH_v1 — remplace l'ancienne _do_send_info_bulletin()
    unique (n=1 reste rétro-compatible avec les clés info_bulletin_text/_id).
    Respecte les jours de diffusion configurés (info_bulletin*_days), sauf en
    envoi manuel (force=True) qui émet immédiatement quel que soit le jour.
    Retourne True si le bulletin a été mis en file, False sinon.
    """
    prefix = "info_bulletin" if n == 1 else "info_bulletin%d" % n
    text = (config_manager.data.get(prefix + "_text") or "").strip()
    if not text:
        logger.warning("[TX] Bulletin d'info #%d vide — envoi annulé", n)
        return False

    if not force:
        days = config_manager.data.get(prefix + "_days", [0, 1, 2, 3, 4, 5, 6])
        try:
            days = [int(d) for d in days]
        except (TypeError, ValueError):
            days = [0, 1, 2, 3, 4, 5, 6]
        today = time.localtime().tm_wday   # 0=lundi ... 6=dimanche
        if today not in days:
            logger.debug("[TX] Bulletin d'info #%d — jour non sélectionné, envoi ignoré", n)
            return False

    try:
        idx = int(config_manager.data.get(prefix + "_id", n)) % 10
    except (TypeError, ValueError):
        idx = n
    # Pas d'emoji dans le payload RF (AX.25/KISS = octets 0-255 uniquement)
    text = text.encode("latin-1", errors="ignore").decode("latin-1")
    if len(text) > 67:
        text = text[:67]
    bln_addr = ("BLN%d" % idx).ljust(9)
    payload  = ":" + bln_addr + ":" + text
    try:
        tx_queue.put_nowait({"dest": "APRS", "payload": payload, "path": None,
                             "aprs_type": "Bulletin", "extra": {"comment": text}})
        logger.info("[TX] Bulletin d'info #%d mis en queue : %s", n, payload)
        return True
    except Exception as e:
        logger.error("[TX] Bulletin d'info #%d queue erreur : %s", n, e)
        return False


def _do_send_info_bulletin():
    _send_info_bulletin(1)

def _do_send_info_bulletin2():
    _send_info_bulletin(2)

def _do_send_info_bulletin3():
    _send_info_bulletin(3)


threading.Thread(target=_beacon_scheduler, daemon=True, name="beacon-supervisor").start()


# ── PATCH_DATA_BACKUP_277 : sauvegarde périodique des données persistantes ──
# Rotation gzippée de config.json / stats.json / chat.json / passphrase.json,
# sur le même principe que la rotation des logs (_GzipTimedRotatingFileHandler)
# mais adaptée à des fichiers réécrits en continu (pas de rotation "à la
# taille" possible). Protège contre une carte SD qui lâche ou une coupure
# secteur en cours d'écriture : sans ça, la perte de stats.json/passphrase.json
# n'est récupérable qu'en repartant de zéro.
_BACKUP_DIR       = "backups"
_BACKUP_FILES     = ["config.json", "stats.json", "chat.json", "passphrase.json"]
_BACKUP_INTERVAL  = 6 * 3600    # toutes les 6h
_BACKUP_RETENTION = 28          # 28 sauvegardes/fichier (~7 jours à 6h d'intervalle)

def _backup_data_files():
    """Copie gzippée horodatée de chaque fichier de données existant."""
    from datetime import datetime
    try:
        os.makedirs(_BACKUP_DIR, exist_ok=True)
    except Exception as e:
        logger.error("[BACKUP] Impossible de créer %s : %s", _BACKUP_DIR, e)
        return

    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    for fname in _BACKUP_FILES:
        if not os.path.exists(fname):
            continue
        dest = os.path.join(_BACKUP_DIR, "%s.%s.gz" % (fname, ts))
        try:
            with open(fname, "rb") as f_in, gzip.open(dest, "wb") as f_out:
                shutil.copyfileobj(f_in, f_out)
        except Exception as e:
            logger.error("[BACKUP] Échec sauvegarde %s : %s", fname, e)
            continue

        # Purge des sauvegardes excédentaires pour ce fichier
        try:
            prefix = fname + "."
            existing = sorted(
                f for f in os.listdir(_BACKUP_DIR)
                if f.startswith(prefix) and f.endswith(".gz")
            )
            for old in existing[:-_BACKUP_RETENTION]:
                os.remove(os.path.join(_BACKUP_DIR, old))
        except Exception as e:
            logger.warning("[BACKUP] Purge des anciennes sauvegardes (%s) échouée : %s", fname, e)

    logger.info("[BACKUP] Sauvegarde effectuée (%s)", ts)

def _backup_scheduler():
    """Boucle de fond : sauvegarde périodique des fichiers de données."""
    time.sleep(120)   # laisse l'appli finir son démarrage avant la première sauvegarde
    while True:
        _backup_data_files()
        time.sleep(_BACKUP_INTERVAL)

threading.Thread(target=_backup_scheduler, daemon=True, name="data-backup").start()


@app.route('/backups')
@_login_required
def list_backups():
    """Liste les sauvegardes disponibles, groupées par fichier d'origine."""
    result = {}
    if os.path.isdir(_BACKUP_DIR):
        for f in sorted(os.listdir(_BACKUP_DIR)):
            if not f.endswith(".gz"):
                continue
            for base in _BACKUP_FILES:
                if f.startswith(base + "."):
                    result.setdefault(base, []).append(f)
                    break
    return jsonify(result)


