@app.route('/config/import', methods=['POST'])
@_login_required
def config_import():
    """Restaure la configuration à partir d'un fichier de sauvegarde uploadé.
    Sauvegarde l'ancienne config dans backups/ avant écrasement, puis relance
    le modem avec les nouveaux paramètres (même mécanisme que /update_config)."""
    f = request.files.get('file')
    if not f or not f.filename:
        return jsonify({"status": "error", "error": "Aucun fichier reçu"}), 400

    try:
        new_data = json.loads(f.read().decode('utf-8'))
        if not isinstance(new_data, dict):
            raise ValueError("Le fichier ne contient pas un objet JSON valide")
    except Exception as e:
        return jsonify({"status": "error", "error": "Fichier invalide : %s" % e}), 400

    # Sauvegarde de sécurité de la config actuelle avant écrasement
    try:
        if os.path.exists(os.path.join(BASE_DIR, 'config.json')):
            os.makedirs(_BACKUP_DIR, exist_ok=True)
            from datetime import datetime
            ts = datetime.now().strftime("%Y%m%d_%H%M%S")
            dest = os.path.join(_BACKUP_DIR, "config.json.%s.pre-import.gz" % ts)
            with open(os.path.join(BASE_DIR, 'config.json'), 'rb') as f_in, gzip.open(dest, 'wb') as f_out:
                shutil.copyfileobj(f_in, f_out)
    except Exception as e:
        logger.warning("[CONFIG-IMPORT] Sauvegarde de sécurité échouée : %s", e)

    def _reload():
        global modem
        with _reload_lock:
            _reload_status["state"] = "loading"
            _reload_status["error"] = ""
            try:
                config_manager.restore(new_data)
                old = modem
                old.is_rx_running = False
                try:
                    if old.ser: old.ser.close()
                except Exception:
                    pass
                time.sleep(0.3)
                modem = APRSModem(config_manager.data)
                modem.start_rx()
                _reload_status["state"] = "ok"
                logger.info("[CONFIG-IMPORT] Configuration restaurée depuis %s", f.filename)
            except Exception as e:
                _reload_status["state"] = "error"
                _reload_status["error"] = str(e)
    threading.Thread(target=_reload, daemon=True, name="config-import-reload").start()
    return jsonify({"status": "reloading"})


