@app.route('/nearby_stations')
@_login_required
def nearby_stations():
    """Recherche périmétrique des stations APRS connues.
    Paramètres GET :
      lat        float  — latitude centre (défaut : station locale)
      lon        float  — longitude centre (défaut : station locale)
      radius_km  float  — rayon en km (défaut : 50, max : 1000)
      max_age_s  float  — âge max des données en secondes (défaut : 3600)
      mobile_only int   — 1 = mobiles uniquement (défaut : 0)
    Réponse JSON :
      { "center": {lat, lon}, "radius_km": float, "stations": [
          { "callsign", "lat", "lon", "distance_km", "mobile", "age_s", "ts" }, …
        ] }
    """
    import math as _m
    import json as _j
    import time as _t

    # ── Coordonnées centre ──────────────────────────────────────────────────
    def _safe_float(v):
        try: return float(v)
        except: return None

    lat = _safe_float(request.args.get("lat"))
    lon = _safe_float(request.args.get("lon"))
    if lat is None or lon is None:
        # Fallback 1 : coordonnées manuelles
        lat = _safe_float(config_manager.data.get("lat_manual"))
        lon = _safe_float(config_manager.data.get("lon_manual"))
    if lat is None or lon is None:
        # Fallback 2 : dériver depuis le locator Maidenhead
        mh = (config_manager.data.get("maidenhead") or "").strip().upper()
        if len(mh) >= 4:
            try:
                _lo = (ord(mh[0]) - 65) * 20 - 180
                _la = (ord(mh[1]) - 65) * 10 - 90
                _lo += int(mh[2]) * 2
                _la += int(mh[3]) * 1
                if len(mh) >= 6:
                    _lo += (ord(mh[4]) - 65) * (2/24) + (1/24)
                    _la += (ord(mh[5]) - 65) * (1/24) + (0.5/24)
                else:
                    _lo += 1.0; _la += 0.5
                lat, lon = _la, _lo
            except Exception:
                pass
    if lat is None or lon is None:
        return _j.dumps({"error": "lat/lon non disponibles — configurez les coordonnées ou le locator Maidenhead dans les réglages"}),\
               400, {'Content-Type': 'application/json'}

    radius_km   = min(float(request.args.get("radius_km",  50)),  1000.0)
    max_age_s   = float(request.args.get("max_age_s",  3600))
    mobile_only = request.args.get("mobile_only", "0") == "1"

    # ── Haversine (Python) ──────────────────────────────────────────────────
    def _hav_km(la1, lo1, la2, lo2):
        R = 6371.0
        dlat = _m.radians(la2 - la1)
        dlon = _m.radians(lo2 - lo1)
        a = _m.sin(dlat/2)**2 + _m.cos(_m.radians(la1))*_m.cos(_m.radians(la2))*_m.sin(dlon/2)**2
        return R * 2 * _m.asin(_m.sqrt(a))

    now = _t.time()
    result = []

    with stations_positions_lock:
        snapshot = dict(stations_positions)

    for cs, pos in snapshot.items():
        if pos.get("lat") is None: continue
        age = now - pos.get("ts", 0)
        if age > max_age_s: continue
        if mobile_only and not pos.get("mobile"): continue
        dist = _hav_km(lat, lon, pos["lat"], pos["lon"])
        if dist > radius_km: continue
        result.append({
            "callsign":    cs,
            "lat":         round(pos["lat"], 6),
            "lon":         round(pos["lon"], 6),
            "distance_km": round(dist, 2),
            "mobile":      bool(pos.get("mobile")),
            "age_s":       round(age),
            "ts":          pos.get("ts", 0),
        })

    result.sort(key=lambda x: x["distance_km"])
    return _j.dumps({
        "center":     {"lat": round(lat, 6), "lon": round(lon, 6)},
        "radius_km":  radius_km,
        "count":      len(result),
        "stations":   result,
    }), 200, {'Content-Type': 'application/json'}


@app.route('/beacon_status')
@_login_required
def beacon_status():
    """Retourne l'état de chaque type de balise : interval + next_in."""
    _ALL_TYPES = ["station", "iss", "meteo", "propagation", "lune", "soleil", "text1", "text2", "bulletin", "bulletin2", "bulletin3"]
    schedules = config_manager.data.get('beacon_schedules', {})
    result = {}
    with _beacon_workers_lock:
        for btype in _ALL_TYPES:
            worker   = _beacon_workers.get(btype, {})
            interval = schedules.get(btype, 0)
            next_at  = worker.get("next_at")
            next_in  = max(0, int(next_at - time.time())) if next_at else None
            result[btype] = {"interval": interval, "next_in": next_in}
    return jsonify({"schedules": result})

# ── PROPAGATION_EXTRA_PATCH_v1 — informations de propagation détaillées ─────────
_PX_LOCK = threading.Lock()
_PX_NET  = {"ts": 0.0, "data": None}
_PX_TTL  = 300
_PX_BASE = "https://services.swpc.noaa.gov"
_PX_LV   = ["Fermée", "Médiocre", "Moyen", "Bon"]


def _px_json(path):
    import urllib.request as _u
    req = _u.Request(_PX_BASE + path, headers={"User-Agent": "Mozilla/5.0"})
    with _u.urlopen(req, timeout=8) as r:
        raw = r.read().decode("utf-8", "replace").strip()
    return json.loads(raw) if raw else None


def _px_rows(raw):
    """Normalise les formats NOAA : liste de listes (1re ligne = en-têtes) ou liste de dicts."""
    if isinstance(raw, list) and raw and isinstance(raw[0], list):
        hdr = [str(h) for h in raw[0]]
        return [dict(zip(hdr, r)) for r in raw[1:] if isinstance(r, list)]
    if isinstance(raw, list):
        return [r for r in raw if isinstance(r, dict)]
    return []


def _px_f(v):
    try:
        if v is None or v == "":
            return None
        x = float(v)
        return x if x == x else None
    except (TypeError, ValueError):
        return None


def _px_ts(s):
    import datetime as _d
    s = str(s or "").replace("T", " ").replace("Z", "").split(".")[0].strip()
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
        try:
            return _d.datetime.strptime(s, fmt).replace(tzinfo=_d.timezone.utc).timestamp()
        except ValueError:
            pass
    return None


def _px_series(rows, key):
    out = []
    for r in rows:
        t, v = _px_ts(r.get("time_tag")), _px_f(r.get(key))
        if t is not None and v is not None:
            out.append((t, v))
    out.sort()
    return out


def _px_xcls(f):
    if f >= 1e-4: return "X%.1f" % (f / 1e-4)
    if f >= 1e-5: return "M%.1f" % (f / 1e-5)
    if f >= 1e-6: return "C%.1f" % (f / 1e-6)
    if f >= 1e-7: return "B%.1f" % (f / 1e-7)
    return "A%.1f" % (f / 1e-8)


def _px_solar_wind():
    pl = _px_rows(_px_json("/products/solar-wind/plasma-2-hour.json"))
    mg = _px_rows(_px_json("/products/solar-wind/mag-2-hour.json"))
    sp, de = _px_series(pl, "speed"), _px_series(pl, "density")
    bz, bt = _px_series(mg, "bz_gsm"), _px_series(mg, "bt")
    if not (sp or bz):
        raise RuntimeError("données vides")
    res = {"speed": None, "speed_trend": None, "density": None, "bz": None, "bz_mean30": None, "bt": None, "age_min": None}
    if sp:
        t0, v0 = sp[-1]
        res["speed"] = int(round(v0))
        res["age_min"] = int(max(0, (time.time() - t0) / 60))
        ref = [(abs(t - (t0 - 3600)), v) for t, v in sp if abs(t - (t0 - 3600)) <= 900]
        if ref:
            res["speed_trend"] = int(round(v0 - min(ref)[1]))
    if de:
        res["density"] = round(de[-1][1], 1)
    if bz:
        res["bz"] = round(bz[-1][1], 1)
        w = [v for t, v in bz if t >= bz[-1][0] - 1800]
        res["bz_mean30"] = round(sum(w) / len(w), 1)
    if bt:
        res["bt"] = round(bt[-1][1], 1)
    return res


def _px_scales():
    sc = _px_json("/products/noaa-scales.json") or {}

    def lv(d, k):
        try:
            return int((d.get(k) or {}).get("Scale") or 0)
        except (TypeError, ValueError):
            return 0

    def pr(d, k, f):
        try:
            return int((d.get(k) or {}).get(f))
        except (TypeError, ValueError):
            return None
    cur = sc.get("0") or {}
    fc = [sc.get(str(i)) or {} for i in (1, 2, 3)]
    return {"R": lv(cur, "R"), "S": lv(cur, "S"), "G": lv(cur, "G"),
            "g_fc": [lv(d, "G") for d in fc],
            "r_minor": pr(fc[0], "R", "MinorProb"), "r_major": pr(fc[0], "R", "MajorProb"),
            "s_prob": pr(fc[0], "S", "Prob")}


def _px_xray():
    data = _px_json("/json/goes/primary/xrays-6-hour.json") or []
    rows = [e for e in data if isinstance(e, dict) and "0.1-0.8" in str(e.get("energy", ""))]
    if not rows:
        rows = [e for e in data if isinstance(e, dict)]
    vals = []
    for e in rows:
        f = _px_f(e.get("flux"))
        if f is None:
            f = _px_f(e.get("observed_flux"))
        if f is not None and f > 0:
            vals.append(f)
    if not vals:
        raise RuntimeError("données vides")
    return {"cls": _px_xcls(vals[-1]), "flux": vals[-1], "max_cls": _px_xcls(max(vals)), "max_flux": max(vals)}


def _px_kp_fc():
    import datetime as _d
    rows = _px_rows(_px_json("/products/noaa-planetary-k-index-forecast.json"))
    now = time.time()
    seq = []
    for r in rows:
        t = _px_ts(r.get("time_tag"))
        kp = _px_f(r.get("kp", r.get("Kp")))
        if t is not None and kp is not None:
            seq.append((t, kp, str(r.get("observed") or "")))
    seq.sort()
    seq = [s for s in seq if s[0] >= now - 10800]
    if not seq:
        raise RuntimeError("données vides")
    days = {}
    for t, kp, _k in seq:
        d = _d.datetime.fromtimestamp(t, _d.timezone.utc).strftime("%d/%m")
        days[d] = max(days.get(d, 0.0), kp)
    day_max = [{"day": d, "kp": round(v, 1)} for d, v in list(days.items())[:3]]
    return {"next": [{"t": int(t), "kp": round(kp, 1), "kind": k} for t, kp, k in seq[:9]],
            "day_max": day_max, "max72": round(max(s[1] for s in seq), 1)}


def _px_fetch_net():
    out = {"errors": {}}
    for key, fn in (("solar_wind", _px_solar_wind), ("scales", _px_scales),
                    ("xray", _px_xray), ("kp_fc", _px_kp_fc)):
        try:
            out[key] = fn()
        except Exception as e:
            out["errors"][key] = str(e)[:80]
            logger.debug("[PROP-EXTRA] %s : %s", key, e)
    try:
        out["indices"] = _fetch_solar_indices()
    except Exception as e:
        out["indices"] = {}
        out["errors"]["indices"] = str(e)[:80]
    return out


def _px_hf(sfi, kp, a, phase):
    """Tableau HF jour/nuit par groupe de bandes (estimation indicative d'après SFI / Kp / A)."""
    if sfi is None:
        return {"matrix": [], "now": [], "phase": phase}
    pen = 0
    if kp is not None:
        pen = 2 if kp >= 7 else 1 if kp >= 5 else 0
    if a is not None and a >= 30:
        pen = max(pen, 1)
    groups = [
        ("80-40 m", 2, 3),
        ("30-20 m", 3 if sfi >= 80 else 2, 2 if sfi >= 100 else 1),
        ("17-15 m", 3 if sfi >= 120 else 2 if sfi >= 95 else 1, 1 if sfi >= 150 else 0),
        ("12-10 m", 3 if sfi >= 150 else 2 if sfi >= 120 else 1 if sfi >= 100 else 0, 0),
    ]
    matrix = [{"band": n, "day": max(0, d - pen), "night": max(0, ng - pen)} for n, d, ng in groups]
    best = []
    for m in matrix:
        lvl = m["day"] if phase == "day" else m["night"] if phase == "night" else max(m["day"], m["night"])
        if lvl >= 2:
            best.append((lvl, m["band"]))
    best.sort(key=lambda x: -x[0])
    return {"matrix": matrix, "now": [b for _l, b in best], "phase": phase}


def _px_payload():
    import math as _m
    import datetime as _d
    now = time.time()
    with _PX_LOCK:
        net = _PX_NET["data"] if (_PX_NET["data"] is not None and now - _PX_NET["ts"] < _PX_TTL) else None
    if net is None:
        net = _px_fetch_net()
        with _PX_LOCK:
            _PX_NET["ts"], _PX_NET["data"] = now, net

    lat, lon = _lightning_center()
    sp = _sun_position(lat, lon)
    el = sp.get("elevation_deg", 0.0)
    phase = "day" if el > 0 else "night" if el < -6 else "gray"
    t_rise = t_set = None
    prev = el
    t0 = _d.datetime.now(_d.timezone.utc)
    for i in range(1, 289):
        dt = t0 + _d.timedelta(minutes=5 * i)
        e = _sun_position(lat, lon, dt).get("elevation_deg", 0.0)
        if t_rise is None and prev <= 0 < e:
            t_rise = int(dt.timestamp())
        if t_set is None and prev > 0 >= e:
            t_set = int(dt.timestamp())
        prev = e
        if t_rise and t_set:
            break

    plat, plon = _m.radians(80.8), _m.radians(-72.8)
    la, lo = _m.radians(lat), _m.radians(lon)
    maglat = _m.degrees(_m.asin(max(-1.0, min(1.0, _m.sin(la) * _m.sin(plat) + _m.cos(la) * _m.cos(plat) * _m.cos(lo - plon)))))
    kp_need = round(max(0.0, (66.5 - abs(maglat)) / 2.0), 1)
    ind = net.get("indices") or {}
    kp_now = ind.get("k_index")
    kp_max = (net.get("kp_fc") or {}).get("max72")
    aurora = {"maglat": round(maglat, 1), "kp_needed": min(kp_need, 9.0), "kp_now": kp_now, "kp_max72": kp_max,
              "possible": bool(kp_max is not None and kp_max >= kp_need - 0.01)}

    month = _d.datetime.now(_d.timezone.utc).month
    if month in (6, 7):
        es_lv, es_lab = 3, "Pleine saison"
    elif month in (5, 8):
        es_lv, es_lab = 2, "Bonne saison"
    elif month in (4, 9, 12, 1):
        es_lv, es_lab = 1, "Saison faible"
    else:
        es_lv, es_lab = 0, "Hors saison"

    hf = _px_hf(ind.get("sfi"), kp_now, ind.get("a_index"), phase)

    # Prochains essaims de météores (calendrier statique) — meteor scatter 50/144 MHz
    meteors = []
    try:
        _today = _d.date.today()
        for _mo, _dy, _name, _zhr, _note in _SW_SHOWERS:
            _pk = _d.date(_today.year, _mo, _dy)
            if _pk < _today:
                _pk = _d.date(_today.year + 1, _mo, _dy)
            meteors.append({"name": _name, "peak": _pk.strftime("%d/%m"), "days": (_pk - _today).days, "zhr": _zhr})
        meteors.sort(key=lambda r: r["days"])
        meteors = meteors[:3]
    except Exception:
        meteors = []

    notes = []

    def note(level, icon, text):
        notes.append({"level": level, "icon": icon, "text": text})

    sw, scl, xr = net.get("solar_wind") or {}, net.get("scales") or {}, net.get("xray") or {}
    if sw.get("bz") is not None and sw.get("speed") is not None:
        if sw["bz"] <= -10 and sw["speed"] >= 500:
            note(2, "🌬️", "Vent solaire rapide (%d km/s) avec Bz fortement sud (%.1f nT) : orage géomagnétique probable dans l’heure." % (sw["speed"], sw["bz"]))
        elif (sw.get("bz_mean30") is not None and sw["bz_mean30"] <= -5) or sw["speed"] >= 600:
            note(1, "🌬️", "Vent solaire perturbé (%d km/s, Bz %.1f nT) : le Kp peut monter dans les prochaines heures." % (sw["speed"], sw["bz"]))
    if scl.get("G", 0) >= 1:
        note(2 if scl["G"] >= 3 else 1, "🧲", "Tempête géomagnétique G%d en cours : aurore possible (diffusion VHF)." % scl["G"])
    elif scl.get("g_fc") and max(scl["g_fc"]) >= 1:
        note(1, "🧲", "Tempête géomagnétique G%d prévue d’ici 3 jours : aurore VHF possible." % max(scl["g_fc"]))
    if aurora["possible"]:
        note(1, "🌌", "Kp prévu jusqu’à %.1f : seuil d’aurore à votre latitude (≈ Kp %.1f) atteint, diffusion aurorale VHF possible." % (kp_max, kp_need))
    if es_lv >= 2:
        note(0, "⚡", "%s de sporadique E : surveillez 6 m et 2 m, surtout en fin de matinée et en soirée." % es_lab)
    if not notes:
        note(0, "✅", "Rien de particulier : conditions de propagation habituelles.")

    return {"ts": now, "solar_wind": net.get("solar_wind"), "scales": net.get("scales"), "xray": net.get("xray"),
            "kp_fc": net.get("kp_fc"), "errors": net.get("errors", {}),
            "sun": {"phase": sp.get("phase_name"), "emoji": sp.get("phase_emoji"), "elevation": el,
                    "grayline": bool(sp.get("is_grayline")), "next_sunrise": t_rise, "next_sunset": t_set, "mode": phase},
            "aurora": aurora, "es": {"level": es_lv, "label": es_lab, "month": month},
            "hf": hf, "notes": notes, "meteors": meteors}


# ── PROP_PLUS_v1 : pression/anticyclone, aurore locale, chat ON4KST ───────────────────────
_PP_CACHE = {}
_PP_LOCK  = threading.Lock()


def _pp_get_json(url, timeout=15):
    import urllib.request as _u
    req = _u.Request(url, headers={"User-Agent": "aprs_station/3.0"})
    with _u.urlopen(req, timeout=timeout) as r:
        return json.loads(r.read().decode("utf-8", "replace"))


def _pp_cached(key, ttl, fn):
    now = time.time()
    with _PP_LOCK:
        c = _PP_CACHE.get(key)
        if c and now - c[0] < ttl:
            return c[1]
    val = fn()
    with _PP_LOCK:
        _PP_CACHE[key] = (now, val)
    return val


def _pp_pressure(lat, lon):
    """Pression au niveau de la mer : tendance 3 h / 24 h et durée de la situation anticyclonique (7 j)."""
    import datetime as _d
    url = ("https://api.open-meteo.com/v1/forecast?latitude=%.4f&longitude=%.4f"
           "&hourly=pressure_msl&past_days=7&forecast_days=1&timezone=auto") % (lat, lon)
    raw = _pp_get_json(url)
    h = raw.get("hourly") or {}
    times, vals = h.get("time") or [], h.get("pressure_msl") or []
    off = raw.get("utc_offset_seconds") or 0
    now_s = (_d.datetime.now(_d.timezone.utc) + _d.timedelta(seconds=off)).strftime("%Y-%m-%dT%H:00")
    ok = [i for i, t in enumerate(times) if t <= now_s and i < len(vals) and vals[i] is not None]
    if not ok or ok[-1] < 24:
        raise RuntimeError("série de pression trop courte")
    ni = ok[-1]
    p = vals[ni]
    d3 = (p - vals[ni - 3]) if vals[ni - 3] is not None else None
    d24 = (p - vals[ni - 24]) if vals[ni - 24] is not None else None
    days = {}
    for i in range(ni + 1):
        if vals[i] is not None:
            days.setdefault(times[i][:10], []).append(vals[i])
    dl = [{"date": k, "mean": round(sum(v) / len(v), 1), "min": round(min(v), 1), "max": round(max(v), 1)}
          for k, v in sorted(days.items())][-8:]
    streak = 0
    for dd in reversed(dl):
        if dd["mean"] >= 1018 and dd["max"] - dd["min"] <= 8:
            streak += 1
        else:
            break
    arrow, label = _wx_pressure_trend(d3)
    return {"now": round(p, 1),
            "d3": None if d3 is None else round(d3, 1),
            "d24": None if d24 is None else round(d24, 1),
            "arrow": arrow, "label": label, "days": dl,
            "high_days": streak, "high_now": p >= 1018}


def _pp_aurora(lat, lon):
    """Probabilité d'aurore (modèle NOAA OVATION) ici et dans le secteur nord (+3° à +15° de latitude)."""
    raw = _pp_get_json("https://services.swpc.noaa.gov/json/ovation_aurora_latest.json", timeout=25)
    grid = {}
    for c in raw.get("coordinates") or []:
        try:
            grid[(int(c[0]) % 360, int(c[1]))] = float(c[2])
        except (TypeError, ValueError, IndexError):
            continue
    if not grid:
        raise RuntimeError("grille OVATION vide")
    lo0, la0 = int(round(lon)) % 360, int(round(lat))
    best, best_lat = 0.0, None
    for la in range(la0 + 3, min(90, la0 + 15) + 1):
        for dlo in range(-20, 21):
            v = grid.get(((lo0 + dlo) % 360, la))
            if v is not None and v > best:
                best, best_lat = v, la
    return {"here": grid.get((lo0, la0)),
            "north_max": int(round(best)),
            "north_lat": best_lat,
            "north_km": None if best_lat is None else int(round((best_lat - lat) * 111)),
            "obs": raw.get("Observation Time"), "fc": raw.get("Forecast Time")}


@app.route('/prop_pressure')
@_login_required
def prop_pressure_route():
    lat, lon = _wx_station_latlon()
    if lat is None:
        return jsonify({"error": "position de la station non configurée"}), 200
    try:
        return jsonify(_pp_cached("press:%.2f,%.2f" % (lat, lon), 1800, lambda: _pp_pressure(lat, lon)))
    except Exception as e:
        logger.warning("[PROP+] pression : %s", e)
        return jsonify({"error": str(e)[:120]}), 200


@app.route('/prop_aurora')
@_login_required
def prop_aurora_route():
    lat, lon = _wx_station_latlon()
    if lat is None:
        return jsonify({"error": "position de la station non configurée"}), 200
    try:
        return jsonify(_pp_cached("aur:%.2f,%.2f" % (lat, lon), 600, lambda: _pp_aurora(lat, lon)))
    except Exception as e:
        logger.warning("[PROP+] aurore : %s", e)
        return jsonify({"error": str(e)[:120]}), 200


# ── Chat ON4KST (telnet www.on4kst.info:23000) ───────────────────────────────────────────
KST_FILE = os.path.join(BASE_DIR, "kst.json")   # identifiants à part de config.json (exports/sauvegardes)


def _kst_load():
    try:
        with open(KST_FILE, "r", encoding="utf-8") as f:
            d = json.load(f)
    except Exception:
        d = {}
    return {"login": str(d.get("login") or ""), "password": str(d.get("password") or ""),
            "chat": str(d.get("chat") or "2")}


def _kst_save(d):
    with open(KST_FILE, "w", encoding="utf-8") as f:
        json.dump(d, f)
    try:
        os.chmod(KST_FILE, 0o600)
    except Exception:
        pass


class _KstClient:
    """Client telnet minimal : identification, choix du chat, flux de lignes brutes, envoi de texte."""

    def __init__(self):
        self.host, self.port = "www.on4kst.info", 23000
        self._lock = threading.Lock()
        self._sock = None
        self._thread = None
        self._want = False
        self.state = "off"      # off | connecting | login | online | error
        self.msg = ""
        self.lines = collections.deque(maxlen=400)
        self.seq = 0

    def _log(self, text, kind="rx"):
        with self._lock:
            self.seq += 1
            self.lines.append({"n": self.seq, "t": int(time.time()), "k": kind, "x": text})

    def _set(self, state, msg=""):
        self.state, self.msg = state, msg

    def alive(self):
        return bool(self._thread and self._thread.is_alive())

    def connect(self, login, password, chat):
        if self.alive():
            return
        if not login or not password:
            self._set("error", "identifiant ou mot de passe manquant")
            return
        self._want = True
        self._set("connecting", "")
        self._thread = threading.Thread(target=self._run, args=(login, password, str(chat or "2")),
                                        daemon=True, name="kst-chat")
        self._thread.start()

    def disconnect(self):
        self._want = False
        s = self._sock
        if s:
            try:
                s.close()
            except Exception:
                pass
        self._set("off", "")

    @staticmethod
    def _strip_iac(data, sock):
        """Retire les séquences telnet (IAC) et refuse poliment toute option proposée."""
        out = bytearray()
        i, n = 0, len(data)
        while i < n:
            b = data[i]
            if b != 255:
                out.append(b)
                i += 1
                continue
            if i + 1 >= n:
                break
            c = data[i + 1]
            if c in (251, 252, 253, 254) and i + 2 < n:        # WILL/WONT/DO/DONT
                try:
                    sock.sendall(bytes([255, 254 if c == 251 else 252, data[i + 2]]) if c in (251, 253)
                                 else b"")
                except Exception:
                    pass
                i += 3
            elif c == 250:                                       # sous-négociation : ignorer jusqu'à IAC SE
                j = data.find(bytes([255, 240]), i + 2)
                i = n if j < 0 else j + 2
            elif c == 255:
                out.append(255)
                i += 2
            else:
                i += 2
        return bytes(out)

    def _send_raw(self, text):
        self._sock.sendall((text + "\r\n").encode("latin-1", "replace"))

    def _run(self, login, password, chat):
        sock = None
        try:
            sock = socket.create_connection((self.host, self.port), timeout=12)
            sock.settimeout(1.0)
            self._sock = sock
            self._set("login", "identification…")
            self._log("Connecté à %s:%d" % (self.host, self.port), "sys")
            stage, tail = 0, ""
            while self._want:
                try:
                    data = sock.recv(4096)
                except socket.timeout:
                    data = None
                if data == b"":
                    break
                if data:
                    txt = self._strip_iac(data, sock).decode("utf-8", "replace")
                    buf = tail + txt.replace("\r", "")
                    parts = buf.split("\n")
                    tail = parts.pop()
                    for ln in parts:
                        if ln.strip():
                            self._log(ln.rstrip(), "rx")
                    low = (buf).lower()
                    if stage == 0 and "login" in low:
                        self._send_raw(login)
                        self._log("(identifiant envoyé : %s)" % login, "sys")
                        stage, tail = 1, ""
                    elif stage == 1 and "password" in low:
                        self._send_raw(password)
                        self._log("(mot de passe envoyé)", "sys")
                        stage, tail = 2, ""
                    if stage < 3 and "chat selection" in low:
                        self._send_raw(chat)
                        self._log("(chat n°%s choisi)" % chat, "sys")
                        stage, tail = 3, ""
                        self._set("online", "")
                    if tail.strip() and stage >= 3:      # invite sans fin de ligne
                        self._log(tail.rstrip(), "rx")
                        tail = ""
            if self._want:
                self._set("error", "connexion fermée par le serveur" + (
                    " avant la fin de l'identification (identifiants ?)" if stage < 3 else ""))
                self._log("Connexion fermée.", "sys")
        except Exception as e:
            self._set("error", str(e)[:100])
            self._log("Erreur : %s" % e, "sys")
        finally:
            try:
                if sock:
                    sock.close()
            except Exception:
                pass
            self._sock = None
            if self._want is False and self.state != "error":
                self._set("off", "")
            self._want = False

    def send(self, text):
        text = (text or "").replace("\r", " ").replace("\n", " ").strip()[:250]
        if not text:
            return False, "message vide"
        if self.state != "online" or not self._sock:
            return False, "non connecté"
        try:
            self._send_raw(text)
            self._log(text, "tx")
            return True, ""
        except Exception as e:
            self._set("error", str(e)[:100])
            return False, str(e)[:100]

    def poll(self, since):
        with self._lock:
            return [l for l in self.lines if l["n"] > since], self.seq


_kst = _KstClient()


@app.route('/kst/status')
@_login_required
def kst_status():
    c = _kst_load()
    return jsonify({"state": _kst.state, "msg": _kst.msg, "login": c["login"],
                    "chat": c["chat"], "has_password": bool(c["password"]), "seq": _kst.seq})


@app.route('/kst/config', methods=['POST'])
@_login_required
def kst_config():
    d = request.get_json(force=True, silent=True) or {}
    c = _kst_load()
    login = str(d.get("login") or "").strip()[:30]
    if login:
        c["login"] = login
    pw = str(d.get("password") or "")
    if pw:
        c["password"] = pw[:60]
    chat = str(d.get("chat") or "").strip()
    if chat.isdigit():
        c["chat"] = chat
    _kst_save(c)
    return jsonify({"ok": True, "has_password": bool(c["password"])})


@app.route('/kst/connect', methods=['POST'])
@_login_required
def kst_connect():
    c = _kst_load()
    _kst.connect(c["login"], c["password"], c["chat"])
    return jsonify({"state": _kst.state, "msg": _kst.msg})


@app.route('/kst/disconnect', methods=['POST'])
@_login_required
def kst_disconnect():
    _kst.disconnect()
    return jsonify({"state": _kst.state})


@app.route('/kst/send', methods=['POST'])
@_login_required
def kst_send():
    d = request.get_json(force=True, silent=True) or {}
    ok, err = _kst.send(d.get("text"))
    return jsonify({"ok": ok, "error": err})


@app.route('/kst/poll')
@_login_required
def kst_poll():
    try:
        since = int(request.args.get("since", "0"))
    except ValueError:
        since = 0
    lines, seq = _kst.poll(since)
    return jsonify({"state": _kst.state, "msg": _kst.msg, "seq": seq, "lines": lines})



