_WX_CARDINALS = ["N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE",
                 "S", "SSO", "SO", "OSO", "O", "ONO", "NO", "NNO"]


def _wx_card(deg):
    """Angle en degrés → point cardinal (16 directions, français)."""
    if deg is None:
        return None
    return _WX_CARDINALS[int((deg + 11.25) / 22.5) % 16]


def _wx_station_latlon():
    """(lat, lon) de la station selon la config (coordonnées ou locator), sinon (None, None)."""
    cfg = config_manager.data
    lat = lon = None
    if cfg.get("geo_mode", "locator") == "coords":
        lat = _safe_float(cfg.get("lat_manual"))
        lon = _safe_float(cfg.get("lon_manual"))
    else:
        g = cfg.get("maidenhead", "")
        if g:
            lat, lon = _grid_to_latlon(g)
    if lat is None or lon is None:
        return None, None
    return lat, lon


def _wx_refractivity(t_c, rh, p_hpa):
    """Refractivité radio N (N-units) : N = 77.6/T · (P + 4810·e/T)."""
    if t_c is None or rh is None or p_hpa is None:
        return None
    import math as _m
    es = 6.112 * _m.exp(17.62 * t_c / (243.12 + t_c))   # pression de vapeur saturante (hPa)
    e  = max(0.0, min(100.0, rh)) / 100.0 * es
    tk = t_c + 273.15
    return 77.6 / tk * (p_hpa + 4810.0 * e / tk)


def _wx_tropo_class(g):
    """Classe ITU-R P.453 selon le gradient de refractivité g (N-units/km)."""
    if g <= -157: return 3, "Conduit troposphérique"
    if g <= -79:  return 2, "Super-réfraction"
    if g <= -60:  return 1, "Réfraction légèrement améliorée"
    return 0, "Propagation normale"


def _wx_tropo_hour(h, i, elev):
    """
    Estimation du gradient vertical de refractivité pour l'heure i à partir du sol
    (T/HR 2 m + pression station) et des niveaux 1000/925/850/700 hPa.
    Retourne [score 0-100, classe 0-3, gradient N/km, inversion 0/1, z_bas m, z_haut m] ou None.
    """
    def g(name):
        arr = h.get(name)
        return arr[i] if arr and 0 <= i < len(arr) else None

    n0 = _wx_refractivity(g("temperature_2m"), g("relative_humidity_2m"), g("surface_pressure"))
    t0 = g("temperature_2m")
    if n0 is None or t0 is None:
        return None
    nodes = [{"z": 0.0, "n": n0, "t": t0}]
    for lvl in (1000, 925, 850, 700):
        t   = g("temperature_%dhPa" % lvl)
        rh  = g("relative_humidity_%dhPa" % lvl)
        gph = g("geopotential_height_%dhPa" % lvl)
        if t is None or rh is None or gph is None:
            continue
        z = gph - elev                       # hauteur au-dessus du sol
        if z < nodes[-1]["z"] + 150:         # niveau sous terre ou trop proche du précédent
            continue
        nodes.append({"z": z, "n": _wx_refractivity(t, rh, lvl), "t": t})
        if z > 3500:
            break
    if len(nodes) < 2:
        return None
    worst = None
    inversion = 0
    for a, b in zip(nodes, nodes[1:]):
        if a["n"] is None or b["n"] is None:
            continue
        grad = (b["n"] - a["n"]) / ((b["z"] - a["z"]) / 1000.0)
        if worst is None or grad < worst[0]:
            worst = (grad, a["z"], b["z"])
        if b["t"] > a["t"] + 0.2:
            inversion = 1
    if worst is None:
        return None
    grad, z1, z2 = worst
    cls, _lbl = _wx_tropo_class(grad)
    score = int(max(0, min(100, round((-grad - 40.0) / (157.0 - 40.0) * 100.0))))
    return [score, cls, int(round(grad)), inversion, int(round(z1)), int(round(z2))]


def _wx_uv_label(uv):
    if uv is None:  return None, None
    if uv < 3:      return "Faible", "Aucune protection nécessaire"
    if uv < 6:      return "Modéré", "Protection conseillée (crème, lunettes)"
    if uv < 8:      return "Élevé", "Protection indispensable, évitez le plein soleil"
    if uv < 11:     return "Très élevé", "Évitez le soleil entre 12 h et 16 h"
    return "Extrême", "Restez à l'ombre aux heures chaudes"


def _wx_pressure_trend(delta):
    """Tendance barométrique sur 3 h → (flèche, libellé)."""
    if delta is None:   return None, None
    if delta >= 3.6:    return "⇈", "Hausse rapide"
    if delta >= 1.6:    return "↗", "En hausse"
    if delta > -1.6:    return "→", "Stable"
    if delta > -3.6:    return "↘", "En baisse"
    return "⇊", "Chute rapide"


def _wx_hour_label(iso):
    """'2026-09-29T14:00' → '14h' ; ajoute le jour si besoin côté appelant."""
    try:
        return "%sh" % iso[11:13]
    except Exception:
        return "?"


def _wx_risks(h, ni):
    """Risques brouillard / verglas-gel sur les 12 prochaines heures + nuit tropicale."""
    times = h["time"]

    def g(name, i):
        arr = h.get(name)
        return arr[i] if arr and 0 <= i < len(arr) else None

    def fog_level(i):
        code = g("weather_code", i)
        vis  = g("visibility", i)
        rh   = g("relative_humidity_2m", i)
        t    = g("temperature_2m", i)
        td   = g("dew_point_2m", i)
        ws   = g("wind_speed_10m", i) or 0
        spread = (t - td) if (t is not None and td is not None) else None
        if code in (45, 48) or (vis is not None and vis < 1000):
            return 2
        if rh is not None and spread is not None and rh >= 97 and spread <= 0.8 and ws < 8:
            return 2
        if vis is not None and vis < 5000 and rh is not None and rh >= 90:
            return 1
        if rh is not None and spread is not None and rh >= 92 and spread <= 2.0 and ws < 12:
            return 1
        return 0

    def ice_level(i):
        code = g("weather_code", i)
        t    = g("temperature_2m", i)
        rh   = g("relative_humidity_2m", i)
        pr   = g("precipitation", i) or 0
        ws   = g("wind_speed_10m", i) or 0
        cl   = g("cloud_cover", i)
        rad  = g("shortwave_radiation", i)
        if t is None:
            return 0
        recent = sum((g("precipitation", k) or 0) for k in range(i - 5, i + 1))
        if code in (56, 57, 66, 67):
            return 2
        if t <= 0.5 and (pr >= 0.1 or recent >= 0.3):
            return 2                           # pluie / chaussée mouillée qui gèle → verglas
        night = (rad is not None and rad < 10)
        if t <= 1.5 and rh is not None and rh >= 85:
            return 1                           # givre / gelée blanche possible
        if t <= 2.0 and night and cl is not None and cl < 30 and ws < 10:
            return 1                           # nuit claire et calme : gelée au sol
        return 0

    out = {}
    for name, fn, txt2, txt1 in (
        ("fog", fog_level, "Brouillard probable", "Brouillard possible"),
        ("ice", ice_level, "Risque de verglas",   "Gelée / givre possible"),
    ):
        worst, when = 0, None
        for i in range(ni, min(ni + 13, len(times))):
            lv = fn(i)
            if lv > worst:
                worst, when = lv, i
        out[name] = {
            "level": worst,
            "text":  txt2 if worst == 2 else (txt1 if worst == 1 else "Aucun risque détecté"),
            "when":  (_wx_hour_label(times[when]) if (when is not None and when > ni) else ("maintenant" if worst else None)),
        }

    # Nuit tropicale : ≥ 6 h nocturnes (21 h–6 h) toutes à ≥ 20 °C dans les 24 h qui viennent
    night_t = []
    for i in range(ni, min(ni + 25, len(times))):
        hh = int(times[i][11:13])
        t = g("temperature_2m", i)
        if t is not None and (hh >= 21 or hh <= 6):
            night_t.append(t)
    out["tropical_night"] = bool(len(night_t) >= 6 and min(night_t) >= 20.0)
    out["night_min"] = round(min(night_t), 1) if night_t else None
    return out


def _wx_air_quality(lat, lon, cur_hour):
    """Qualité de l'air + pollens (Open-Meteo Air Quality). None si indisponible."""
    import urllib.request, json as _j
    url = (
        "https://air-quality-api.open-meteo.com/v1/air-quality"
        "?latitude=%.5f&longitude=%.5f"
        "&current=european_aqi,pm10,pm2_5,ozone,nitrogen_dioxide"
        "&hourly=alder_pollen,birch_pollen,grass_pollen,mugwort_pollen,olive_pollen,ragweed_pollen"
        "&forecast_days=2&timezone=auto"
    ) % (lat, lon)
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "aprs_station/2.5"})
        with urllib.request.urlopen(req, timeout=8) as r:
            raw = _j.loads(r.read())
    except Exception as e:
        logger.warning("[WX-EXTRA] air-quality indisponible : %s", e)
        return None

    cur = raw.get("current") or {}
    aqi = cur.get("european_aqi")
    if aqi is None:      aq_lbl = None
    elif aqi <= 20:      aq_lbl = "Bon"
    elif aqi <= 40:      aq_lbl = "Correct"
    elif aqi <= 60:      aq_lbl = "Moyen"
    elif aqi <= 80:      aq_lbl = "Médiocre"
    elif aqi <= 100:     aq_lbl = "Mauvais"
    else:                aq_lbl = "Très mauvais"

    pollens = []
    hh = raw.get("hourly") or {}
    times = hh.get("time") or []
    idx = times.index(cur_hour) if cur_hour in times else 0
    for key, name in (("alder_pollen", "Aulne"), ("birch_pollen", "Bouleau"),
                      ("grass_pollen", "Graminées"), ("mugwort_pollen", "Armoise"),
                      ("olive_pollen", "Olivier"), ("ragweed_pollen", "Ambroisie")):
        arr = hh.get(key) or []
        v = arr[idx] if idx < len(arr) else None
        if v is None:
            continue
        if v < 1:      lvl, lb = 0, "Absent"
        elif v < 20:   lvl, lb = 1, "Faible"
        elif v < 80:   lvl, lb = 2, "Modéré"
        elif v < 200:  lvl, lb = 3, "Élevé"
        else:          lvl, lb = 4, "Très élevé"
        pollens.append({"name": name, "value": round(v, 1), "level": lvl, "label": lb})
    return {
        "aqi": aqi, "aqi_label": aq_lbl,
        "pm2_5": cur.get("pm2_5"), "pm10": cur.get("pm10"),
        "o3": cur.get("ozone"), "no2": cur.get("nitrogen_dioxide"),
        "pollen": pollens,
    }


def _wx_extra_data(lat, lon, force=False):
    """
    Récupère et prépare toutes les données météo étendues (cache 10 min).
    Utilisé par la route /weather_extra, les alertes avancées et la balise WX.
    """
    import urllib.request, json as _j, time as _t
    from datetime import datetime, timezone

    key = "%.3f,%.3f" % (lat, lon)
    with _WX_EXTRA_LOCK:
        c = _WX_EXTRA_CACHE.get(key)
        if c and not force and (_t.time() - c["ts"]) < _WX_EXTRA_TTL_S:
            return c["payload"]

        url = (
            "https://api.open-meteo.com/v1/forecast"
            "?latitude=%.5f&longitude=%.5f"
            "&current=temperature_2m,relative_humidity_2m,apparent_temperature,is_day,"
            "precipitation,weather_code,cloud_cover,pressure_msl,surface_pressure,"
            "wind_speed_10m,wind_direction_10m,wind_gusts_10m"
            "&hourly=temperature_2m,relative_humidity_2m,dew_point_2m,precipitation,snowfall,"
            "weather_code,pressure_msl,surface_pressure,cloud_cover,visibility,wind_speed_10m,"
            "uv_index,shortwave_radiation,freezing_level_height,"
            "precipitation_probability,wind_gusts_10m,wind_direction_10m,apparent_temperature,is_day,"
            "temperature_1000hPa,temperature_925hPa,temperature_850hPa,temperature_700hPa,"
            "relative_humidity_1000hPa,relative_humidity_925hPa,relative_humidity_850hPa,relative_humidity_700hPa,"
            "geopotential_height_1000hPa,geopotential_height_925hPa,geopotential_height_850hPa,geopotential_height_700hPa"
            "&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_sum,"
            "precipitation_probability_max,snowfall_sum,sunrise,sunset,sunshine_duration,"
            "daylight_duration,uv_index_max,wind_gusts_10m_max,wind_direction_10m_dominant"
            "&past_days=2&forecast_days=7&wind_speed_unit=kmh&timezone=auto"
        ) % (lat, lon)
        req = urllib.request.Request(url, headers={"User-Agent": "aprs_station/2.5"})
        with urllib.request.urlopen(req, timeout=10) as r:
            raw = _j.loads(r.read())

        h     = raw["hourly"]
        times = h["time"]
        cur   = raw.get("current") or {}
        daily = raw.get("daily") or {}
        elev  = raw.get("elevation") or 0.0

        # ── Index de l'heure courante dans le tableau horaire ────────────────
        cur_hour = (cur.get("time") or "")[:13] + ":00"
        if cur_hour not in times:
            off = raw.get("utc_offset_seconds") or 0
            cur_hour = datetime.fromtimestamp(_t.time() + off, timezone.utc).strftime("%Y-%m-%dT%H:00")
        if cur_hour not in times:
            raise ValueError("heure courante introuvable dans la réponse Open-Meteo")
        ni = times.index(cur_hour)

        def g(name, i):
            arr = h.get(name)
            return arr[i] if arr and 0 <= i < len(arr) else None

        def ssum(name, a, b):
            return round(sum((g(name, k) or 0) for k in range(max(0, a), min(len(times), b))), 2)

        # ── Pression et tendance ─────────────────────────────────────────────
        p_msl = cur.get("pressure_msl")
        if p_msl is None:
            p_msl = g("pressure_msl", ni)
        p_ref = g("pressure_msl", ni)
        p_3h  = g("pressure_msl", ni - 3)
        delta = round(p_ref - p_3h, 1) if (p_ref is not None and p_3h is not None) else None
        arrow, trend_lbl = _wx_pressure_trend(delta)

        code = cur.get("weather_code", g("weather_code", ni))
        icon, label = _WX_WMO_FR.get(code, ("🌡️", "Conditions inconnues"))
        uv = g("uv_index", ni)
        uv_lbl, uv_adv = _wx_uv_label(uv)
        vis = g("visibility", ni)

        now = {
            "temp":            cur.get("temperature_2m"),
            "feels":           cur.get("apparent_temperature"),
            "humidity":        cur.get("relative_humidity_2m"),
            "dew_point":       g("dew_point_2m", ni),
            "pressure_msl":    p_msl,
            "pressure_delta_3h": delta,
            "pressure_arrow":  arrow,
            "pressure_trend":  trend_lbl,
            "wind_kmh":        cur.get("wind_speed_10m"),
            "wind_dir":        cur.get("wind_direction_10m"),
            "wind_card":       _wx_card(cur.get("wind_direction_10m")),
            "gust_kmh":        cur.get("wind_gusts_10m"),
            "cloud":           cur.get("cloud_cover"),
            "visibility_km":   round(vis / 1000.0, 1) if vis is not None else None,
            "uv":              uv,
            "uv_label":        uv_lbl,
            "uv_advice":       uv_adv,
            "code":            code,
            "icon":            icon,
            "label":           label,
            "is_day":          cur.get("is_day"),
            "precip_mm":       cur.get("precipitation"),
            "freezing_level_m": g("freezing_level_height", ni),
            "radiation":       g("shortwave_radiation", ni),
            "snow_24h_cm":     ssum("snowfall", ni + 1, ni + 25),
        }

        # ── Prévisions journalières (aujourd'hui + 6 jours) ──────────────────
        dtimes = daily.get("time") or []
        today  = times[ni][:10]
        d0 = dtimes.index(today) if today in dtimes else min(2, max(0, len(dtimes) - 1))

        def dv(name, k):
            arr = daily.get(name)
            return arr[k] if arr and 0 <= k < len(arr) else None

        def hhmm(iso):
            return iso[11:16] if iso else None

        days = []
        for k in range(d0, min(d0 + 7, len(dtimes))):
            c2 = dv("weather_code", k)
            ic2, lb2 = _WX_WMO_FR.get(c2, ("🌡️", "—"))
            sun_s = dv("sunshine_duration", k)
            day_s = dv("daylight_duration", k)
            days.append({
                "date":     dtimes[k],
                "code":     c2, "icon": ic2, "label": lb2,
                "tmax":     dv("temperature_2m_max", k),
                "tmin":     dv("temperature_2m_min", k),
                "precip":   dv("precipitation_sum", k),
                "pop":      dv("precipitation_probability_max", k),
                "snow_cm":  dv("snowfall_sum", k),
                "sunrise":  hhmm(dv("sunrise", k)),
                "sunset":   hhmm(dv("sunset", k)),
                "sun_h":    round(sun_s / 3600.0, 1) if sun_s is not None else None,
                "day_h":    round(day_s / 3600.0, 1) if day_s is not None else None,
                "uv_max":   dv("uv_index_max", k),
                "gust_max": dv("wind_gusts_10m_max", k),
                "wind_dir": dv("wind_direction_10m_dominant", k),
                "wind_card": _wx_card(dv("wind_direction_10m_dominant", k)),
            })

        # ── Fenêtre horaire des graphes : 48 h passées + 48 h prévues ────────
        a = max(0, ni - 47)
        b = min(len(times), ni + 49)

        def sl(name, nd=1):
            arr = h.get(name) or []
            return [None if v is None else round(v, nd) for v in arr[a:b]]

        tropo = [_wx_tropo_hour(h, i, elev) for i in range(a, b)]
        tropo_now = tropo[ni - a] if 0 <= ni - a < len(tropo) else None
        peak = None
        for j, tv in enumerate(tropo):
            if tv is None or j < ni - a:          # pic recherché à partir de maintenant
                continue
            if peak is None or tv[0] > peak["score"]:
                peak = {"score": tv[0], "cls": tv[1], "index": j, "time": times[a + j]}

        # ── HOURLY_FC_PATCH_v1 : prévisions heure par heure (24 h suivantes) ──
        def _hentry(k):
            ck = g("weather_code", k)
            ick, lbk = _WX_WMO_FR.get(ck, ("🌡️", "—"))
            if g("is_day", k) == 0 and ck in (0, 1):
                ick = "🌙"
            dk = g("wind_direction_10m", k)
            return {
                "time":      times[k],
                "temp":      g("temperature_2m", k),
                "feels":     g("apparent_temperature", k),
                "code":      ck, "icon": ick, "label": lbk,
                "precip":    g("precipitation", k),
                "pop":       g("precipitation_probability", k),
                "wind":      g("wind_speed_10m", k),
                "gust":      g("wind_gusts_10m", k),
                "wind_dir":  dk,
                "wind_card": _wx_card(dk),
                "is_day":    g("is_day", k),
                "hum":       g("relative_humidity_2m", k),
            }

        hourly_fc = [_hentry(k) for k in range(ni + 1, min(len(times), ni + 25))]

        # DAILY_HOURS_PATCH_v1 : météo à chaque heure pour les 7 jours (de 00h aujourd'hui à +168 h)
        hourly_week = []
        _k0 = next((k for k in range(len(times)) if times[k][:10] == today), ni)
        for k in range(_k0, min(len(times), _k0 + 168)):
            e = _hentry(k)
            e["past"] = k < ni
            e["now"]  = (k == ni)
            hourly_week.append(e)

        # ── Agrégats pour la balise WX APRS (pluie 1 h / 24 h / minuit, luminosité) ──
        midnight_idx = next((k for k in range(ni, -1, -1) if times[k][:10] != today), -1) + 1
        beacon = {
            "rain_1h_mm":       g("precipitation", ni) or 0.0,
            "rain_24h_mm":      ssum("precipitation", ni - 23, ni + 1),
            "rain_midnight_mm": ssum("precipitation", midnight_idx, ni + 1),
            "lum_wm2":          g("shortwave_radiation", ni),
        }

        payload = {
            "location":  "%.3f, %.3f" % (lat, lon),
            "elevation": round(elev),
            "generated": _t.time(),
            "now":       now,
            "sun":       days[0] if days else None,
            "daily":     days,
            "risks":     _wx_risks(h, ni),
            "hourly_fc": hourly_fc,
            "hourly_week": hourly_week,
            "hourly": {
                "time":         times[a:b],
                "now_index":    ni - a,
                "temperature":  sl("temperature_2m"),
                "humidity":     sl("relative_humidity_2m", 0),
                "dew_point":    sl("dew_point_2m"),
                "pressure_msl": sl("pressure_msl"),
                "cloud":        sl("cloud_cover", 0),
            },
            "tropo": {
                "hourly": tropo,
                "now":    tropo_now,
                "peak":   peak,
                "pressure_hpa": p_msl,
            },
            "beacon": beacon,
            "air":    _wx_air_quality(lat, lon, cur_hour),
        }
        _WX_EXTRA_CACHE[key] = {"payload": payload, "ts": _t.time()}
        return payload


def _wx_neighbors(lat, lon, model_temp=None, max_km=200.0, limit=12, max_age_s=6 * 3600):
    """Stations météo APRS entendues récemment (RF + IS) dans un rayon max_km."""
    import time as _t
    my_call = (config_manager.data.get("callsign", "") or "").upper().split("-")[0]
    now = _t.time()
    with rx_history_lock:
        snap = list(rx_history)
    latest = {}
    for fr in snap:
        if fr.get("aprs_type") != "Meteo":
            continue
        src = (fr.get("src") or "").upper().strip()
        if not src or src.split("-")[0] == my_call:
            continue
        ts = fr.get("_ts") or 0
        if now - ts > max_age_s:
            continue
        e = fr.get("extra") or {}
        if e.get("temp_c") is None and e.get("pressure_hpa") is None and e.get("wind_speed_kmh") is None:
            continue
        la, lo = e.get("lat"), e.get("lon")
        if la is None or lo is None:
            with stations_positions_lock:
                sp = stations_positions.get(src) or {}
            la, lo = sp.get("lat"), sp.get("lon")
        if la is None or lo is None:
            continue
        latest[src] = (ts, fr, e, la, lo)

    rows = []
    for src, (ts, fr, e, la, lo) in latest.items():
        d = _welcome_dist_km(lat, lon, la, lo)
        if d > max_km:
            continue
        rows.append({
            "src":      src,
            "dist_km":  round(d, 1),
            "age_min":  int(round((now - ts) / 60.0)),
            "source":   "IS" if fr.get("_source") == "IS" else "RF",
            "temp":     e.get("temp_c"),
            "humidity": e.get("humidity_pct"),
            "wind_kmh": e.get("wind_speed_kmh"),
            "gust_kmh": e.get("gust_kmh"),
            "pressure": e.get("pressure_hpa"),
            "rain_1h":  e.get("rain_1h_mm"),
            "lum":      e.get("luminosity_wm2"),
        })
    rows.sort(key=lambda r: r["dist_km"])
    rows = rows[:limit]
    temps = sorted(r["temp"] for r in rows if r["temp"] is not None)
    med = temps[len(temps) // 2] if temps else None
    return {
        "stations": rows,
        "count":    len(rows),
        "median_temp": med,
        "delta_vs_model": (round(med - model_temp, 1) if (med is not None and model_temp is not None) else None),
    }


# ── CHANNEL_USAGE_PATCH_v1 — taux d'utilisation de la fréquence APRS + conseils ──
_CU_LOCK   = threading.Lock()
_CU_FRAMES = collections.deque()      # (ts, airtime_s, src, is_tx, ndigi, plen)
_CU_START  = time.time()


def _cu_record(frame):
    """Appelé pour chaque trame RF reçue ou émise (hors APRS-IS). Estime la durée d'antenne."""
    try:
        t = frame.get("type")
        if t == "rx_level" or not frame.get("src"):
            return
        is_tx = (t == "tx_event")
        if not is_tx and frame.get("_source") == "IS":
            return
        ndigi = len([p for p in str(frame.get("path") or "").split(",") if p])
        plen = len(frame.get("payload") or "")
        pre = 0.3                              # préambule (TXDELAY) typique d'une station distante
        if is_tx:
            try:
                pre = max(0.05, float(config_manager.data.get("tx_delay_ms", 300)) / 1000.0)
            except Exception:
                pre = 0.3
        bits = (18 + 7 * ndigi + plen) * 8 * 1.1 + 16      # en-tête AX.25 + FCS + bit stuffing + fanions
        now = time.time()
        with _CU_LOCK:
            _CU_FRAMES.append((now, bits / 1200.0 + pre, str(frame.get("src")).upper(), is_tx, ndigi, plen))
            cutoff = now - 86400
            while _CU_FRAMES and _CU_FRAMES[0][0] < cutoff:
                _CU_FRAMES.popleft()
    except Exception:
        pass


def _cu_hops(path):
    """Nombre de sauts demandés par un chemin (WIDE2-2 → 2, TRACE3-3 → 3)."""
    import re as _cu_re
    n = 0
    for p in str(path or "").split(","):
        p = p.strip().upper()
        if not p:
            continue
        m = _cu_re.match(r"^(WIDE|TRACE)[1-7]-([1-7])$", p)
        n += int(m.group(2)) if m else 1
    return n


def _cu_payload():
    now = time.time()
    cfg = config_manager.data
    my = (cfg.get("callsign", "") or "").upper()
    with _CU_LOCK:
        snap = list(_CU_FRAMES)
    up = now - _CU_START

    def pct(air, sec):
        span = max(60.0, min(float(sec), up))
        return round(min(100.0, air / span * 100.0), 2)

    wins = {}
    for label, sec in (("m5", 300), ("h1", 3600), ("h24", 86400)):
        sel = [f for f in snap if f[0] >= now - sec]
        wins[label] = {
            "frames":   len(sel),
            "stations": len({f[2] for f in sel if not f[3]}),
            "pct":      pct(sum(f[1] for f in sel), sec),
            "tx_pct":   pct(sum(f[1] for f in sel if f[3]), sec),
        }

    hours = []                                   # 24 tranches d'une heure, la dernière = heure écoulée
    for i in range(24):
        t0 = now - (24 - i) * 3600
        t1 = t0 + 3600
        if t1 <= _CU_START:
            hours.append(None)
            continue
        air = sum(f[1] for f in snap if t0 <= f[0] < t1)
        span = 3600.0 if t0 >= _CU_START else max(60.0, t1 - _CU_START)
        hours.append(round(min(100.0, air / span * 100.0), 2))

    h1 = [f for f in snap if f[0] >= now - 3600]
    tot = sum(f[1] for f in h1)
    agg = {}
    for f in h1:
        a = agg.setdefault(f[2], [0.0, 0])
        a[0] += f[1]
        a[1] += 1
    top = []
    span_min = min(3600.0, max(60.0, up)) / 60.0
    for src, (air, n) in sorted(agg.items(), key=lambda kv: -kv[1][0])[:5]:
        top.append({"src": src, "frames": n, "own": (src == my),
                    "share": int(round(air / tot * 100.0)) if tot else 0,
                    "every_min": round(span_min / n, 1)})

    mine = [f for f in h1 if f[3]]
    own_air = sum(f[1] for f in mine)
    own = {"frames": len(mine), "pct": pct(own_air, 3600),
           "share": int(round(own_air / tot * 100.0)) if tot else 0,
           "avg_len": int(round(sum(f[5] for f in mine) / len(mine))) if mine else None}
    heard = [f for f in h1 if not f[3]]
    long_share = int(round(100.0 * len([f for f in heard if f[4] >= 3]) / len(heard))) if heard else 0

    p = wins["h1"]["pct"]
    if p < 3:
        lvl, lab = 0, "Canal très libre"
    elif p < 10:
        lvl, lab = 0, "Canal peu chargé"
    elif p < 20:
        lvl, lab = 1, "Charge modérée"
    elif p < 30:
        lvl, lab = 2, "Canal chargé"
    else:
        lvl, lab = 2, "Canal saturé"

    adv = []

    def add(level, icon, text):
        adv.append({"level": level, "icon": icon, "text": text})

    if p < 3:
        add(0, "✅", "Canal très libre : aucune optimisation nécessaire.")
    elif p < 10:
        add(0, "✅", "Charge faible : le canal absorbe sans problème balises et messages.")
    elif p < 20:
        add(1, "⚠️", "Charge modérée : évitez les balises superflues et gardez des chemins courts.")
    elif p < 30:
        add(2, "🚦", "Canal chargé : les collisions deviennent fréquentes et certaines trames se perdent. Réduisez votre trafic et vos sauts.")
    else:
        add(2, "🛑", "Canal saturé (plus de 30 %) : le débit utile s'effondre. Limitez fortement vos émissions.")

    path = cfg.get("path", "") or ""
    hops = _cu_hops(path)
    if hops > 2:
        add(2 if hops >= 4 else 1, "🛤️",
            "Votre chemin « %s » demande jusqu'à %d sauts : chaque saut répète la trame sur le canal. Utilisez WIDE1-1,WIDE2-1 (2 sauts maximum)." % (path, hops))
    try:
        bi = int(cfg.get("beacon_interval", 0) or 0)
    except Exception:
        bi = 0
    if 0 < bi < 10:
        add(1, "⏱️", "Balise automatique toutes les %d min : pour une station fixe, 10 à 30 min suffisent." % bi)
    if own["frames"] >= 6 and own["share"] >= 25 and p >= 5:
        add(1, "📤", "Votre station occupe %d %% du temps d'antenne utilisé (%d trames en 1 h) : espacez balises, météo et bulletins." % (own["share"], own["frames"]))
    if own["avg_len"] is not None and own["avg_len"] > 80 and own["frames"] >= 3:
        add(1, "✂️", "Vos trames font en moyenne %d caractères : raccourcissez commentaires et bulletins (une trame courte occupe moins le canal)." % own["avg_len"])
    if len(heard) >= 10 and long_share >= 25:
        add(1, "🔁", "%d %% des trames entendues traversent 3 relais ou plus : les longs chemins (WIDE2-2 et plus) multiplient la charge." % long_share)
    if p >= 5:
        for t in top:
            if (not t["own"]) and t["frames"] >= 8 and t["share"] >= 30:
                add(1, "📡", "%s occupe %d %% du canal (%d trames en 1 h, une toutes les %s min) : balise très fréquente ou boucle de relais." % (t["src"], t["share"], t["frames"], t["every_min"]))
                break
    if cfg.get("digi_enabled"):
        try:
            dl = int(cfg.get("digi_limit", 2) or 2)
        except Exception:
            dl = 2
        if dl > 2:
            add(1, "🔧", "Votre digipeater accepte %d sauts : limitez-le à 2 (paramètre « sauts max »)." % dl)
        if p >= 15:
            add(1, "🔧", "Canal chargé : désactivez le digipeater ou ne relayez que WIDE1-1 pour ne pas ajouter de trafic.")

    return {"ts": now, "uptime_s": int(up), "windows": wins, "hours": hours, "top": top,
            "own": own, "level": lvl, "label": lab, "advice": adv,
            "note": "Estimation : durée des trames à 1200 bauds (préambule inclus), RF uniquement (hors APRS-IS), vos émissions comprises, depuis le dernier démarrage."}


@app.route('/channel_usage')
@_login_required
def channel_usage():
    import json as _j
    hdr = {'Content-Type': 'application/json'}
    try:
        return _j.dumps(_cu_payload(), ensure_ascii=False), 200, hdr
    except Exception as e:
        logger.error("[CHANNEL-USAGE] %s", e)
        return _j.dumps({"error": str(e)}), 500, hdr


@app.route('/weather_extra')
@_login_required
def weather_extra():
    """Météo étendue (Maintenant, 7 jours, pression, UV, risques, tropo, air) + stations WX voisines."""
    import json as _j
    hdr = {'Content-Type': 'application/json'}
    lat, lon = _wx_station_latlon()
    _cname = None   # WX_CITY_PICK_v1 : ville choisie dans le panneau « Maintenant »
    try:
        _clat = float(request.args.get('lat', ''))
        _clon = float(request.args.get('lon', ''))
        if -90.0 <= _clat <= 90.0 and -180.0 <= _clon <= 180.0:
            lat, lon = round(_clat, 3), round(_clon, 3)
            _cname = (request.args.get('name') or '').strip()[:60] or None
    except (TypeError, ValueError):
        pass
    if lat is None:
        return _j.dumps({"error": "Coordonnées station non configurées"}), 400, hdr
    try:
        data = dict(_wx_extra_data(lat, lon, force=(request.args.get('refresh') == '1')))
    except Exception as e:
        logger.error("[WX-EXTRA] %s", e)
        return _j.dumps({"error": str(e)}), 502, hdr
    data.pop("beacon", None)      # usage interne (balise APRS)
    if _cname:
        data["location"] = _cname   # WX_CITY_PICK_v1
    try:
        data["neighbors"] = _wx_neighbors(lat, lon, model_temp=(data.get("now") or {}).get("temp"))
    except Exception as e:
        logger.warning("[WX-EXTRA] voisines : %s", e)
        data["neighbors"] = {"stations": [], "count": 0, "median_temp": None, "delta_vs_model": None}
    return _j.dumps(data, default=str), 200, hdr


@app.route('/geocode_city')
@_login_required
def geocode_city():
    """WX_CITY_PICK_v1 : recherche de villes par nom (Open-Meteo Geocoding, gratuit, sans clé)."""
    q = (request.args.get('q') or '').strip()[:60]
    if len(q) < 2:
        return jsonify({"results": []})
    try:
        js = _sw_http_json("https://geocoding-api.open-meteo.com/v1/search?" + _sw_up.urlencode(
            {"name": q, "count": 6, "language": "fr", "format": "json"}))
    except Exception as e:
        logger.warning("[WX-CITY] Géocodage : %s", e)
        return jsonify({"results": [], "error": str(e)[:120]}), 502
    out = []
    for r in (js.get("results") or []):
        if r.get("latitude") is None or r.get("longitude") is None:
            continue
        out.append({"name": r.get("name") or "?", "admin1": r.get("admin1") or "",
                    "country_code": r.get("country_code") or "",
                    "lat": round(float(r["latitude"]), 4), "lon": round(float(r["longitude"]), 4)})
    return jsonify({"results": out})

