# ══════════════════════════════════════════════════════════════════════════════
# ── Détection d'ouragans (NHC / NOAA) ── HURRICANE_WATCH_v1 ───────────────────
# Source : https://www.nhc.noaa.gov/CurrentStorms.json (officielle, gratuite,
# sans clé). Couvre l'Atlantique et le Pacifique Est/Central uniquement (pas les
# typhons du Pacifique Ouest ni l'océan Indien).
# Alerte : bannière + bip via le canal SSE "weather_alert" existant, et en
# option bulletin RF BLNWX8 (via _wx_send_aprs_bulletin(force=True)).
# ══════════════════════════════════════════════════════════════════════════════
_HURR_URL = "https://www.nhc.noaa.gov/CurrentStorms.json"
_HURR_CLASS_FR = {
    "TD":  "Dépression tropicale",
    "STD": "Dépression subtropicale",
    "TS":  "Tempête tropicale",
    "HU":  "Ouragan",
    "STS": "Tempête subtropicale",
    "PTC": "Cyclone post-tropical",
    "PC":  "Cyclone tropical potentiel",
    "TY":  "Typhon",
}
_HURR_COMPASS = ["N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE",
                 "S", "SSO", "SO", "OSO", "O", "ONO", "NO", "NNO"]
_hurr_lock  = threading.Lock()
_hurr_state = {"storms": [], "ts": 0.0, "ok": False, "error": ""}


def _hurr_cfg():
    cfg = dict(DEFAULT_CONFIG["hurricane_watch"])
    cfg.update(config_manager.data.get("hurricane_watch") or {})
    return cfg


def _hurr_compass(deg):
    try:
        return _HURR_COMPASS[int((float(deg) % 360) / 22.5 + 0.5) % 16]
    except Exception:
        return ""


def _hurr_num(v):
    try:
        if v is None or v == "":
            return None
        return float(v)
    except (TypeError, ValueError):
        return None


def _hurr_coord(v_num, v_str):
    """Coordonnée décimale : champ numérique, sinon repli sur '22.9N' / '79.9W'."""
    x = _hurr_num(v_num)
    if x is not None:
        return x
    try:
        import re as _re
        m = _re.match(r"^\s*([0-9]+(?:\.[0-9]+)?)\s*([NSEWnsew])\s*$", str(v_str or ""))
        if m:
            val = float(m.group(1))
            return -val if m.group(2).upper() in ("S", "W") else val
    except Exception:
        pass
    return None


def _hurr_category(cls, kt):
    """Catégorie Saffir-Simpson (1-5) d'après le vent soutenu en nœuds ; 0 = pas un ouragan."""
    if kt is None:
        return 1 if cls in ("HU", "TY") else 0
    if kt >= 137: return 5
    if kt >= 113: return 4
    if kt >= 96:  return 3
    if kt >= 83:  return 2
    if kt >= 64:  return 1
    return 0


def _hurricane_parse(raw, ref_lat, ref_lon):
    """Transforme le JSON NHC en liste de dicts (distance/cap par rapport à la station)."""
    storms = []
    for s in (raw.get("activeStorms") or []):
        try:
            lat = _hurr_coord(s.get("latitude_numeric", s.get("latitudeNumeric")), s.get("latitude"))
            lon = _hurr_coord(s.get("longitude_numeric", s.get("longitudeNumeric")), s.get("longitude"))
            if lat is None or lon is None:
                continue
            cls  = str(s.get("classification") or "").upper()
            kt   = _hurr_num(s.get("intensity"))
            cat  = _hurr_category(cls, kt)
            dist = _welcome_dist_km(ref_lat, ref_lon, lat, lon)
            brg  = _lightning_bearing_deg(ref_lat, ref_lon, lat, lon)    # station -> cyclone
            back = _lightning_bearing_deg(lat, lon, ref_lat, ref_lon)    # cyclone -> station
            mdir = _hurr_num(s.get("movementDir"))
            mph  = _hurr_num(s.get("movementSpeed"))
            approaching = False
            if mdir is not None and mph and mph > 0:
                approaching = abs((mdir - back + 540) % 360 - 180) <= 45
            pa = s.get("publicAdvisory") or {}
            storms.append({
                "id":           str(s.get("id") or s.get("name") or ""),
                "name":         str(s.get("name") or "?"),
                "class":        cls,
                "class_fr":     _HURR_CLASS_FR.get(cls, cls or "Cyclone"),
                "kt":           kt,
                "kmh":          int(round(kt * 1.852)) if kt is not None else None,
                "category":     cat,
                "pressure":     _hurr_num(s.get("pressure")),
                "lat":          round(lat, 2),
                "lon":          round(lon, 2),
                "dist_km":      int(round(dist)),
                "bearing_deg":  int(round(brg)),
                "bearing_txt":  _hurr_compass(brg),
                "move_dir":     mdir,
                "move_dir_txt": _hurr_compass(mdir) if mdir is not None else "",
                "move_kmh":     int(round(mph * 1.609)) if mph is not None else None,
                "approaching":  approaching,
                "last_update":  str(s.get("lastUpdate") or ""),
                "url":          str(pa.get("url") or "") if isinstance(pa, dict) else "",
            })
        except Exception as _e:
            logger.debug("[HURRICANE] Tempête ignorée (parse) : %s", _e)
    storms.sort(key=lambda x: x["dist_km"])
    return storms


def _hurricane_fetch(ref_lat, ref_lon):
    import urllib.request
    req = urllib.request.Request(_HURR_URL, headers={"User-Agent": "Py-APRS/2.9 (F1RIQ)"})
    with urllib.request.urlopen(req, timeout=15) as resp:
        raw = json.loads(resp.read().decode("utf-8", "replace"))
    return _hurricane_parse(raw, ref_lat, ref_lon)


def _hurricane_alert_frame(s):
    """Trame SSE 'weather_alert' (bannière + bip + badge header déjà gérés côté client)."""
    cat = s["category"]
    name = s["name"]
    kmh  = s["kmh"]
    if cat >= 1:
        title = "Ouragan %s — cat. %d%s" % (name, cat, (" (%d km/h)" % kmh) if kmh is not None else "")
    else:
        title = "%s %s%s" % (s["class_fr"], name, (" (%d km/h)" % kmh) if kmh is not None else "")
    detail = "À %d km de la station (cap %s)" % (s["dist_km"], s["bearing_txt"])
    if s["approaching"]:
        detail += " · se dirige vers la station"
    if s["pressure"] is not None:
        detail += " · %d hPa" % int(s["pressure"])
    if cat >= 3:
        col = ("#dc2626", "#4c0519", "#fecdd3")
    elif cat >= 1:
        col = ("#ef4444", "#450a0a", "#fca5a5")
    else:
        col = ("#f97316", "#431407", "#fdba74")
    return {
        "type":         "weather_alert",
        "key":          "hurricane_%s_%s" % (s["id"], ("c%d" % cat) if cat else "ts"),
        "icon":         "🌀",
        "title":        title,
        "detail":       detail,
        "color_border": col[0],
        "color_bg":     col[1],
        "color_text":   col[2],
        "temp_c":       None,
        "wind_kmh":     kmh,
        "description":  None,
    }


def _hurricane_check_alerts(storms, cfg):
    """Diffuse les alertes des cyclones qualifiants (anti-spam 6 h par tempête et par niveau)."""
    min_level = str(cfg.get("min_level", "HU")).upper()
    radius = _hurr_num(cfg.get("alert_radius_km")) or 0.0
    for s in storms:
        cat   = s["category"]
        is_ts = s["class"] in ("TS", "STS") or (s["kt"] or 0) >= 34
        if not (cat >= 1 or (min_level == "TS" and is_ts)):
            continue
        if radius > 0 and s["dist_km"] > radius:
            continue
        frame = _hurricane_alert_frame(s)
        if not _wx_should_alert(frame["key"], 6 * 3600.0):
            continue
        for _q in list(listeners):
            try: _q.put_nowait(frame)
            except Exception: pass
        logger.warning("[HURRICANE] %s — %s — %s", frame["key"], frame["title"], frame["detail"])
        if cfg.get("bulletin_aprs"):
            # Texte RF : ASCII, sans accent (limite 67 car. appliquée par l'émetteur)
            if cat >= 1:
                rf = "OURAGAN %s Cat%d %skm/h a %dkm" % (
                    s["name"].upper(), cat, s["kmh"] if s["kmh"] is not None else "?", s["dist_km"])
            else:
                rf = "TEMPETE TROPICALE %s %skm/h a %dkm" % (
                    s["name"].upper(), s["kmh"] if s["kmh"] is not None else "?", s["dist_km"])
            _wx_send_aprs_bulletin("🌀", rf, frame["detail"], 8, force=True)


def _hurricane_refresh(alerts=True):
    """Interroge le NHC, met à jour l'état partagé, déclenche les alertes si demandé."""
    cfg = _hurr_cfg()
    ref_lat, ref_lon = _lightning_center()
    try:
        storms = _hurricane_fetch(ref_lat, ref_lon)
    except Exception as e:
        with _hurr_lock:
            _hurr_state.update({"ok": False, "error": str(e)[:200], "ts": time.time()})
        logger.warning("[HURRICANE] Échec consultation NHC : %s", e)
        return
    with _hurr_lock:
        _hurr_state.update({"storms": storms, "ok": True, "error": "", "ts": time.time()})
    logger.info("[HURRICANE] %d cyclone(s) actif(s) dans le flux NHC", len(storms))
    if alerts and cfg.get("enabled"):
        _hurricane_check_alerts(storms, cfg)


def _hurricane_worker():
    """Thread daemon : consulte le NHC toutes les interval_min minutes (min. 15) si activé."""
    while True:
        try:
            cfg = _hurr_cfg()
            if cfg.get("enabled"):
                interval = max(15.0, _hurr_num(cfg.get("interval_min")) or 60.0) * 60.0
                if time.time() - _hurr_state["ts"] >= interval:
                    _hurricane_refresh()
        except Exception as _e:
            logger.error("[HURRICANE] Erreur worker : %s", _e)
        time.sleep(20)


threading.Thread(target=_hurricane_worker, daemon=True, name="hurricane-worker").start()
logger.info("[HURRICANE] Worker thread démarré (inactif tant que non activé en config)")


def _hurricane_status_payload():
    cfg = _hurr_cfg()
    with _hurr_lock:
        st = dict(_hurr_state)
    return {
        "enabled":         bool(cfg.get("enabled")),
        "alert_radius_km": cfg.get("alert_radius_km"),
        "min_level":       cfg.get("min_level"),
        "interval_min":    cfg.get("interval_min"),
        "bulletin_aprs":   bool(cfg.get("bulletin_aprs")),
        "ok":              st["ok"],
        "error":           st["error"],
        "ts":              st["ts"],
        "storms":          st["storms"],
    }


@app.route('/hurricane_status')
@_login_required
def hurricane_status():
    return json.dumps(_hurricane_status_payload(), ensure_ascii=False), 200, {'Content-Type': 'application/json'}


@app.route('/hurricane_config', methods=['POST'])
@_login_required
def hurricane_config():
    cfg = _hurr_cfg()
    d = request.get_json(force=True, silent=True) or {}
    was_enabled = bool(cfg.get("enabled"))
    if "enabled" in d:       cfg["enabled"] = bool(d["enabled"])
    if "bulletin_aprs" in d: cfg["bulletin_aprs"] = bool(d["bulletin_aprs"])
    if "min_level" in d and str(d["min_level"]).upper() in ("HU", "TS"):
        cfg["min_level"] = str(d["min_level"]).upper()
    for k in ("alert_radius_km", "interval_min"):
        if k in d:
            try: cfg[k] = max(0.0, float(d[k]))
            except (TypeError, ValueError): pass
    config_manager.data["hurricane_watch"] = cfg
    with open(os.path.join(BASE_DIR, "config.json"), "w") as f:
        json.dump(config_manager.data, f, ensure_ascii=False)
    if cfg["enabled"] and not was_enabled:
        _hurr_state["ts"] = 0.0      # consultation immédiate à l'activation
    return json.dumps(_hurricane_status_payload(), ensure_ascii=False), 200, {'Content-Type': 'application/json'}


@app.route('/hurricane_refresh', methods=['POST'])
@_login_required
def hurricane_refresh():
    """Consultation immédiate du NHC (sans alerte : simple mise à jour de l'affichage)."""
    _hurricane_refresh(alerts=False)
    return json.dumps(_hurricane_status_payload(), ensure_ascii=False), 200, {'Content-Type': 'application/json'}


