# ══════════════════════════════════════════════════════════════════════════════
# ── Marées par port (Open-Meteo Marine) ── TIDES_v1 ───────────────────────────
# Source : API marine Open-Meteo (gratuite, sans clé), champ sea_level_height_msl
# (niveau de la mer, marée comprise, par rapport au niveau moyen). Modèle global
# à maille d'environ 8 km : bon pour l'heure et le rythme des marées, moins précis
# dans les estuaires et les ports abrités. Ce n'est PAS une annonce du SHOM.
# ══════════════════════════════════════════════════════════════════════════════
# (id, nom, lat, lon) -- points légèrement au large pour tomber dans une maille marine
_TIDE_PORTS = [
    ("dunkerque",   "Dunkerque",             51.10,   2.35),
    ("calais",      "Calais",                51.00,   1.82),
    ("boulogne",    "Boulogne-sur-Mer",      50.75,   1.55),
    ("baie-somme",  "Baie de Somme",         50.25,   1.55),
    ("dieppe",      "Dieppe",                49.97,   1.07),
    ("fecamp",      "Fécamp",                49.78,   0.35),
    ("le-havre",    "Le Havre",              49.52,   0.05),
    ("honfleur",    "Honfleur (baie de Seine)", 49.45, 0.15),
    ("port-bessin", "Port-en-Bessin",        49.39,  -0.75),
    ("cherbourg",   "Cherbourg",             49.70,  -1.62),
    ("granville",   "Granville",             48.85,  -1.65),
    ("saint-malo",  "Saint-Malo",            48.70,  -2.05),
    ("perros",      "Perros-Guirec",         48.85,  -3.45),
    ("roscoff",     "Roscoff",               48.78,  -3.98),
    ("brest",       "Brest",                 48.35,  -4.55),
    ("douarnenez",  "Douarnenez",            48.12,  -4.40),
    ("concarneau",  "Concarneau",            47.82,  -3.92),
    ("lorient",     "Lorient",               47.68,  -3.42),
    ("quiberon",    "Quiberon",              47.45,  -3.12),
    ("st-nazaire",  "Saint-Nazaire",         47.22,  -2.30),
    ("yeu",         "Île d'Yeu",             46.72,  -2.40),
    ("sables",      "Les Sables-d'Olonne",   46.45,  -1.80),
    ("la-rochelle", "La Rochelle",           46.12,  -1.30),
    ("royan",       "Royan",                 45.60,  -1.20),
    ("arcachon",    "Arcachon",              44.60,  -1.30),
    ("biarritz",    "Biarritz",              43.50,  -1.65),
]
_TIDE_TTL = 1800
_tide_lock = threading.Lock()
_tide_cache = {}        # id -> (timestamp, payload)


def _tide_extrema(vals):
    """Pleines/basses mers (H/L) d'une série horaire : [type, indice fractionnaire, hauteur]."""
    raw = []
    n = len(vals)
    for i in range(1, n - 1):
        a, b, c = vals[i - 1], vals[i], vals[i + 1]
        if a is None or b is None or c is None:
            continue
        if b >= a and b > c:
            kind = "H"
        elif b <= a and b < c:
            kind = "L"
        else:
            continue
        den = a - 2.0 * b + c
        off = 0.5 * (a - c) / den if den else 0.0
        off = max(-0.5, min(0.5, off))
        raw.append([kind, i + off, b - 0.25 * (a - c) * off])
    seq = []                                   # alternance stricte H/L (garde le plus extrême)
    for e in raw:
        if seq and seq[-1][0] == e[0]:
            if (e[0] == "H" and e[2] > seq[-1][2]) or (e[0] == "L" and e[2] < seq[-1][2]):
                seq[-1] = e
        else:
            seq.append(e)
    out = []                                   # bruit : écart < 15 cm entre deux extrema voisins
    for e in seq:
        if out and abs(e[2] - out[-1][2]) < 0.15:
            out.pop()
            continue
        out.append(e)
    return out


def _tide_payload(port):
    import calendar
    pid, name, lat, lon = port
    now = time.time()
    with _tide_lock:
        hit = _tide_cache.get(pid)
    if hit and now - hit[0] < _TIDE_TTL:
        return hit[1]
    url = ("https://marine-api.open-meteo.com/v1/marine?latitude=%.4f&longitude=%.4f"
           "&hourly=sea_level_height_msl&past_days=1&forecast_days=4&timezone=auto") % (lat, lon)
    try:
        js = _sw_http_json(url, timeout=20)
        hr = js.get("hourly") or {}
        times = hr.get("time") or []
        vals = [None if v is None else float(v) for v in (hr.get("sea_level_height_msl") or [])]
        if not times or not any(v is not None for v in vals):
            raise RuntimeError("port hors de la maille du modèle marin")
        off = int(js.get("utc_offset_seconds") or 0)
        t0 = calendar.timegm(time.strptime(times[0], "%Y-%m-%dT%H:%M")) - off
        ext = []
        for kind, idx, h in _tide_extrema(vals):
            ts = int(t0 + 3600.0 * idx)
            lt = time.gmtime(ts + off)
            ext.append({"type": kind, "ts": ts, "h": round(h, 2),
                        "time": time.strftime("%H:%M", lt), "day": time.strftime("%d/%m", lt)})

        def level_at(t):
            x = (t - t0) / 3600.0
            i = int(x)
            if i < 0 or i + 1 >= len(vals) or vals[i] is None or vals[i + 1] is None:
                return None
            return vals[i] + (vals[i + 1] - vals[i]) * (x - i)

        cur = level_at(now)
        ahead = level_at(now + 1800)
        behind = level_at(now - 1800)
        state = None
        if ahead is not None and behind is not None:
            state = "montante" if ahead > behind else "descendante"
        nxt_h = next((e for e in ext if e["type"] == "H" and e["ts"] > now), None)
        nxt_l = next((e for e in ext if e["type"] == "L" and e["ts"] > now), None)
        payload = {
            "port": {"id": pid, "name": name, "lat": lat, "lon": lon},
            "now": int(now), "offset": off, "t0": int(t0), "step": 3600,
            "levels": [None if v is None else round(v, 2) for v in vals],
            "extrema": ext, "level_now": None if cur is None else round(cur, 2),
            "state": state, "next_high": nxt_h, "next_low": nxt_l,
            "source": "Open-Meteo Marine (modèle global ~8 km)",
        }
    except Exception as e:
        if hit:
            return hit[1]                      # donnée périmée plutôt que rien
        raise
    with _tide_lock:
        _tide_cache[pid] = (now, payload)
    return payload


@app.route('/tides_ports')
@_login_required
def tides_ports():
    lat, lon = _lightning_center()
    ports, best = [], None
    for pid, name, plat, plon in _TIDE_PORTS:
        d = _welcome_dist_km(lat, lon, plat, plon)
        ports.append({"id": pid, "name": name, "dist_km": int(round(d))})
        if best is None or d < best[0]:
            best = (d, pid)
    return json.dumps({"ports": ports, "nearest": best[1] if best else None},
                      ensure_ascii=False), 200, {'Content-Type': 'application/json'}


@app.route('/tides')
@_login_required
def tides_route():
    pid = (request.args.get("port") or "").strip()
    port = next((p for p in _TIDE_PORTS if p[0] == pid), None)
    if port is None:
        return json.dumps({"error": "port inconnu"}), 400, {'Content-Type': 'application/json'}
    try:
        return json.dumps(_tide_payload(port), ensure_ascii=False), 200, {'Content-Type': 'application/json'}
    except Exception as e:
        logger.warning("[MAREES] %s : %s", pid, e)
        return json.dumps({"error": str(e)[:160]}), 502, {'Content-Type': 'application/json'}


# ── FIN TIDES_v1 ──────────────────────────────────────────────────────────────

# ══════════════════════════════════════════════════════════════════════════════
# ── Prochaines grandes marées (coefficients) ── TIDES_SPRINGS_v1 ──────────────
# Coefficient de marée ESTIMÉ par synthèse harmonique : amplitude de la marée
# semi-diurne à Brest (référence du coefficient SHOM, échelle 20-120) à l'heure
# de chaque pleine mer, à partir des ondes M2, S2, N2, K2, T2, R2, nu2, 2N2, mu2
# et L2 (corrections nodales de M2/K2, retard de phase proportionnel à la
# fréquence). Les 7 paramètres ont été calés sur ~130 coefficients SHOM publiés
# (2015, août 2026 -> septembre 2027) : écart de 1 point en moyenne, 2 au plus
# dans la grande majorité des cas. Ce n'est PAS une annonce officielle ; pour un
# usage critique, voir maree.shom.fr.
# Les jours sont découpés en heure locale du système (Europe/Paris sur le Pi).
# ══════════════════════════════════════════════════════════════════════════════
_SPRING_MIN = 95      # épisode listé quand les deux marées du jour sont >= à ce coefficient
_SPRING_BIG = 100     # « grande marée » au sens SHOM / maree.info
# scale, tau (h, retard de phase), aS, aN, aK (admittances), gM (heure des pleines mers)
_COEF_P = (69.6716, 38.8517, 0.7179, 1.0187, 0.7255, 130.6827)
# (delta de vitesse /M2 en °/h, amplitude d'équilibre /M2, groupe d'admittance, nom)
_COEF_WAVES = (
    (1.015896, 0.459,  "S", "S2"),  (0.974829, 0.027,  "S", "T2"),  (1.056963, 0.0038, "S", "R2"),
    (-0.544374, 0.1915, "N", "N2"), (-0.471521, 0.0365, "N", "nu2"), (-1.088749, 0.0254, "N", "2N2"),
    (-1.015896, 0.0307, "N", "mu2"), (0.544375, 0.0275, "N", "L2"),  (1.098033, 0.126, "K", "K2"),
)


def _tide_astro(ts):
    import math as _m
    d = (ts - 946728000.0) / 86400.0                     # jours depuis J2000.0
    r = _m.radians
    s = r((218.3165 + 13.17639648 * d) % 360.0)          # longitude moyenne de la Lune
    h = r((280.4665 + 0.98564736 * d) % 360.0)           # longitude moyenne du Soleil
    p = r((83.3532 + 0.11140353 * d) % 360.0)            # périgée lunaire
    n = r((125.0445 - 0.05295377 * d) % 360.0)           # nœud ascendant (cycle de 18,6 ans)
    t = r(15.0 * (((d + 0.5) % 1.0) * 24.0) + 180.0)     # angle horaire du Soleil moyen
    return s, h, p, n, t


def _tide_coef_at(ts):
    """Coefficient (flottant, échelle SHOM) de la marée semi-diurne à l'instant ts."""
    import math as _m
    scale, tau, aS, aN, aK, _gM = _COEF_P
    adm = {"S": aS, "N": aN, "K": aK}
    s, h, p, n, _t = _tide_astro(ts)
    p1 = _m.radians(282.94)                              # périhélie
    fM = 1.0004 - 0.0373 * _m.cos(n) + 0.0002 * _m.cos(2 * n)
    uM = _m.radians(-2.14) * _m.sin(n)
    fK = 1.0241 + 0.2863 * _m.cos(n) + 0.0083 * _m.cos(2 * n)
    uK = _m.radians(-17.74) * _m.sin(n) + _m.radians(0.68) * _m.sin(2 * n)
    arg = {
        "S2": 2 * (s - h), "T2": -3 * h + 2 * s + p1, "R2": -h + 2 * s - p1 + _m.pi,
        "N2": -s + p, "nu2": -s + 2 * h - p, "2N2": -2 * s + 2 * p, "mu2": -2 * s + 2 * h,
        "L2": s - p + _m.pi, "K2": 2 * s + (uK - uM),
    }
    z = complex(fM, 0.0)
    for dv, ratio, grp, name in _COEF_WAVES:
        f = fK if name == "K2" else (1.0 if grp == "S" else fM)
        a = adm[grp] * ratio * f
        ph = arg[name] - _m.radians(dv * tau)
        z += a * complex(_m.cos(ph), _m.sin(ph))
    return scale * abs(z)


def _tide_hw_times(t0):
    """Pleines mers (M2) tombant dans la journée locale qui commence à t0 (epoch)."""
    import math as _m
    gM = _m.radians(_COEF_P[5])

    def _ph(t):
        _s, _h, _p, _n, _T = _tide_astro(t)
        return 2 * (_T + _h - _s) + _m.radians(-2.14) * _m.sin(_n) - gM

    t = t0 - 13 * 3600.0
    x = _ph(t) % (2 * _m.pi)
    t += ((2 * _m.pi - x) % (2 * _m.pi)) / _m.radians(28.984104) * 3600.0
    out = []
    while t < t0 + 86400.0 + 13 * 3600.0:
        if t0 <= t < t0 + 86400.0:
            out.append(t)
        t += 12.4206 * 3600.0
    return out


def _tide_coef_day(t0):
    """(matin, après-midi) : coefficients entiers de la journée locale commençant à t0."""
    hw = _tide_hw_times(t0)
    if not hw:
        hw = [t0 + 6 * 3600.0]
    t2 = hw[1] if len(hw) > 1 else hw[0] + 12.4206 * 3600.0
    clamp = lambda v: int(max(20, min(120, round(v))))
    return clamp(_tide_coef_at(hw[0])), clamp(_tide_coef_at(t2))


def _springs_payload(ndays):
    lt = time.localtime()
    days = []
    for i in range(ndays):
        t0 = time.mktime((lt.tm_year, lt.tm_mon, lt.tm_mday + i, 0, 0, 0, 0, 0, -1))
        am, pm = _tide_coef_day(t0)
        days.append({"date": time.strftime("%Y-%m-%d", time.localtime(t0)),
                     "am": am, "pm": pm, "max": max(am, pm), "lo": min(am, pm)})
    episodes, cur = [], None
    for dy in days:
        if dy["lo"] >= _SPRING_MIN:
            if cur is None:
                cur = {"start": dy["date"], "end": dy["date"], "peak": dy["max"],
                       "peak_date": dy["date"], "n": 0}
            cur["end"] = dy["date"]
            cur["n"] += 1
            if dy["max"] > cur["peak"]:
                cur["peak"], cur["peak_date"] = dy["max"], dy["date"]
        elif cur is not None:
            episodes.append(cur)
            cur = None
    if cur is not None:
        episodes.append(cur)
    return {"today": days[0]["date"] if days else None, "min": _SPRING_MIN, "big": _SPRING_BIG,
            "days": days, "episodes": episodes,
            "source": "Estimation astronomique (calée sur les coefficients SHOM)"}


@app.route('/tides_springs')
@_login_required
def tides_springs_route():
    try:
        nd = max(14, min(180, int(request.args.get("days", 60))))
    except Exception:
        nd = 60
    try:
        return json.dumps(_springs_payload(nd), ensure_ascii=False), 200, {'Content-Type': 'application/json'}
    except Exception as e:
        logger.warning("[MAREES] coefficients : %s", e)
        return json.dumps({"error": str(e)[:160]}), 500, {'Content-Type': 'application/json'}


# ══════════════════════════════════════════════════════════════════════════════
# ── Phases de la Lune ── MOON_PHASES_v1 ───────────────────────────────────────
# S'appuie sur _moon_position() (algorithme de P. Schlyter, sans dépendance).
# Phases / quartiers : recherche des passages de l'élongation Lune-Soleil par
# 0 / 90 / 180 / 270 degres (pas de 3 h puis bissection, precision ~ 1 minute).
# Perigee / apogee : precision ~ 1 h. Lever / coucher : precision ~ 2 min, sans
# correction de relief.
# ══════════════════════════════════════════════════════════════════════════════
_MOON_OCT_NAMES = ["Nouvelle lune", "Premier croissant", "Premier quartier", "Gibbeuse croissante",
                   "Pleine lune", "Gibbeuse décroissante", "Dernier quartier", "Dernier croissant"]
_MOON_OCT_EMOJI = ["🌑", "🌒", "🌓", "🌔", "🌕", "🌖", "🌗", "🌘"]
_MOON_EV_NAMES = ["Nouvelle lune", "Premier quartier", "Pleine lune", "Dernier quartier"]
_MOON_EV_EMOJI = ["🌑", "🌓", "🌕", "🌗"]
_moon_cache = {"key": None, "ts": 0.0, "data": None}
_moon_lock = threading.Lock()


def _moon_at(lat, lon, ts):
    from datetime import datetime as _dtm, timezone as _tzm
    return _moon_position(lat, lon, _dtm.fromtimestamp(ts, _tzm.utc))


def _moon_octant(elong):
    return int(((elong + 22.5) % 360.0) // 45.0)


def _moon_bisect(f, lo, hi, rising, n=14):
    """Instant ou f passe de <=0 a >0 (rising=True) ou de >0 a <=0 (rising=False)."""
    for _ in range(n):
        mid = (lo + hi) / 2.0
        if (f(mid) > 0) == rising:
            hi = mid
        else:
            lo = mid
    return (lo + hi) / 2.0


def _moon_events(lat, lon, now, back_days=32, fwd_days=45):
    """Nouvelles lunes, premiers quartiers, pleines lunes, derniers quartiers (kind 0..3)."""
    step = 3 * 3600.0
    t = now - back_days * 86400.0
    end = now + fwd_days * 86400.0
    prev = _moon_at(lat, lon, t)["elongation_deg"]
    out = []
    while t < end:
        t2 = t + step
        cur = _moon_at(lat, lon, t2)["elongation_deg"]
        k0 = int(prev // 90.0) % 4
        k1 = int(cur // 90.0) % 4
        if k1 != k0:
            boundary = k1 * 90.0
            f = lambda x, b=boundary: ((_moon_at(lat, lon, x)["elongation_deg"] - b + 180.0) % 360.0) - 180.0
            out.append({"kind": k1, "ts": _moon_bisect(f, t, t2, True)})
        prev, t = cur, t2
    return out


def _moon_apside(lat, lon, now, find_max):
    """Prochain apogee (find_max=True) ou perigee, dans les 33 jours."""
    step = 6 * 3600.0
    n = int(33 * 86400 / step)
    ts = [now + i * step for i in range(n + 1)]
    ds = [_moon_at(lat, lon, t)["distance_km"] for t in ts]
    sgn = -1.0 if find_max else 1.0
    g = lambda x: sgn * _moon_at(lat, lon, x)["distance_km"]
    for i in range(1, n):
        if sgn * ds[i] < sgn * ds[i - 1] and sgn * ds[i] <= sgn * ds[i + 1]:
            lo, hi = ts[i - 1], ts[i + 1]
            for _ in range(30):
                m1 = lo + (hi - lo) / 3.0
                m2 = hi - (hi - lo) / 3.0
                if g(m1) < g(m2):
                    hi = m2
                else:
                    lo = m1
            t0 = (lo + hi) / 2.0
            return {"ts": int(t0), "km": int(round(_moon_at(lat, lon, t0)["distance_km"]))}
    return None


def _moon_riseset(lat, lon, now, hours=40):
    """Prochain lever / coucher (altitude geocentrique ~ +0.1 degre, parallaxe et refraction comprises)."""
    thr = 0.1
    step = 600.0
    el = lambda t: _moon_at(lat, lon, t)["elevation_deg"] - thr
    rise = sett = None
    prev = el(now)
    for i in range(1, int(hours * 3600 / step) + 1):
        t2 = now + i * step
        cur = el(t2)
        if rise is None and prev <= 0 < cur:
            rise = int(_moon_bisect(el, t2 - step, t2, True, 10))
        elif sett is None and prev > 0 >= cur:
            sett = int(_moon_bisect(el, t2 - step, t2, False, 10))
        if rise is not None and sett is not None:
            break
        prev = cur
    return rise, sett


def _moon_ev_dec(e):
    return {"kind": e["kind"], "name": _MOON_EV_NAMES[e["kind"]],
            "emoji": _MOON_EV_EMOJI[e["kind"]], "ts": int(e["ts"])}


def _moon_payload(lat, lon):
    now = time.time()
    m = _moon_at(lat, lon, now)
    elong = m["elongation_deg"]
    idx = _moon_octant(elong)
    evs = _moon_events(lat, lon, now)
    past = [e for e in evs if e["ts"] <= now]
    fut = [e for e in evs if e["ts"] > now]
    last_new = next((e["ts"] for e in reversed(past) if e["kind"] == 0), None)
    rise, sett = _moon_riseset(lat, lon, now)

    ev_days = {}
    for e in evs:
        ev_days[time.strftime("%Y-%m-%d", time.localtime(e["ts"]))] = e["kind"]
    lt = time.localtime(now)
    days = []
    for i in range(30):
        t0 = time.mktime((lt.tm_year, lt.tm_mon, lt.tm_mday + i, 12, 0, 0, 0, 0, -1))
        md = _moon_at(lat, lon, t0)
        di = _moon_octant(md["elongation_deg"])
        key = time.strftime("%Y-%m-%d", time.localtime(t0))
        ek = ev_days.get(key)
        days.append({"date": key, "illum": md["illumination_pct"], "idx": di,
                     "emoji": _MOON_OCT_EMOJI[di], "name": _MOON_OCT_NAMES[di],
                     "event": ek, "event_name": _MOON_EV_NAMES[ek] if ek is not None else None})

    return {
        "ts": int(now), "lat": lat, "lon": lon, "south": lat < 0,
        "now": {"name": _MOON_OCT_NAMES[idx], "emoji": _MOON_OCT_EMOJI[idx], "idx": idx,
                "illum": m["illumination_pct"], "elong": elong, "waxing": elong < 180.0,
                "age_days": round((now - last_new) / 86400.0, 1) if last_new else None,
                "az": m["azimuth_deg"], "el": m["elevation_deg"],
                "dist_km": m["distance_km"], "visible": m["visible"]},
        "rise": rise, "set": sett,
        "events": [_moon_ev_dec(e) for e in fut[:4]],
        "last_event": _moon_ev_dec(past[-1]) if past else None,
        "perigee": _moon_apside(lat, lon, now, False),
        "apogee": _moon_apside(lat, lon, now, True),
        "days": days,
        "source": "Algorithme de Schlyter (calcul local, sans dependance externe)",
    }


