@app.route('/moon_disc.jpg')
@_login_required
def moon_disc_route():
    return Response(_MOON_DISC_JPG, mimetype='image/jpeg',
                    headers={'Cache-Control': 'public, max-age=86400'})


@app.route('/moon_phases')
@_login_required
def moon_phases_route():
    lat, lon = _lightning_center()
    key = (round(lat, 2), round(lon, 2), time.strftime("%Y%m%d"))
    hdr = {'Content-Type': 'application/json'}
    with _moon_lock:
        if _moon_cache["key"] == key and time.time() - _moon_cache["ts"] < 300:
            return json.dumps(_moon_cache["data"], ensure_ascii=False), 200, hdr
        try:
            data = _moon_payload(lat, lon)
        except Exception as e:
            logger.error("[LUNE] Calcul des phases : %s", e)
            return json.dumps({"error": str(e)[:160]}), 500, hdr
        _moon_cache.update({"key": key, "ts": time.time(), "data": data})
    return json.dumps(data, ensure_ascii=False), 200, hdr


