# ── FIN HURRICANE_WATCH_v1 ────────────────────────────────────────────────────

# ══════════════════════════════════════════════════════════════════════════════
# ── Veilles locales ── STATION_WATCH_v1 ───────────────────────────────────────
# Vigilance Météo-France (dépt), niveau des cours d'eau (Hub'Eau), séismes
# (EMSC), essaims de météores (calendrier), trafic 144.800 (trames/occupation),
# soleil/lune. Même modèle que HURRICANE_WATCH_v1 : worker daemon, alerte SSE
# "weather_alert" (bannière + bip) et bulletin RF optionnel (BLNWX3..BLNWX6).
# Toutes les sources sont désactivées par défaut (toggle dans l'onglet Météo).
# ══════════════════════════════════════════════════════════════════════════════
import urllib.request as _sw_ur
import urllib.parse as _sw_up
import datetime as _sw_dt
import math as _sw_math

_SW_DEFAULTS = {
    "vigilance": {"enabled": False, "dept": "37", "min_level": 3,   # 2 jaune, 3 orange, 4 rouge
                  "interval_min": 30, "bulletin_aprs": False},
    "rivers":    {"enabled": False, "interval_min": 15, "bulletin_aprs": False,
                  "stations": [{"code": "K490003010", "name": "Loire Tours", "alert_h_m": 3.0}]},
    "quakes":    {"enabled": False, "interval_min": 30, "radius_km": 500.0, "min_mag": 3.0,
                  "alert_mag": 3.5, "alert_radius_km": 300.0, "bulletin_aprs": False},
    "meteors":   {"enabled": False, "lead_days": 1, "bulletin_aprs": False},
}
_SW_BLN = {"meteors": 3, "quakes": 4, "rivers": 5, "vigilance": 6}
_SW_URL_VIGI = ("https://public.opendatasoft.com/api/explore/v2.1/catalog/datasets/"
                "weatherref-france-vigilance-meteo-departement/records")
# STATIONWATCH_FIX_v1 : API v1 arrêtée le 05/05/2025, v2 en service
_SW_URL_HUBEAU = "https://hubeau.eaufrance.fr/api/v2/hydrometrie"
_SW_URL_EMSC = "https://www.seismicportal.eu/fdsnws/event/1/query"
_SW_PHEN = {1: "Vent violent", 2: "Pluie-inondation", 3: "Orages", 4: "Crues", 5: "Neige-verglas",
            6: "Canicule", 7: "Grand froid", 8: "Avalanches", 9: "Vagues-submersion"}
_SW_LEVEL_TXT = {1: "vert", 2: "jaune", 3: "orange", 4: "rouge"}
_SW_COLORS = {
    "info":   ("#38bdf8", "#0c4a6e", "#bae6fd"),
    "yellow": ("#f59e0b", "#451a03", "#fcd34d"),
    "orange": ("#f97316", "#431407", "#fdba74"),
    "red":    ("#ef4444", "#450a0a", "#fca5a5"),
}
# (mois, jour du pic, nom, ZHR, note) -- pics approximatifs (+/- 1 jour), cf. IMO
_SW_SHOWERS = [
    (1, 3, "Quadrantides", 110, "pic tres bref"),
    (4, 22, "Lyrides", 18, ""),
    (5, 6, "Eta Aquarides", 50, "mieux vu vers l'aube"),
    (7, 30, "Delta Aquarides Sud", 25, ""),
    (8, 12, "Perseides", 100, "la plus populaire, MS 144 MHz tres actif"),
    (10, 8, "Draconides", 10, "tres variable"),
    (10, 21, "Orionides", 20, ""),
    (11, 5, "Taurides", 5, "peu nombreuses, bolides brillants"),
    (11, 17, "Leonides", 15, ""),
    (12, 14, "Geminides", 150, "la plus riche, MS 144 MHz tres actif"),
    (12, 22, "Ursides", 10, ""),
]

_sw_lock = threading.Lock()
_sw_state = {k: {"ts": 0.0, "ok": False, "error": "", "data": None} for k in _SW_DEFAULTS}
_sw_alert_last = {}
_sw_quake_seen = set()


def _sw_cfg():
    out = {}
    stored = config_manager.data.get("station_watch") or {}
    for k, d in _SW_DEFAULTS.items():
        c = json.loads(json.dumps(d))
        c.update(stored.get(k) or {})
        out[k] = c
    return out


def _sw_save(cfg):
    config_manager.data["station_watch"] = cfg
    with open(os.path.join(BASE_DIR, "config.json"), "w") as f:
        json.dump(config_manager.data, f, ensure_ascii=False)


def _sw_http_json(url, timeout=15):
    req = _sw_ur.Request(url, headers={"User-Agent": "Py-APRS/2.9 (F1RIQ)", "Accept": "application/json"})
    with _sw_ur.urlopen(req, timeout=timeout) as resp:
        raw = resp.read().decode("utf-8", "replace").strip()
        if resp.status == 204 or not raw:      # FDSN/EMSC : 204 = aucun résultat
            return {}
        return json.loads(raw)


def _sw_num(v, default=None):
    try:
        if v is None or v == "":
            return default
        return float(v)
    except (TypeError, ValueError):
        return default


def _sw_iso_ts(s):
    if not s:
        return None
    try:
        d = _sw_dt.datetime.fromisoformat(str(s).replace("Z", "+00:00"))
        if d.tzinfo is None:
            d = d.replace(tzinfo=_sw_dt.timezone.utc)
        return d.timestamp()
    except Exception:
        return None


def _sw_ascii(s):
    import unicodedata
    return unicodedata.normalize("NFKD", str(s)).encode("ascii", "ignore").decode("ascii")


def _sw_alert(src, key, icon, title, detail, color, bulletin, cooldown_s=3 * 3600, force=False):
    """Bannière SSE + bulletin RF optionnel, avec anti-spam par clé."""
    now = time.time()
    if not force and now - _sw_alert_last.get(key, 0) < cooldown_s:
        return False
    _sw_alert_last[key] = now
    bd, bg, tx = _SW_COLORS.get(color, _SW_COLORS["info"])
    frame = {"type": "weather_alert", "key": key, "icon": icon, "title": title, "detail": detail,
             "color_border": bd, "color_bg": bg, "color_text": tx,
             "temp_c": None, "wind_kmh": None, "description": None}
    for _q in list(listeners):
        try: _q.put_nowait(frame)
        except Exception: pass
    logger.warning("[WATCH-%s] %s — %s", src.upper(), key, title)
    if bulletin:
        _wx_send_aprs_bulletin(icon, _sw_ascii(title), detail, _SW_BLN.get(src, 3), force=True)
    return True


# ── Vigilance Météo-France (jeu Opendatasoft, sans clé) ──────────────────────
def _sw_fetch_vigilance(dept):
    last = None
    for params in ({"where": 'domain_id="%s"' % dept, "limit": 100},
                   {"refine": "domain_id:%s" % dept, "limit": 100}):
        try:
            js = _sw_http_json(_SW_URL_VIGI + "?" + _sw_up.urlencode(params))
            recs = js.get("results") or []
            if recs:
                return recs
        except Exception as e:
            last = e
    if last:
        raise last
    return []


def _sw_parse_vigilance(recs):
    now = time.time()
    per = {}
    seen_keys = set()
    for r in recs:
        f = r.get("fields") if isinstance(r.get("fields"), dict) else r
        seen_keys.update(f.keys())
        pid = _sw_num(f.get("phenomenon_id"))
        pid = int(pid) if pid is not None else None
        cid = _sw_num(f.get("color_id"))
        if cid is None:
            lab = str(f.get("color") or f.get("color_name") or "").lower()
            for k, v in _SW_LEVEL_TXT.items():
                if v in lab:
                    cid = k
        if cid is None:
            continue
        cid = int(cid)
        end = _sw_iso_ts(f.get("end_time"))
        if end is not None and end < now:
            continue
        name = (f.get("phenomenon") or f.get("phenomenon_name") or f.get("phenomenon_label")
                or _SW_PHEN.get(pid) or ("phenomene %s" % pid))
        begin = _sw_iso_ts(f.get("begin_time"))
        cur = per.get(name)
        if cur is None or cid > cur["level"]:
            per[name] = {"name": str(name), "pid": pid, "level": cid,
                         "level_txt": _SW_LEVEL_TXT.get(cid, str(cid)), "begin": begin, "end": end}
    items = sorted(per.values(), key=lambda x: -x["level"])
    if recs and not per:
        raise RuntimeError("champs inattendus dans le jeu vigilance : " + ", ".join(sorted(seen_keys))[:150])
    return {"max": max([i["level"] for i in items] or [1]), "items": items, "n": len(recs)}


def _sw_refresh_vigilance(cfg, alerts):
    dept = str(cfg.get("dept") or "37").strip()
    data = _sw_parse_vigilance(_sw_fetch_vigilance(dept))
    data["dept"] = dept
    if alerts and cfg.get("enabled"):
        for it in data["items"]:
            if it["level"] >= int(cfg.get("min_level", 3)):
                color = "red" if it["level"] >= 4 else ("orange" if it["level"] == 3 else "yellow")
                _sw_alert("vigilance", "vigi_%s_%s_%d" % (dept, it["name"], it["level"]), "⚠️",
                          "Vigilance %s %s (dept %s)" % (it["level_txt"], it["name"], dept),
                          "Météo-France — niveau %s" % it["level_txt"], color,
                          cfg.get("bulletin_aprs"), cooldown_s=6 * 3600)
    return data


# ── Niveau des cours d'eau (Hub'Eau / Vigicrues) ─────────────────────────────
def _sw_hubeau_obs(code, grandeur, size):
    url = _SW_URL_HUBEAU + "/observations_tr?" + _sw_up.urlencode(
        {"code_entite": code, "grandeur_hydro": grandeur, "size": size, "sort": "desc"})
    return _sw_http_json(url).get("data") or []


def _sw_refresh_rivers(cfg, alerts):
    rows = []
    for st in (cfg.get("stations") or []):
        code = str(st.get("code") or "").strip()
        if not code:
            continue
        row = {"code": code, "name": st.get("name") or code, "alert_h_m": _sw_num(st.get("alert_h_m"), 0.0),
               "h_m": None, "q_m3s": None, "date_obs": "", "trend_cm_h": None, "over": False, "error": ""}
        try:
            hs = _sw_hubeau_obs(code, "H", 12)
            if hs:
                h0 = _sw_num(hs[0].get("resultat_obs"))          # mm
                row["h_m"] = round(h0 / 1000.0, 3) if h0 is not None else None
                row["date_obs"] = str(hs[0].get("date_obs") or "")
                t0, t1 = _sw_iso_ts(hs[0].get("date_obs")), _sw_iso_ts(hs[-1].get("date_obs"))
                h1 = _sw_num(hs[-1].get("resultat_obs"))
                if None not in (h0, h1, t0, t1) and t0 - t1 >= 1800:
                    row["trend_cm_h"] = round((h0 - h1) / 10.0 / ((t0 - t1) / 3600.0), 1)
            qs = _sw_hubeau_obs(code, "Q", 1)
            if qs:
                q = _sw_num(qs[0].get("resultat_obs"))           # l/s
                row["q_m3s"] = round(q / 1000.0, 1) if q is not None else None
        except Exception as e:
            row["error"] = str(e)[:100]
        thr = row["alert_h_m"]
        row["over"] = bool(thr and row["h_m"] is not None and row["h_m"] >= thr)
        if alerts and cfg.get("enabled") and row["over"]:
            color = "red" if row["h_m"] >= thr * 1.25 else "orange"
            _sw_alert("rivers", "river_%s_%s" % (code, color), "🌊",
                      "Crue %s : %.2f m (seuil %.2f)" % (row["name"], row["h_m"], thr),
                      "Hub'Eau/Vigicrues", color, cfg.get("bulletin_aprs"))
        rows.append(row)
    if rows and all(r["error"] and r["h_m"] is None for r in rows):
        raise RuntimeError(rows[0]["error"])
    return {"stations": rows}


# ── Séismes récents (EMSC / seismicportal.eu) ────────────────────────────────
def _sw_refresh_quakes(cfg, alerts):
    lat, lon = _lightning_center()
    radius = max(10.0, _sw_num(cfg.get("radius_km"), 500.0))
    start = (_sw_dt.datetime.now(_sw_dt.timezone.utc) - _sw_dt.timedelta(days=7)).strftime("%Y-%m-%dT%H:%M:%S")
    url = _SW_URL_EMSC + "?" + _sw_up.urlencode({
        "format": "json", "lat": round(lat, 3), "lon": round(lon, 3), "minradius": 0,
        "maxradius": round(radius / 111.19, 3), "minmag": _sw_num(cfg.get("min_mag"), 3.0),
        "start": start, "limit": 30, "orderby": "time"})
    js = _sw_http_json(url)
    now = time.time()
    events = []
    for ft in (js.get("features") or []):
        p = ft.get("properties") or {}
        elat, elon = _sw_num(p.get("lat")), _sw_num(p.get("lon"))
        if elat is None or elon is None:
            continue
        ts = _sw_iso_ts(p.get("time"))
        dist = _welcome_dist_km(lat, lon, elat, elon)
        events.append({"id": str(p.get("unid") or ft.get("id") or ""), "mag": _sw_num(p.get("mag")),
                       "region": str(p.get("flynn_region") or "?"), "depth": _sw_num(p.get("depth")),
                       "ts": ts, "dist_km": int(round(dist)),
                       "bearing_txt": _hurr_compass(_lightning_bearing_deg(lat, lon, elat, elon))})
    events.sort(key=lambda e: -(e["ts"] or 0))
    if alerts and cfg.get("enabled"):
        first_run = not _sw_quake_seen
        for e in events:
            if e["id"] in _sw_quake_seen:
                continue
            _sw_quake_seen.add(e["id"])
            recent = e["ts"] and now - e["ts"] < 3 * 3600
            if (not first_run or recent) and recent and e["mag"] is not None \
                    and e["mag"] >= _sw_num(cfg.get("alert_mag"), 3.5) \
                    and e["dist_km"] <= _sw_num(cfg.get("alert_radius_km"), 300.0):
                _sw_alert("quakes", "quake_" + e["id"], "🌍",
                          "Seisme M%.1f %s a %d km" % (e["mag"], e["region"], e["dist_km"]),
                          "EMSC — profondeur %s km" % (e["depth"] if e["depth"] is not None else "?"),
                          "orange" if e["mag"] >= 4.5 else "yellow", cfg.get("bulletin_aprs"),
                          cooldown_s=24 * 3600)
    else:
        for e in events:
            _sw_quake_seen.add(e["id"])
    return {"events": events[:10], "n": len(events), "radius_km": radius}


# ── Essaims de météores (calendrier statique) ────────────────────────────────
def _sw_refresh_meteors(cfg, alerts):
    today = _sw_dt.date.today()
    rows = []
    for mo, dy, name, zhr, note in _SW_SHOWERS:
        peak = _sw_dt.date(today.year, mo, dy)
        if peak < today:
            peak = _sw_dt.date(today.year + 1, mo, dy)
        rows.append({"name": name, "peak": peak.strftime("%d/%m"), "days": (peak - today).days,
                     "zhr": zhr, "note": note, "year": peak.year})
    rows.sort(key=lambda r: r["days"])
    if alerts and cfg.get("enabled"):
        lead = int(_sw_num(cfg.get("lead_days"), 1))
        for r in rows:
            if r["days"] <= lead:
                when = "aujourd'hui" if r["days"] == 0 else "demain" if r["days"] == 1 else "dans %d j" % r["days"]
                _sw_alert("meteors", "meteor_%s_%d_%d" % (r["name"], r["year"], r["days"]), "☄️",
                          "Pic %s %s (ZHR %d)" % (r["name"], when, r["zhr"]),
                          "Meteor scatter 144 MHz favorable, surtout vers 6h locale", "info",
                          cfg.get("bulletin_aprs"), cooldown_s=20 * 3600)
    return {"showers": rows[:4]}


# ── Trafic 144.800 : trames décodées et occupation estimée ───────────────────
_fs_lock = threading.Lock()
_fs_frames = collections.deque()   # (ts, bits, src)


def _fs_record(frame):
    """Appelé par _rx_broadcaster pour chaque trame RF décodée."""
    try:
        if frame.get("type") in ("tx_event", "rx_level") or frame.get("_source") == "IS" or not frame.get("src"):
            return
        path = frame.get("path") or ""
        ndigi = len([p for p in str(path).split(",") if p])
        nbytes = 16 + 7 * ndigi + len(frame.get("payload") or "")
        now = time.time()
        with _fs_lock:
            _fs_frames.append((now, nbytes * 8 * 1.1, str(frame.get("src"))))   # 1.1 = bit stuffing
            cutoff = now - 86400
            while _fs_frames and _fs_frames[0][0] < cutoff:
                _fs_frames.popleft()
    except Exception:
        pass


def _fs_payload():
    now = time.time()
    with _fs_lock:
        snap = list(_fs_frames)
    out = {}
    for label, win in (("h1", 3600), ("h24", 86400)):
        sel = [f for f in snap if f[0] >= now - win]
        bits = sum(f[1] for f in sel)
        out[label] = {"frames": len(sel), "stations": len({f[2] for f in sel}),
                      "occupancy_pct": round(min(100.0, bits / 1200.0 / win * 100.0), 2)}
    out["note"] = "occupation estimée (durée des trames à 1200 bauds, hors préambule)"
    return out


# ── Soleil / lune (lever, coucher, durée du jour, phase) ─────────────────────
def _sw_sun_times(lat, lon, d):
    n = d.timetuple().tm_yday
    g = 2 * _sw_math.pi / 365.0 * (n - 1)
    eq = 229.18 * (0.000075 + 0.001868 * _sw_math.cos(g) - 0.032077 * _sw_math.sin(g)
                   - 0.014615 * _sw_math.cos(2 * g) - 0.040849 * _sw_math.sin(2 * g))
    dec = (0.006918 - 0.399912 * _sw_math.cos(g) + 0.070257 * _sw_math.sin(g) - 0.006758 * _sw_math.cos(2 * g)
           + 0.000907 * _sw_math.sin(2 * g) - 0.002697 * _sw_math.cos(3 * g) + 0.00148 * _sw_math.sin(3 * g))
    la = _sw_math.radians(lat)
    x = _sw_math.cos(_sw_math.radians(90.833)) / (_sw_math.cos(la) * _sw_math.cos(dec)) - _sw_math.tan(la) * _sw_math.tan(dec)
    if x >= 1 or x <= -1:
        return None
    ha = _sw_math.degrees(_sw_math.acos(x))
    rise_utc = 720 - 4 * (lon + ha) - eq
    set_utc = 720 - 4 * (lon - ha) - eq
    base = _sw_dt.datetime(d.year, d.month, d.day, tzinfo=_sw_dt.timezone.utc)
    return (base + _sw_dt.timedelta(minutes=rise_utc), base + _sw_dt.timedelta(minutes=set_utc), 2 * ha * 4 / 60.0)


@app.route('/sun_moon_info')
@_login_required
def sun_moon_info():
    try:
        lat, lon = _lightning_center()
        today = _sw_dt.date.today()
        t = _sw_sun_times(lat, lon, today)
        y = _sw_sun_times(lat, lon, today - _sw_dt.timedelta(days=1))
        out = {"sunrise": None, "sunset": None, "day_len": None, "day_delta_min": None}
        if t:
            out["sunrise"] = t[0].astimezone().strftime("%H:%M")
            out["sunset"] = t[1].astimezone().strftime("%H:%M")
            out["day_len"] = "%dh%02d" % (int(t[2]), int(round((t[2] % 1) * 60)) % 60)
            if y:
                out["day_delta_min"] = round((t[2] - y[2]) * 60, 1)
        try:
            sun = _sun_position(lat, lon)
            out["sun_el"] = round(sun["elevation_deg"], 1)
            out["sun_phase"] = sun["phase_name"]
            moon = _moon_position(lat, lon)
            out["moon"] = {"pct": round(moon["phase_pct"]), "name": moon["phase_name"],
                           "emoji": moon["phase_emoji"], "visible": moon["visible"]}
        except Exception as _e:
            logger.debug("[WATCH] soleil/lune : %s", _e)
        return json.dumps(out, ensure_ascii=False), 200, {'Content-Type': 'application/json'}
    except Exception as e:
        return json.dumps({"error": str(e)}), 500, {'Content-Type': 'application/json'}


# ── Orchestration ────────────────────────────────────────────────────────────
_SW_FUNCS = {"vigilance": _sw_refresh_vigilance, "rivers": _sw_refresh_rivers,
             "quakes": _sw_refresh_quakes, "meteors": _sw_refresh_meteors}


def _sw_refresh(src, alerts=True):
    cfg = _sw_cfg()[src]
    try:
        data = _SW_FUNCS[src](cfg, alerts)
        with _sw_lock:
            _sw_state[src].update({"ok": True, "error": "", "ts": time.time(), "data": data})
    except Exception as e:
        with _sw_lock:
            _sw_state[src].update({"ok": False, "error": str(e)[:200], "ts": time.time()})
        logger.warning("[WATCH-%s] Échec : %s", src.upper(), e)


def _sw_worker():
    while True:
        try:
            cfgs = _sw_cfg()
            for src, cfg in cfgs.items():
                if not cfg.get("enabled"):
                    continue
                interval = 3600.0 if src == "meteors" else max(5.0, _sw_num(cfg.get("interval_min"), 30.0)) * 60.0
                if time.time() - _sw_state[src]["ts"] >= interval:
                    _sw_refresh(src)
        except Exception as _e:
            logger.error("[WATCH] Erreur worker : %s", _e)
        time.sleep(20)


threading.Thread(target=_sw_worker, daemon=True, name="station-watch-worker").start()
logger.info("[WATCH] Worker veilles locales démarré (sources inactives tant que non activées)")


def _sw_status_payload():
    cfg = _sw_cfg()
    with _sw_lock:
        st = {k: dict(v) for k, v in _sw_state.items()}
    return {"cfg": cfg, "state": st, "traffic": _fs_payload()}


