@app.route('/station_watch_config', methods=['POST'])
@_login_required
def station_watch_config():
    d = request.get_json(force=True, silent=True) or {}
    cfg = _sw_cfg()
    newly = []
    for src, patch in d.items():
        if src not in cfg or not isinstance(patch, dict):
            continue
        was = bool(cfg[src].get("enabled"))
        for k, v in patch.items():
            if k not in _SW_DEFAULTS[src]:
                continue
            ref = _SW_DEFAULTS[src][k]
            if k == "stations":
                if isinstance(v, list):
                    cfg[src][k] = [{"code": str(s.get("code", "")).strip()[:12],
                                    "name": str(s.get("name", ""))[:40],
                                    "alert_h_m": _sw_num(s.get("alert_h_m"), 0.0)}
                                   for s in v if isinstance(s, dict) and s.get("code")]
            elif isinstance(ref, bool):
                cfg[src][k] = bool(v)
            elif isinstance(ref, (int, float)):
                n = _sw_num(v)
                if n is not None:
                    cfg[src][k] = max(0.0, n) if isinstance(ref, float) else int(max(0, n))
            else:
                cfg[src][k] = str(v).strip()[:20]
        if cfg[src].get("enabled") and not was:
            newly.append(src)
    _sw_save(cfg)
    for src in newly:
        _sw_state[src]["ts"] = 0.0      # consultation immédiate à l'activation
    return json.dumps(_sw_status_payload(), ensure_ascii=False), 200, {'Content-Type': 'application/json'}


