# ══════════════════════════════════════════════════════════════════════════════
# ── Carte des nuages (Meteosat MTG / EUMETSAT) ── CLOUD_MAP_v1 ────────────────
# Le navigateur charge les tuiles WMS directement chez EUMETSAT ; le serveur
# fournit seulement la position de la station et l'heure de la dernière image
# disponible (lue dans le GetCapabilities du WMS, cache 5 min).
# ══════════════════════════════════════════════════════════════════════════════
_CLOUD_BASE = "https://view.eumetsat.int/geoserver"
_CLOUD_LAYER = "mtg_fd:ir105_hrfi"       # couche de référence pour l'heure (pas 10 min)
_cloud_lock = threading.Lock()
_cloud_cache = {"ts": 0.0, "latest": "", "latest_ms": 0, "error": ""}


def _cloud_http_get(url, timeout=20):
    import urllib.request
    req = urllib.request.Request(url, headers={"User-Agent": "Py-APRS/3.0 (F1RIQ)"})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return resp.read().decode("utf-8", "replace")


def _cloud_parse_latest(xml_text, layer_name=None):
    """Extrait l'attribut default (= dernière image) de la dimension 'time' du GetCapabilities."""
    import re as _re
    txt = xml_text or ""
    if layer_name:
        i = txt.find("<Name>%s</Name>" % layer_name)
        if i < 0:
            return ""
        txt = txt[i:]
    m = _re.search(r'<Dimension[^>]*name="time"[^>]*default="([^"]+)"', txt)
    return m.group(1) if m else ""


def _cloud_iso_to_ms(iso):
    import datetime as _dt
    d = _dt.datetime.strptime(iso[:19], "%Y-%m-%dT%H:%M:%S").replace(tzinfo=_dt.timezone.utc)
    return int(d.timestamp() * 1000)


def _cloud_latest():
    """(iso, ms, erreur) de la dernière image MTG. Cache 5 min (60 s après un échec)."""
    now = time.time()
    with _cloud_lock:
        c = dict(_cloud_cache)
    ttl = 300.0 if c["latest"] else 60.0
    if c["ts"] and now - c["ts"] < ttl:
        return c["latest"], c["latest_ms"], c["error"]
    latest, err = "", ""
    ws, name = _CLOUD_LAYER.split(":")
    urls = [
        # 1) capacités limitées à la couche (léger)  2) capacités globales (lourd, repli)
        ("%s/%s/%s/ows?service=WMS&version=1.3.0&request=GetCapabilities" % (_CLOUD_BASE, ws, name), None),
        ("%s/wms?service=WMS&version=1.3.0&request=GetCapabilities" % _CLOUD_BASE, _CLOUD_LAYER),
    ]
    for url, lname in urls:
        try:
            latest = _cloud_parse_latest(_cloud_http_get(url), lname)
            if latest:
                _cloud_iso_to_ms(latest)          # validation du format
                break
        except Exception as e:
            err = str(e)[:160]
            latest = ""
    ms = _cloud_iso_to_ms(latest) if latest else 0
    if not latest and not err:
        err = "heure de la dernière image introuvable"
    with _cloud_lock:
        _cloud_cache.update({"ts": now, "latest": latest, "latest_ms": ms, "error": err})
    if err:
        logger.warning("[NUAGES] EUMETView : %s", err)
    return latest, ms, err


# (ancienne route /clouds_info EUMETSAT retirée : remplacée par la version OWM plus bas)


# ── Carte des nuages v4 : tuiles OpenWeatherMap (proxy serveur) ── CLOUD_OWM_v2_TILES
# Le navigateur demande /clouds_tile/<couche>/<z>/<x>/<y>.png ; le serveur ajoute la clé
# (config["owm_key"]) et relaie la tuile OpenWeatherMap, avec un cache mémoire de 10 min.
# La clé n'est donc jamais visible dans le navigateur.
_CT_LAYERS = ("clouds_new", "precipitation_new")
_CT_TTL = 600
_CT_MAX = 800
_ct_cache = {}                       # (couche, z, x, y) -> (timestamp, octets PNG)
_ct_lock = threading.Lock()
_ct_err = {"msg": None, "ts": 0.0}


def _ct_set_err(msg):
    with _ct_lock:
        _ct_err["msg"] = msg
        _ct_err["ts"] = time.time()


@app.route('/clouds_info')
@_login_required
def clouds_info():
    lat, lon = _lightning_center()
    with _ct_lock:
        err = _ct_err["msg"] if (_ct_err["msg"] and time.time() - _ct_err["ts"] < 900) else None
    return jsonify({"lat": lat, "lon": lon,
                    "has_key": bool((config_manager.data.get("owm_key") or "").strip()),
                    "last_error": err})


@app.route('/clouds_tile/<layer>/<int:z>/<int:x>/<int:y>.png')
@_login_required
def clouds_tile(layer, z, x, y):
    if layer not in _CT_LAYERS or not (0 <= z <= 10) or not (0 <= x < (1 << z)) or not (0 <= y < (1 << z)):
        return "", 404
    appid = (config_manager.data.get("owm_key") or "").strip()
    if not appid:
        _ct_set_err("clé OpenWeatherMap manquante (Configuration)")
        return "", 404
    ck = (layer, z, x, y)
    now = time.time()
    with _ct_lock:
        hit = _ct_cache.get(ck)
    if hit and now - hit[0] < _CT_TTL:
        return hit[1], 200, {'Content-Type': 'image/png', 'Cache-Control': 'private, max-age=300'}
    import urllib.request as _ur
    import urllib.error as _ue
    url = "https://tile.openweathermap.org/map/%s/%d/%d/%d.png?appid=%s" % (layer, z, x, y, appid)
    try:
        req = _ur.Request(url, headers={"User-Agent": "Py-APRS/3.0 (F1RIQ)"})
        with _ur.urlopen(req, timeout=15) as resp:
            data = resp.read()
    except _ue.HTTPError as e:
        if e.code == 401:
            _ct_set_err("clé OpenWeatherMap refusée (401) — une clé neuve peut mettre jusqu'à 2 h à s'activer")
        elif e.code == 429:
            _ct_set_err("quota OpenWeatherMap dépassé (429)")
        else:
            _ct_set_err("OpenWeatherMap : HTTP %d" % e.code)
        if hit:                                    # tuile périmée > rien
            return hit[1], 200, {'Content-Type': 'image/png', 'Cache-Control': 'private, max-age=60'}
        return "", 502
    except Exception as e:
        _ct_set_err("OpenWeatherMap injoignable : %s" % str(e)[:80])
        if hit:
            return hit[1], 200, {'Content-Type': 'image/png', 'Cache-Control': 'private, max-age=60'}
        return "", 502
    with _ct_lock:
        _ct_cache[ck] = (now, data)
        _ct_err["msg"] = None
        if len(_ct_cache) > _CT_MAX:
            for k in sorted(_ct_cache, key=lambda q: _ct_cache[q][0])[:_CT_MAX // 4]:
                _ct_cache.pop(k, None)
    return data, 200, {'Content-Type': 'image/png', 'Cache-Control': 'private, max-age=300'}


# ── RADAR_RV_v1 : radar de précipitations RainViewer (images passées) ─────────────────────
# API gratuite depuis le 01/01/2026 : images passées uniquement (pas de prévision), zoom 7 max,
# ~100 requêtes/min/IP. Le serveur relaie les tuiles, les met en cache (une image passée ne change
# plus) et limite son débit vers RainViewer.
_RV_HOST = "https://tilecache.rainviewer.com"
_RV_FRAMES_N = 8
_RV_INFO = {"ts": 0.0, "frames": [], "host": _RV_HOST, "err": None}
_RV_TILES = {}
_RV_REQS = collections.deque()
_RV_LOCK = threading.Lock()


def _rv_frames():
    """Dernières images radar : ([{time, path}], host). Rafraîchi toutes les 2 min au plus."""
    now = time.time()
    with _RV_LOCK:
        if now - _RV_INFO["ts"] < 120 and _RV_INFO["frames"]:
            return list(_RV_INFO["frames"]), _RV_INFO["host"]
    try:
        raw = _pp_get_json("https://api.rainviewer.com/public/weather-maps.json", timeout=12)
        past = (raw.get("radar") or {}).get("past") or []
        frames = []
        for f in past[-_RV_FRAMES_N:]:
            path = str(f.get("path") or "")
            # RADAR_RV_FIX_v1 : RainViewer a changé le format des chemins -> à utiliser tels quels ;
            # on vérifie seulement qu'ils sont sûrs (pas de « .. », pas de caractère inattendu)
            if _re.fullmatch(r"/[A-Za-z0-9_./~-]{1,160}", path) and ".." not in path:
                try:
                    frames.append({"time": int(f["time"]), "path": path.rstrip("/")})
                except (KeyError, TypeError, ValueError):
                    continue
        host = str(raw.get("host") or _RV_HOST)
        if not _re.fullmatch(r"https://([a-z0-9-]+\.)*rainviewer\.com", host):
            host = _RV_HOST
        if not frames:
            logger.warning("[RADAR] aucune image exploitable : %d image(s) brute(s), exemple=%s",
                           len(past), (past[-1] if past else None))
        with _RV_LOCK:
            _RV_INFO.update({"ts": now, "frames": frames, "host": host,
                             "err": None if frames else "aucune image radar disponible"})
        return list(frames), host
    except Exception as e:
        with _RV_LOCK:
            _RV_INFO["err"] = "RainViewer injoignable : %s" % str(e)[:80]
            _RV_INFO["ts"] = now - 90          # nouvel essai dans 30 s
            return list(_RV_INFO["frames"]), _RV_INFO["host"]


def _rv_throttle(max_per_min=80, max_wait=25.0):
    """Limiteur : au plus max_per_min requêtes amont par minute (attend jusqu'à max_wait s)."""
    t0 = time.time()
    while True:
        with _RV_LOCK:
            now = time.time()
            while _RV_REQS and now - _RV_REQS[0] > 60:
                _RV_REQS.popleft()
            if len(_RV_REQS) < max_per_min:
                _RV_REQS.append(now)
                return True
        if time.time() - t0 > max_wait:
            return False
        time.sleep(0.4)


@app.route('/radar_info')
@_login_required
def radar_info():
    lat, lon = _lightning_center()
    frames, _host = _rv_frames()
    with _RV_LOCK:
        err = _RV_INFO["err"]
    return jsonify({"lat": lat, "lon": lon, "frames": [f["time"] for f in frames], "error": err,
                    "sample": (_host + frames[-1]["path"]) if frames else None})


@app.route('/radar_tile/<int:ts>/<int:z>/<int:x>/<int:y>.png')
@_login_required
def radar_tile(ts, z, x, y):
    if not (0 <= z <= 7) or not (0 <= x < (1 << z)) or not (0 <= y < (1 << z)):
        return "", 404
    frames, host = _rv_frames()
    fr = next((f for f in frames if f["time"] == ts), None)
    if not fr:
        return "", 404
    ck = (ts, z, x, y)
    with _RV_LOCK:
        hit = _RV_TILES.get(ck)
    hdr = {'Content-Type': 'image/png', 'Cache-Control': 'private, max-age=3600'}
    if hit:
        return hit, 200, hdr
    if not _rv_throttle():
        return "", 429
    import urllib.request as _ur
    import urllib.error as _ue
    url = "%s%s/256/%d/%d/%d/2/1_1.png" % (host, fr["path"], z, x, y)     # 2 = Universal Blue, 1_1 = lissé + neige
    try:
        req = _ur.Request(url, headers={"User-Agent": "Py-APRS/3.0"})
        with _ur.urlopen(req, timeout=15) as resp:
            data = resp.read()
    except _ue.HTTPError as e:
        with _RV_LOCK:
            _RV_INFO["err"] = "RainViewer : HTTP %d%s" % (e.code, " (limite de requêtes)" if e.code == 429 else "")
        logger.warning("[RADAR] tuile refusée HTTP %d : %s", e.code, url)
        return "", 502
    except Exception as e:
        with _RV_LOCK:
            _RV_INFO["err"] = "RainViewer injoignable : %s" % str(e)[:80]
        logger.warning("[RADAR] tuile injoignable : %s (%s)", url, e)
        return "", 502
    with _RV_LOCK:
        _RV_TILES[ck] = data
        _RV_INFO["err"] = None
        if len(_RV_TILES) > 1200:
            for k in list(_RV_TILES)[:300]:     # dict ordonné : on retire les plus anciennes
                _RV_TILES.pop(k, None)
    return data, 200, hdr


